window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-preventiva-pre-2"]={"block":"medcurso:medcurso-preventiva-pre-2","label":"Medcurso · PRE 2","count":464,"questions":[{"id":"medcurso-preventiva-pre-2-343799","number":"343799","sourceNumber":"343799","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Estudos epidemiológicos são importantes para a construção e consolidação de\nevidências em saúde, o que é importante fator\nque guia as condutas médicas de forma geral. Na\nMedicina Baseada em Evidências existem níveis de evidência conforme o poder dos desenhos de\nestudo epidemiológicos. Nessa perspectiva, qual das opções abaixo contêm os desenhos de\nestudo capazes de gerar o maior nível de evidências?","options":{"A":"Estudos transversais e revisões integrativas.","B":"Estudos de coorte e caso controle.","C":"Estudos qualitativos e estudos ecológicos.","D":"Ensaios clínicos e metanálises."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-343804","number":"343804","sourceNumber":"343804","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"As medidas de acurácia de testes diagnósticos são importantes para a tomada de\ndecisão clínica por parte dos médicos. Sobre as medidas de acurácia que medem a validade dos\ntestes, assinale abaixo a alternativa correta.","options":{"A":"Saber a especificidade de um teste é importante para medir a sua reprodutibilidade ou precisão\n(confiabilidade) diante do diagnóstico de determinada doença.","B":"A curva ROC é uma representação gráfica do Valor Preditivo Positivo (eixo Y) em relação ao\nValor Preditivo Negativo (eixo X).","C":"A sensibilidade de um teste é a probabilidade de um teste dar positivo na presença de\ndeterminada doença.","D":"A razão de verossimilhança é a razão entre a probabilidade de um resultado de um teste\ndiagnóstico em indivíduos sem a doença da doença e a probabilidade do mesmo resultado em\nindivíduos portadores da doença."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-247209","number":"247209","sourceNumber":"247209","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Você vai iniciar sua vida profissional no município de Colares-AL de 20 000 habitantes,\nna única Unidade Básica de Saúde da cidade\nque está organizada segundo a estratégia de saúde\nda família. O município apresenta índice de envelhecimento de 115% e proporção (%) da neonatal\nsobre a mortalidade infantil total de 20%. O secretário municipal da saúde solicita sua opinião\nsobre\na compra de um novo teste diagnóstico para o diabete melito. O desempenho do novo teste,\ndivulgado na última edição de um renomado jornal científico internacional, impressiona. O valor\npreditivo positivo foi de 97%, comparado com 80% do teste antigo. A probabilidade de a diferença\nter ocorrido por acaso foi de P<0,001. Você decide","options":{"A":"Calcular a incidência de diabetes na população de Colares.","B":"Indicar a compra, respaldado na estrutura populacional.","C":"Descarta a compra, por que a diferença não apresentou significância estatística.","D":"Propor um estudo de base populacional para estimar a prevalência de diabetes.","E":"Ler o artigo em busca da prevalência de diabetes na população do estudo."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-247211","number":"247211","sourceNumber":"247211","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"As variáveis etnias, peso corporal (kg) e número de irmãos são, respectivamente,","options":{"A":"Qualitativa Ordinal, quantitativa contínua e quantitativa discreta.","B":"Qualitativa nominal, quantitativa contínua e quantitativa discreta.","C":"Qualitativa nominal, quantitativa discreta e quantitativa discreta.","D":"Qualitativa nominal, quantitativa contínua e quantitativa intervalar.","E":"Qualitativa ordinal, quantitativa contínua e quantitativa intervalar."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-247212","number":"247212","sourceNumber":"247212","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Ao afirmar que a estimativa, por intervalo com 95% de confiança, da prevalência de\nhipertensão, entre adultos residentes em um determinado município, é de 25% a 35% o\npesquisador quer dizer que","options":{"A":"Ele aceita a hipótese de que a prevalência seja baixa, com 95% de confiança.","B":"A prevalência de hipertensão foi estimada com confiança.","C":"Não existe confiança na estimativa dessa prevalência.","D":"Ele rejeita a hipótese de que a prevalências seja baixa, com 95% de confiança.","E":"Em 95% das vezes que repetisse esse estudo com amostra de mesmo tamanho, encontraria\nvalores dessa prevalência entre 25% a 35%."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-247213","number":"247213","sourceNumber":"247213","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A representação gráfica da distribuição dos pacientes internados em determinado\nhospital em 2019 por faixa etária deve ser\nfeita por","options":{"A":"Histograma ou polígono de frequências.","B":"Barra ou pizza.","C":"Setores circulares.","D":"Barra ou histograma.","E":"Setores circulares ou polígono de frequências."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-247224","number":"247224","sourceNumber":"247224","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale a alternativa correta em relação a validação de critério em teste diagnósticos.","options":{"A":"A magnitude dos valores da sensibilidade e a da especificidade de um teste são diretamente\nproporcionais.","B":"Especificidade do teste é o percentual de acerto do teste entre os testes negativos.","C":"As curvas denominadas \"\"Curvas ROC - Curvas de Características de Operação do Receptor\"\"\ndemonstram a variação dos valores do Valor Preditivo Positivo do teste de acordo com a\nprevalência da doença.","D":"Para a decisão de adoção de um teste para screening, o valor mais importante a ser\nconsiderado é o preditivo positivo.","E":"A razão de verossimilhança do teste mede a probabilidade pré-teste de uma determinada\ndoença."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-247225","number":"247225","sourceNumber":"247225","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere um estudo de coorte sobre a associação entre um determinado tipo de\ncirurgia ocular e a ocorrência de acidentes\nautomobilísticos. Para isso, decidiu-se investigar dois\ngrupos, um de 175 motoristas que passaram pelo procedimento cirúrgico (C+) e outro de 105\nmotoristas sem história de cirurgia ocular (C-). O seguimento desses dois grupos de indivíduos\ncomputou 25 acidentes em 2 500 000 quilômetros dirigidos em C+ e 20 acidentes em 2 500 000\nquilômetros dirigidos em C-. Assumindo que os grupos são comparáveis em suas características, a\nalternativa que exprime, respectivamente, a medida de associação mais indicada e o seu valor\naproximado é:","options":{"A":"Razão de taxas de incidência: 0,56.","B":"Risco atribuível: 0,21.","C":"Razão de odds: 0,41.","D":"Razão de proporções de incidências: 0,76.","E":"Taxa de prevalências: 0,75."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-247234","number":"247234","sourceNumber":"247234","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo mostra a comparação de duas curvas ROC (Receiving Operating\nCharacteristic) para o diagnóstico de diabete\nmelito. Qual dos testes você escolheria para usar na\npratica diária?","options":{"A":"O teste cuja curva seja mais próxima de 50%.","B":"O teste cuja curva mais se aproxime do canto superior direito.","C":"O teste cuja curva mais se aproxime da diagonal do gráfico.","D":"O teste cuja curva tenha sido construída levando-se em consideração quanto tempo cada\nindivíduo participou do estudo.","E":"O teste cuja área em baixo da curva seja maior."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-247237","number":"247237","sourceNumber":"247237","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Ainda que arbitrário, é um procedimento comum o estabelecimento de intervalos de\nreferência utilizando o intervalo central que comporta 95% dos resultados obtidos de uma\npopulação composta de indivíduos assumidamente normais. Por esse critério de \"normalidade\",\nqual a chance de um indivíduo normal ter um resultado alterado?","options":{"A":"1 em 10.","B":"1 em 5.","C":"1 em 20.","D":"1 em 95.","E":"1 em 100."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-183147","number":"183147","sourceNumber":"183147","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale a alternativa CORRETA. Uma investigação simultaneamente realizada em\ndois grupos de indivíduos, um grupo com\nportadores de uma dada patologia e outro sem a mesma\npatologia, pareados por diversas variáveis, entre elas a idade, o sexo e a ocupação, indagou sobre\na presença ou a ausência de uma série de fatores relacionados com a patologia ao longo dos\núltimos 10 anos. Trata-se de um estudo:","options":{"A":"Caso e controles.","B":"Transversal.","C":"Coorte controlada.","D":"Ensaio clínico.","E":"Estudo ecológico."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-183221","number":"183221","sourceNumber":"183221","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale a alternativa CORRETA. Em bioestatística, é denominada como\nestatisticamente significativa a associação entre duas variáveis, quando:","options":{"A":"As variáveis apresentam uma relação que pode ser considerada relevante em termos clínicos ou\npopulacionais.","B":"Um dos fatores analisados pode ser considerado como causa do outro","C":"Foi observada no contexto de um ensaio clínico randomizado, no qual todos os possíveis fatores\nque influenciam a associação foram devidamente\ncontrolados.","D":"Os valores de uma variável dependem dos valores da outra, havendo uma situação de\ndependência estatísticas entre elas.","E":"a probabilidade de que esta associação tenha ocorrido ao acaso seja menor do que algum valor\ncrítico previamente definido como, por exemplo, 5% ou 1%."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-183225","number":"183225","sourceNumber":"183225","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale a alternativa CORRETA. Diversos parâmetros biológicos, entre eles o peso e a\naltura dos indivíduos, apresentam comportamento semelhante ao que se costuma rotular, em\nbioestatística, como distribuição normal. São propriedades da distribuição normal:","options":{"A":"Ter forma simétrica e apresentar média, mediana e moda com valores semelhantes.","B":"Apresentar área constante sob a curva, que impede o cálculo de probabilidades relacionadas à\nocorrência de observações situadas em alguma faixa de valor.","C":"Permitir, para os parâmetros que possuem distribuição normal, o cálculo de diferenças de\nmédias a partir de testes estatísticos não paramétricos.","D":"Refletir a distribuição de parâmetros ou variáveis, que se apresentam altamente concentrados\nem uma parcela da população, como a renda\nfamiliar.","E":"Ter sua distribuição completamente determinada pela mediana e pelo desvio-padrão."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-183227","number":"183227","sourceNumber":"183227","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale a alternativa CORRETA. O valor de p (probabilidade) e o intervalo de\nconfiança são recursos estatísticos que permitem:","options":{"A":"Avaliar se a pesquisa foi realizada com rigor, definindo a qualidade dos resultados obtidos.","B":"Extrapolar ou generalizar os resultados observados em uma amostra para alguma população de\nreferência.","C":"Identificar se os fatores de risco investigados em uma pesquisa são, de fato, as verdadeiras\ncausas da doença em questão.","D":"Conferir se os testes estatísticos empregados no estudo estão corretos.","E":"Examinar se as variáveis analisadas são categóricas ou numéricas."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-159037","number":"159037","sourceNumber":"159037","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"No ano de 1982 teve início em Pelotas, Rio Grande do Sul, um estudo de saúde\nperinatal que incluiu todos os nascimentos\nocorridos no ano. Um dos objetivos foi conhecer o peso\ndo bebê ao nascimento e sua associação com mortalidade infantil ao final do primeiro ano de vida.\nAs crianças eram classificadas em dois grupos: peso normal (? 2.500 g) e baixo peso (< 2.500 g).\nAo final do primeiro ano, comparou-se a taxa de mortalidade infantil entre os dois grupos. Qual foi\no\ntipo de delineamento de estudo dessa pesquisa?","options":{"A":"Ensaio clínico randomizado.","B":"Estudo de casos e controles.","C":"Estudo de coorte.","D":"Estudo ecológico."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-84542","number":"84542","sourceNumber":"84542","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"No Brasil, a Portaria nº 648 GM/2006, que aprova a Política Nacional de Atenção\nBásica, estabelece a revisão de diretrizes e\nnormas para a organização da Atenção Básica para o\nPrograma Saúde da Famíla (PSF) e o Programa Agentes Comunitários de Saúde (PACS). Sobre\nAtenção Básica, considere as seguintes afirmativas: 1. É um conjunto de ações de saúde, no\nâmbito individual e coletivo, que abrange a promoção e a proteção da saúde, a prevenção de\nagravos, o diagnóstico, o tratamento, a reabilitação e a manutenção da saúde. 2. É desenvolvida\npor meio do exercício de práticas gerenciais e sanitárias democráticas e participativas, sob forma\nde trabalho em equipe, dirigidas a populações de territórios bem delimitados, pelas quais assume a\nresponsabilidade sanitária, considerando a dinamicidade existente no território em que vivem essas\npopulações. 3. Utiliza tecnologias de elevada complexidade e baixa densidade, que devem resolver\nos problemas de saúde de maior frequência e relevância em seu território. 4. É o contato\npreferencial dos usuários com os sistemas de saúde. Assinale a alternativa correta.","options":{"A":"Somente as afirmativas 2 e 3 são verdadeiras.","B":"Somente as afirmativas 2, 3 e 4 são verdadeiras.","C":"Somente as afirmativas 1 e 4 são verdadeiras.","D":"Somente as afirmativas 1, 2 e 3 são verdadeiras.","E":"As afirmativas 1, 2, 3 e 4 são verdadeiras."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-343226","number":"343226","sourceNumber":"343226","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Mesmo numa fase de escalada da variante Ômicron, quando novos questionamentos\npodem surgir sobre os riscos versus benefícios da\nvacinação em crianças e adolescentes jovens,\numa série de estudos publicados mais recentemente concluíram que a vacinação com RNAm\n(particularmente BNT162b2):","options":{"A":"Especialmente quando não reforçada com uma terceira dose, permanece altamente eficaz\ncontra formas graves da COVID-19, incluindo morte.","B":"Especialmente quando reforçada com uma terceira dose, permanece altamente eficaz contra\nformas graves da COVID-19, incluindo morte.","C":"Especialmente quando reforçada com uma terceira dose, não permanece altamente eficaz\ncontra formas graves da COVID-19, incluindo morte.","D":"Especialmente quando reforçada com uma terceira dose, permanece altamente eficaz contra\nformas graves da COVID-19, excluindo morte."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-343231","number":"343231","sourceNumber":"343231","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A cultura para micobactérias de material respiratório apresenta sensibilidade em torno\nde 80% e especificidade de 98%. Sendo correto\nque:","options":{"A":"Os métodos para cultura que utilizam a semeadura em meios líquidos, como o\n\nLöwenstein-Jensen e não o Ogawa-Kudoh, são os mais comumente utilizados por apresentarem a\nvantagem de ter menor custo e um baixo índice de contaminação.","B":"Os métodos para cultura que utilizam a semeadura em meios sólidos, como o\n\nLöwenstein-Jensen e o Ogawa-Kudoh, são os mais comumente utilizados por apresentarem a\nvantagem de ter maior custo e um elevado índice de contaminação.","C":"Os métodos para cultura que utilizam a semeadura em meios sólidos, como o\n\nLöwenstein-Jensen e o Ogawa-Kudoh, são os mais comumente utilizados por apresentarem a\nvantagem de ter menor custo e um baixo índice de contaminação.","D":"Os métodos para cultura que não utilizam a semeadura em meios sólidos, como o\nLöwenstein-Jensen e o Ogawa-Kudoh, são os mais comumente utilizados por apresentarem a\nvantagem de ter menor custo e um baixo índice de contaminação."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-276012","number":"276012","sourceNumber":"276012","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em 2020, pesquisadores de uma universidade do nordeste brasileiro decidiram iniciar\numa análise do efeito do aleitamento materno na\nocorrência de morte neonatal. Para isso,\ndecidiram alocar os indivíduos elegíveis em dois grupos em uma proporção 1:2: os que morreram e\nutilizaram o aleitamento materno e os que não morreram e utilizaram o aleitamento materno. Os\npesquisadores aplicaram um questionário em todas as mães dos indivíduos elegíveis dos dois\ngrupos. A coleta abrangeu óbitos e nascimentos ocorridos entre 2015 e 2019. Em relação a esse\nprojeto hipotético, assinale a alternativa INCORRETA.","options":{"A":"Trata-se de um estudo caso-controle.","B":"O principal e provável viés desse estudo é o de memória, uma vez que se trata de um estudo\nobservacional longitudinal retrospectivo.","C":"Por se tratar de um estudo de meta-análise, fica dispensada a apreciação pelo Comitê de Ética\nem Pesquisa.","D":"A medida de associação a ser utilizada neste estudo provavelmente será o Odds Ratio.","E":"O tipo do estudo em questão permite avaliar vários fatores de risco ao mesmo tempo."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-276013","number":"276013","sourceNumber":"276013","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um ensaio clínico hipotético, o medicamento de cor vermelha mostrou-se eficaz em\nrelação ao medicamento de cor azul (p < 0,05). Entretanto, ao iniciarem a submissão do estudo a\numa revista científica, os pesquisadores perceberam que cometeram um erro. Após refazerem os\ncálculos, eles verificaram que a hipótese nula é verdadeira. Que tipo de erro é esse?","options":{"A":"Erro tipo II.","B":"Erro beta.","C":"Viés de memória.","D":"Viés de confusão.","E":"Erro alfa."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-276014","number":"276014","sourceNumber":"276014","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um grupo de pesquisadores decidiu realizar um estudo observacional sobre a relação\nentre o uso excessivo de aparelhos\neletrônicos (técnica para diagnóstico hipotético) e a presença\nde miopia em indivíduos de uma cidade hipotética. Dos 135 indivíduos analisados, 70 faziam uso\nexcessivo de aparelhos eletrônicos (teste positivo) e eram míopes. Sabendo que 60 indivíduos não\neram míopes e que os verdadeiro-negativos são 20 indivíduos, responda as questões 48 a 50. Qual\no valor do Odds Ratio dessa associação?","options":{"A":"OR = 5,0.","B":"OR = 12,0.","C":"OR = 10,0.","D":"OR = 2,0.","E":"OR = 7,0."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-283759","number":"283759","sourceNumber":"283759","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em março de 2020 a Organização Mundial de Saúde informou que a situação da\ndoença causada pelo Coronavírus no mundo havia\nganhado proporções de pandemia. Desde\nentão, todos os esforços mundiais têm sido no desenvolvimento de vacinas eficazes contra o\n\nSars-Cov-2. O Brasil tem participado efetivamente desse esforço. Os princípios de produção vacinal\ne de imunização são diversos. A despeito de\nnão termos ainda formas de imunização ativa, temos\nempregado no Brasil a imunização passiva para tratamento da COVID-19. Um ensaio clínico fase III\nde um fármaco se caracteriza por:","options":{"A":"Verificar eficiência do fármaco, comparando com tratamento convencional ou placebo.","B":"Verificar a ausência de efeitos colaterais com uso em populações larga escala.","C":"Testar a segurança do fármaco em pequenos grupos.","D":"Verificar a eficiência do fármaco, após a liberação comercial."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-252941","number":"252941","sourceNumber":"252941","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"\"O uso de drogas, na atualidade, é uma preocupação mundial. Entre 2000 e 2015,\nhouve um crescimento de 60% no número de\nmortes causadas diretamente pelo uso de drogas,\nsendo este dado o recorte de apenas uma das consequências do problema. Tal condição extrapola\nas questões individuais e se constitui como um grave problema de saúde pública, com reflexos nos\ndiversos segmentos da sociedade. Os serviços de segurança pública, educação, saúde, sistema de\njustiça, assistência social, dentre outros, e os espaços familiares e sociais são repetidamente\nafetados, direta ou indiretamente, pelos reflexos e pelas consequências do uso das drogas.\"\nBRASIL, Presidência da República, DECRETO LEI Nº 9.761, DE ABRIL DE 2019, publicado no\nDOU em 11/04/2019. Os dados citados no Decreto Lei 9.761, de abril de 2019, foram obtidos pelo II\nLevantamento Nacional de Álcool e Drogas (LENAD) - 2012, que pesquisou o uso de drogas na\npopulação brasileira. Para a realização desse levantamento foi considerada uma \"amostragem\nprobabilística\". Esse termo significa que a seleção dos entrevistados.","options":{"A":"foi feita de forma aleatória, expressando o acaso.","B":"buscou uma representatividade da população geral.","C":"utilizou a probabilidade do uso prévio de drogas.","D":"eliminou a possibilidade de erro amostral."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-212138","number":"212138","sourceNumber":"212138","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A probabilidade de que um paciente selecionado, aleatoriamente, entre os pacientes de\numa Equipe de Saúde da Família tenha um\nresultado negativo nos testes diagnósticos (teste rápido\npara sífilis, hepatite ou HIV, por exemplo), se realmente não tem a doença, é denominada","options":{"A":"sensibilidade.","B":"especificidade.","C":"valor preditivo negativo.","D":"proporção de falsos positivos.","E":"proporção de falsos negativos."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-219866","number":"219866","sourceNumber":"219866","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Estudo realizado com médicos residentes do Hospital de Clínicas de Porto Alegre\n(HCPA), no período de dezembro de 2015 a\njaneiro de 2016, mediante aplicação de um\ninstrumento informatizado que contém dois questionários: um com variáveis sociodemográficas e o\nquestionário Maslach Burnout Inventory (MBI). De 506 médicos residentes do HCPA, 151\nparticiparam voluntariamente do estudo. Burnout esteve presente em 123 participantes (81,5%).\n\nEsta modalidade de estudo pode ser classificada como:","options":{"A":"Ensaio clínico.","B":"Estudo de caso controle.","C":"Estudo de coorte.","D":"Estudo transversal."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-219877","number":"219877","sourceNumber":"219877","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"1.000 médicos realizaram uma prova nacional para obtenção de título em uma\nespecialidade médica. Um candidato foi informado que seu desempenho 68 (de 100 pontos)\ncorrespondeu ao percentil 75. Isto significa que:","options":{"A":"25% dos estudantes tiraram 75 ou menos.","B":"250 candidatos tiraram 75 ou mais.","C":"250 estudantes tiraram 68 ou mais.","D":"75% dos candidatos tiraram 68 ou mais."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-219878","number":"219878","sourceNumber":"219878","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Qual das estatísticas mencionadas a seguir é MENOS afetada pelos valores extremos?","options":{"A":"Amplitude.","B":"Desvio-padrão.","C":"Mediana.","D":"Qui-quadrado."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-219886","number":"219886","sourceNumber":"219886","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Num estudo, foram recrutadas 30 pessoas com certo tipo de câncer de intestino (grupo\nX) e 90 pessoas sem essa doença (grupo Y).\nTodas responderam a um questionário que revelou:\nno grupo X, 30% foram expostos a um determinado fator de interesse e no grupo Y, 20%. O valor\nbruto da medida de associação mais apropriada entre exposição e feito foi:","options":{"A":"OR = 0,58.","B":"OR = 1,71.","C":"RR = 1,48.","D":"RR = 1,50."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-212182","number":"212182","sourceNumber":"212182","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um ensaio clínico realizado em 2.100 pacientes hipertensos tratados com dois tipos\nde medicamentos (?A? e ?B?) obtiveram-se os seguintes resultados: no grupo tratado com o\nmedicamento ?A?, uma diminuição média da pressão arterial sistólica de 46 mmHg; no grupo\ntratado com o medicamento ?B?, a diminuição média observada do mesmo parâmetro foi de 47\nmmHg. No estudo estatístico de comparação entre as duas médias, obteve-se um p-valor < 0,60.\n\nSe o custo econômico do tratamento com o medicamento ?A? é 28% maior que com o\nmedicamento ?B?, é CORRETO afirmar que o medicamento ?A? tem:","options":{"A":"A mesma eficácia, mas é menos eficiente que o ?B?.","B":"A mesma eficácia, mas é mais eficiente que o ?B?.","C":"A mesma eficácia e a mesma eficiência que o ?B?.","D":"Maior eficácia, mas é menos eficiente que o ?B?.","E":"Menor eficácia, mas é mais eficiente que o ?B?."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-180120","number":"180120","sourceNumber":"180120","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Para a investigação de associações etiológicas em doenças de baixa incidência qual\ndos estudos abaixo é o mais indicado?","options":{"A":"Coorte.","B":"Ecológico.","C":"Caso-controle.","D":"Secional.","E":"Ensaio clínico randomizado."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-181303","number":"181303","sourceNumber":"181303","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Selecionamos uma amostra aleatória entre os pacientes que foram receber a vacina da\ngripe durante a campanha anual na unidade básica de saúde. Foi aplicado um questionário para\nesses pacientes com perguntas sobre a utilização de medicamentos para dislipidemias, se são\nportadores de diabetes mellitus, entre outros dados. Como resultado, obteve-se que o diabetes\nmellitus é mais frequente entre os pacientes que tomam medicamentos para dislipidemias que entre\nos que não tomam. A qual dos seguintes corresponde o desenho desse estudo?","options":{"A":"Um estudo ecológico.","B":"Um estudo transversal.","C":"Um ensaio clínico randomizado.","D":"Um estudo de casos e controles.","E":"Um estudo de coorte prospectivo."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-181367","number":"181367","sourceNumber":"181367","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uns pesquisadores realizam um estudo com pacientes coronariopatas provenientes de\numa unidade hospitalar especializada em\ncoronariopatias. A aplicação dos resultados do estudo a\npacientes de uma consulta de medicina de família e comunidade pode ser errada por um problema\nde","options":{"A":"precisão.","B":"confundimento.","C":"validade externa.","D":"validade interna.","E":"viés de classificação."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-181378","number":"181378","sourceNumber":"181378","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A terapia prescrita para uma doença tem como meta a melhora de seu curso clínico, o\nque pode significar a melhora de sintomas já\nmanifestados ou a prevenção de outros ainda\nlatentes. Alcançar essa meta, contudo, nem sempre é fácil. O processo pode ser prejudicado pelos\nefeitos indesejáveis do tratamento e por seu custo financeiro. Prescrever ou não um determinado\ntratamento depende, pois, do balanço adequado entre benefício e risco/custo, julgado a partir das\nevidências clínico-epidemiológicas (DUNCAN, 2006, p. 50). Dadas as afirmativas, I. Evidências de\neficácia são geralmente demonstradas por ensaios clínicos randomizados. II. A efetividade é a\nevidência de que a intervenção funciona em condições experimentais rigorosas. III. O benefício\nterapêutico somente pode ser avaliado por medidas absolutas. IV. As medidas absolutas resultam\nda divisão entre os riscos do grupo experimental e do grupo-controle. verifica-se que está(ão)\ncorreta(s)","options":{"A":"I, apenas.","B":"I e IV, apenas.","C":"II e III, apenas.","D":"III e IV, apenas.","E":"I, II, III e IV."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-187743","number":"187743","sourceNumber":"187743","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Com relação aos estudos epidemiológicos de Coorte, é CORRETO afirmar:","options":{"A":"Envolvem o registro de dados sobre exposição e doença para as mesmas pessoas em pelo\nmenos dois pontos do tempo","B":"São realizados com dados secundários provenientes de grandes bases de dados","C":"Se iniciam com a identificação do total de casos provindos de uma população, seguida da\nseleção de uma fração dos não casos, que servirá de base para comparações ou referência","D":"Trata-se de estudos nos quais a variação de tempo não é importante para o pesquisador"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-181386","number":"181386","sourceNumber":"181386","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Dadas as afirmativas quanto à validade de um Teste Diagnóstico, I. Sensibilidade é a\ncapacidade de o teste acertar em indivíduos com aquela doença. II. Especificidade é a capacidade\nde o teste acertar em indivíduos sem aquela doença. III. Testes sensíveis têm poucos\n\nfalsos-negativos.IV. Testes específicos têm poucos falsos-positivos. verifica-se que estão corretas","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e IV, apenas.","D":"III e IV, apenas.","E":"I, II, III e IV."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-161373","number":"161373","sourceNumber":"161373","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Estudos brasileiros que avaliaram o impacto de polimorfismos genéticos na população\nnão conseguiram identificar um padrão mais\nprevalente. Mostraram forte impacto da miscigenação,\ndificultando ainda mais a identificação de um padrão genético para a elevação dos níveis\npressóricos. Esse estudo se referia à população:","options":{"A":"de idosos.","B":"de mulheres.","C":"quilombolas.","D":"de obesos."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-131362","number":"131362","sourceNumber":"131362","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Nas investigações de campo que utilizam estudos de incidência, a associação entre os\nfatores de risco e a ocorrência de doenças deve ser avaliada através de:","options":{"A":"Risco Absoluto.","B":"Odds Ratio.","C":"Risco Relativo.","D":"Razão de Prevalência.","E":"Razão de Incidência."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-131366","number":"131366","sourceNumber":"131366","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Através do banco de dados da Secretaria Municipal de Saúde, uma pesquisa levantou\na prevalência de tuberculose em Maceió e fatores\nassociados. Este é um exemplo de um estudo:","options":{"A":"Caso-controle.","B":"Ecológico.","C":"Transversal Individual.","D":"Coorte.","E":"Experimental."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-131370","number":"131370","sourceNumber":"131370","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um pesquisador acompanhou um grupo de adultos saudáveis por 20 anos. Os\nparticipantes foram alocados em dois subgrupos de acordo com os níveis de ingestão diária de\ngorduras saturadas. Ao final do estudo, verificou-se a diferença na incidência de doenças\ncoronarianas de acordo com a presença de fatores de risco. Este é um exemplo de um estudo:","options":{"A":"Caso-controle.","B":"Ecológico.","C":"Transversal individual.","D":"Coorte.","E":"Experimental."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134341","number":"134341","sourceNumber":"134341","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um pesquisador investigou a hipótese da associação entre o uso de cotonetes e otites.\nForam estudados 100 pacientes que usaram cotonetes e 100 pacientes que não usaram cotonetes\npor 10 dias. Avaliou-se, subsequentemente, a frequência de otite sem cada grupo. Qual é o tipo de\ndelineamento desse estudo?","options":{"A":"Estudo de coorte.","B":"Estudo de casos e controles.","C":"Ensaio clínico randomizado.","D":"Estudo ecológico."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134263","number":"134263","sourceNumber":"134263","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Para avaliação de 120 pacientes, quanto a incidênciade câncer de próstata, foram\nrealizados os métodosde toque retal (padrão) e PSA, obtendo-se os dados da tabela (VER\nIMAGEM): Assinale a alternativa CORRETA:","options":{"A":"Sensibilidade ? 0,15","B":"Especificidade ? 0,80","C":"Valor Preditivo Positivo ? 0,50","D":"Valor Preditivo Negativo ? 0,90"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134297","number":"134297","sourceNumber":"134297","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Estudos de caso-controle são estudos epidemiológicos observacionais,\nlongitudinais e analíticos. Um estudo de\ncaso-controle foi conduzido por Sartor et al. para se\ndeterminar fatores de risco ocupacionais para o câncer de laringe. (Cad. Saúde Pública, 2007, v.\n23, n. 6.) A tabela faz parte dos resultados desse estudo. (VER IMAGEM) De acordo com o\nresultado desse estudo, o nível de consumo de álcool significativamente associado com câncer de\nlaringe foi de:","options":{"A":"Até 270 (gramas/ano).","B":"> 270-890 (gramas/ano).","C":"> 890-1.940 (gramas/ano).","D":"> 1.940 (gramas/ano)."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134111","number":"134111","sourceNumber":"134111","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na investigação descrita a seguir, procurou-se examinar o papel da deficiência\nmaterna de folato para o desenvolvimento de malformação congênita de tubo neural. Foram\nincluídos 80 recém-nascidos (RN) com má formação de tubo neural e 160 RN sem esta má\nformação. Encontrou-se deficiência de folato em 20 mães de RN com má formação congênita de\ntubo neural e em 16 mães de RN sem esta má formação. Acerca disso, indique a alternativa\nCORRETA.","options":{"A":"O oddsratio (?razão de chances?) de má formação congênita de tubo neural associado à\ndeficiência materna de folato foi 3,0.","B":"O risco relativo de má formação congênita de tubo neural associado à deficiência materna de\nfolato foi 1,9.","C":"O risco relativo de má formação congênita de tubo associado à deficiência materna de folato foi\n1,1.","D":"Nas mães com deficiência de folato, o risco atribuível de má formação congênita de tubo neural\nfoi 26%."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134101","number":"134101","sourceNumber":"134101","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O diagnóstico definitivo da influenza pelo vírus H1N1 pode ser feito pelos métodos de\nbiologia molecular (PCR) com maior precisão. Ensaios de detecção antigênica (Elisa e\nImunofluorescência) diferenciam entre influenza A e B somente. Um teste positivo para\ninfluenza A não diferencia influenza sazonal (H3 ou H1) da infecção pela influenza H1N1. A\nsensibilidade do ensaio de detecção antigênica para detectar influenza H1N1 não é ainda\nconhecida. Testes comerciais rápidos de detecção antigênica que usam swabs de garganta ou\nnariz estão disponíveis e podem fornecer um resultado em 15?30 minutos. O teste rápido\ngeralmente tem uma sensibilidade de 60 a 80% comparado com a cultura do vírus. Assim, um\nteste negativo não exclui influenza. A sensibilidade desses testes sugere que o teste rápido é\nmenos útil onde a probabilidade pré-teste é alta (isto é, durante a fase de transmissão sustentada\nde uma pandemia estabelecida). Com base na informação acima, assinale a alternativa em que a\nafirmação esteja INCORRETA.","options":{"A":"Em épocas não epidêmicas (com baixa circulação do vírus da influenza), o valor preditivo\nnegativo do teste rápido será mais alto.","B":"Em épocas epidêmicas, o valor preditivo positivo do teste rápido será mais alto.","C":"Em épocas epidêmicas (de maior circulação do vírus da influenza), não se terá tanta certeza em\ncaso de exames negativos de não se tratar\nde infecção pelo vírus da influenza, pois 20 a 40% dos\ncasos de influenza serão falsos negativos.","D":"A utilização do teste rápido permite dizer que 60 a 80% dos casos com testes positivos são\nefetivamente de influenza."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134316","number":"134316","sourceNumber":"134316","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A epidemiologia pode ser compreendida como um processo contínuo de acúmulo de\nconhecimentos com o objetivo de prover um acervo de evidências científicas para subsidiar a\nmelhor tomada de decisão na área de saúde. A epidemiologia descritiva constitui a primeira etapa\nda utilização dos métodos epidemiológicos de investigação para se compreender o comportamento\nde um agravo à saúde numa população.","options":{"A":"Utilizam um grupo de comparação para o cálculo de medidas de associação.","B":"Inclui relato de caso, série de casos e estudos de prevalência.","C":"São úteis para se calcular incidência a partir de exposições raras.","D":"Permitem identificar fatores associados ao risco de se desenvolver uma doença."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134853","number":"134853","sourceNumber":"134853","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Após aplicar o bafômetro em motoristas, que sabidamente tinham ou não teor alcoólico\nno sangue, obteve-se o seguinte resultado: A\npartir do quadro ABAIXO, assinale a alternativa\nCORRETA (VER IMAGEM).","options":{"A":"A sensibilidade do teste foi de 89,0%.","B":"A acurácia do teste foi de 81,0%.","C":"A prevalência de álcool foi de 76,0%.","D":"O valor preditivo negativo do teste foi de 50,0%."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134859","number":"134859","sourceNumber":"134859","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo conduzido em Papua ? Nova Guiné verificou-se que, de 66 casos de\nenterocolite necrotizante, 50 haviam consumido, recentemente, carne crua. Dos 52 que não tiveram\na doença, 11 haviam consumido. Assinale a alternativa CORRETA.","options":{"A":"O risco foi de 431 por mil.","B":"O risco atribuível foi de 368 por mil.","C":"A razão de chances foi de 11,6.","D":"O risco relativo foi de 174 por mil."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134865","number":"134865","sourceNumber":"134865","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os ensaios clínicos randomizados são, geralmente, utilizados para","options":{"A":"A vigilância epidemiológica de doenças de interesse da Saúde Pública.","B":"Testar a eficácia de tratamentos.","C":"Identificar causas de doenças.","D":"Melhorar a acurácia de testes diagnósticos."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-109797","number":"109797","sourceNumber":"109797","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Qual é a principal medida de associação estimada em estudos caso-controle?","options":{"A":"Incidência.","B":"Prevalência.","C":"Risco relativo.","D":"Razão de chances."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-109803","number":"109803","sourceNumber":"109803","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Observe os seguintes critérios. I. Ter valor preditivo positivo baixo. II. Ser sensível o\nsuficiente para detectar a doença no período assintomático. III. Ser aceitável pelos pacientes e\nclínicos. IV. Ser específico o suficiente para reduzir o número de falso positivo. Para o\nrastreamento\nde doenças, um teste necessita preencher os critérios essenciais, que estão presentes, APENAS,\nnos itens:","options":{"A":"II, III e IV.","B":"I, II e III.","C":"II e IV.","D":"I e III."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-109807","number":"109807","sourceNumber":"109807","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A especificidade de um teste laboratorial diz respeito à capacidade desse teste fornecer\num resultado negativo, quando:","options":{"A":"o valor preditivo do teste for muito baixo.","B":"o indivíduo testado for portador da doença em questão.","C":"a sensibilidade do teste for elevada.","D":"o indivíduo testado não for portador da doença em questão."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-109812","number":"109812","sourceNumber":"109812","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na decisão de escolha do antibiótico a ser prescrito para uma criança com\ninfecção urinária, o Médico deve avaliar o\npadrão de sensibilidade da bactéria isolada na\nurocultura. Considerando somente as estimativas do Risco Relativo (RR), intervalo de confiança de\n95% (IC95%) e o NNT - número necessário para tratar, obtidos em ensaios clínicos randomizados,\nassinale a MELHOR opção terapêutica.","options":{"A":"Antimicrobiano 1 (RR = 2,1; IC95%: 0.75-6.1) (NNT: 3)","B":"Antimicrobiano 2 (RR = 1,9; IC95%: 1,22-5.1) (NNT: 2)","C":"Antimicrobiano 3 (RR = 0,46; IC95%: 0,24-0,88) (NNT: 4)","D":"Antimicrobiano 4 (RR = 0,20; IC95%: 0,05-0,79) (NNT: 8)"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-109814","number":"109814","sourceNumber":"109814","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Margarete comparece à consulta para mostrar os resultados de seus exames, incluindo\no teste anti-HIV. O teste resultou positivo.\nDiante desse resultado, analise as alternativas abaixo e\nassinale a resposta CORRETA em relação ao raciocínio clínico do Médico diante da positividade\ndo teste.","options":{"A":"O teste anti-HIV (Elisa) tem alta sensibilidade e, portanto, a probabilidade de falsos positivos\né\nbaixa. Assim, o diagnóstico está confirmado e a paciente deve ser encaminhada ao infectologista.","B":"O teste anti-HIV (Elisa) tem alta especificidade e, portanto, a probabilidade de falsos\npositivos é\nbaixa. Assim, o diagnóstico está confirmado e a paciente deve ser encaminhada ao infectologista.","C":"O teste anti-HIV (Elisa) tem alta sensibilidade e, portanto, a probabilidade de falsos positivos\né\nmaior. Assim, deve-se solicitar o teste, mais específico, Western-Blott para confirmar ou não o\ndiagnóstico presumido pelo Elisa.","D":"Como o teste Western-Blott, realizado para triagem, é altamente específico, não há necessidade\nde solicitar o teste Elisa. Assim, o diagnóstico\nestá confirmado e a paciente deve ser encaminhada\nao infectologista."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-109765","number":"109765","sourceNumber":"109765","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na avaliação de dois pacientes, um de 19 e outro de 49 anos, ambos com pesquisa de\nsangue oculto nas fezes positiva, um Médico\nconsidera que a probabilidade de câncer do trato\ngastrintestinal é maior para o paciente de 49 anos. O raciocínio desse Médico está CORRETO,\npois:","options":{"A":"o valor preditivo negativo do teste independe da especificidade do teste.","B":"o número de falsos positivos é o mesmo nas duas faixas etárias.","C":"a sensibilidade do teste varia conforme a faixa etária.","D":"o valor preditivo positivo do teste é maior na população com maior prevalência."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-110041","number":"110041","sourceNumber":"110041","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O objetivo de um estudo foi verificar fatores de risco associados à presença de\nepisódios diarreicos em lactentes menores de 6\nmeses. Foram consideradas expostas, as crianças\nnascidas com baixo peso. Foram selecionadas 239 crianças que apresentaram pelo menos 1\nepisódio diarreico nos primeiros 6 meses de vida, sendo que destes, 88 eram expostos. Foram\nconsiderados controles todas as crianças que não apresentaram episódios diarreicos durante os\nprimeiros 6 meses de vida, num total de 158 lactentes, sendo que destes, 47 nasceram com baixo\npeso. Diante da descrição acima, assinale a alternativa CORRETA.","options":{"A":"Fator de estudo: baixo peso ao nascer. Desenlace: episódios diarreicos. Tipo de Estudo: caso\ncontrole. Medida de associação: Odds Ratio = 1,38.","B":"Fator de estudo: baixo peso ao nascer. Desenlace: episódios diarreicos. Tipo de Estudo:\ncoortes. Medida de associação: Risco Relativo =\n2,3.","C":"Fator de estudo: episódios diarreicos. Desenlace: baixo peso ao nascer. Tipo de Estudo: caso\ncontrole. Medida de associação: Odds Ratio = 2,3","D":"Fator de estudo: episódios diarreicos. Desenlace: baixo peso ao nascer. Tipo de Estudo:\ncoortes. Medida de associação: Risco Relativo =\n1,12"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-110623","number":"110623","sourceNumber":"110623","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Nas investigações de campo que utilizam estudos de incidência, a associação entre os\nfatores de risco e a ocorrência de doenças deve ser avaliada através de:","options":{"A":"Risco Absoluto.","B":"Odds Ratio.","C":"Risco Relativo.","D":"Razão de Prevalência.","E":"Razão de Incidência."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-109783","number":"109783","sourceNumber":"109783","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo, visando avaliar a eficácia do autoexame na redução da mortalidade\npor câncer de mama, 133.375 mulheres\nparticiparam de um treinamento sobre essa técnica\nde rastreamento (screening) para a doença. Os resultados do exame e do diagnóstico definitivo\nsão mostrados abaixo. (VER IMAGEM). O valor preditivo positivo do autoexame de mama é:","options":{"A":"0,2%.","B":"14,8%.","C":"77,3%.","D":"98,9%."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-110627","number":"110627","sourceNumber":"110627","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Através do banco de dados da Secretaria Municipal de Saúde, uma pesquisa levantou\na prevalência de tuberculose em Maceió e fatores\nassociados. Este é um exemplo de um estudo:","options":{"A":"Caso-controle.","B":"Ecológico.","C":"Transversal Individual.","D":"Coorte.","E":"Experimental."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-109789","number":"109789","sourceNumber":"109789","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere os dados da tabela abaixo (VER IMAGEM). Efeito da trombólise IV, em\npacientes com supradesnível de ST ou bloqueio de ramo e delta tempo até seis horas do início\ndos sintomas de IAM. Sobre esse caso, os resultados do Risco Relativo (RR) e da Redução\nRelativa Do Risco (RRR) são, RESPECTIVAMENTE,","options":{"A":"RR = 0,76; RRR = 24%.","B":"RR = 0,73; RRR = 27%.","C":"RR = 1,30; RRR = 30%.","D":"RR = 0,75; RRR = 25%."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-110533","number":"110533","sourceNumber":"110533","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um pesquisador acompanhou um grupo de adultos saudáveis por 20 anos. Os\nparticipantes foram alocados em dois subgrupos de acordo com os níveis de ingestão diária de\ngorduras saturadas. Ao final do estudo, verificou-se a diferença na incidência de doenças\ncoronarianas de acordo com a presença de fatores de risco. Este é um exemplo de um estudo:","options":{"A":"Caso-controle.","B":"Ecológico.","C":"Transversal Individual.","D":"Coorte.","E":"Experimental."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-109791","number":"109791","sourceNumber":"109791","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Estudo, realizado em uma empresa pública, teve como objetivo evidenciar as\nmanifestações do sofrimento em seus\ngestores. Das 9 variáveis estudadas, apenas o gênero\nmostrou-se estatisticamente associada (p<0,05) ao sofrimento. As trabalhadoras apresentaram\nsofrimento significativamente superior aos trabalhadores (OR = 0,6; IC = 95%). Acerca desses\nresultados, analise as afirmativas; I. A possibilidade dessa diferença entre os gêneros ser devido\nao\nacaso é menor que 5%; II. A chance das mulheres manifestarem sofrimento é 6 vezes maior que a\ndos homens; III. O Intervalo de Confiança (IC) sugere que a possibilidade desse resultado a ser\nconfirmado em outros estudos é de 95%. São CORRETAS as afirmativas contidas em:","options":{"A":"I, II e III.","B":"I e II, apenas.","C":"I e III, apenas.","D":"II e III, apenas."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-110047","number":"110047","sourceNumber":"110047","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os estudos agregados, observacionais e de corte transversal também podem ser\ndenominados de:","options":{"A":"Ensaios clínicos.","B":"Ensaios comunitários.","C":"Estudos de coortes.","D":"Estudos ecológicos."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-110065","number":"110065","sourceNumber":"110065","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Com o objetivo de avaliar alguns fatores de risco na ocorrência de Doença Isquêmica\ndo Coração (DIC), um estudo epidemiológico\nselecionou 280 pacientes com DIC e 553 pessoas\nsem história ou diagnóstico de DIC. Os resultados foram: (VER IMAGEM). A medida adequada\npara estimar a magnitude do efeito da hipercolesterolemia na ocorrência da DIC e seu respectivo\nvalor, no estudo acima, é:","options":{"A":"Risco relativo: 1,95.","B":"Risco relativo: 3,9%.","C":"Odds Ratio: 3,9.","D":"Odds Ratio: 1,9%."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-86814","number":"86814","sourceNumber":"86814","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Marque a opção correta em que o grupo de doenças são de notificação compulsória.","options":{"A":"Dengue, hepatites virais, cólera;","B":"Dengue, sarampo, herpes-zóster;","C":"Meningite, herpes-zóster,conjuntivite;","D":"Febre tifoide, conjuntivite, herpes-zóster;","E":"Febre tifoide, dengue, conjuntivite."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-86860","number":"86860","sourceNumber":"86860","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Declaração de Óbito é o documento-base do Sistema de Informações sobre\nMortalidade do Ministério da Saúde (SIM/MS).\nÉ composta de três vias autocopiativas,\nprenumeradas sequencialmente, fornecida pelo Ministério da Saúde e distribuída pelas Secretarias\nEstaduais e Municipais de saúde. Quanto ao papel do médico:","options":{"A":"A emissão da DO é ato médico, segundo a\nlegislação do país.","B":"O médico tem responsabilidade ética e jurídica pelo preenchimento e pela assinatura da DO,\nassim como pelas informações registradas em todos os campos deste documento.","C":"O médico deve preencher os dados de identificação com base em um documento da pessoa\nfalecida. Na ausência de documento, caberá à\nautoridade policial proceder ao reconhecimento do\ncadáver.","D":"Na situação da criança nascer viva e morrer logo após o nascimento, independente da duração\nda gestação, do peso do recém-nascido e do\ntempo que tenha permanecido vivo, a DO deve ser\nemitida.","E":"Todas acima estão corretas."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-362453","number":"362453","sourceNumber":"362453","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"As medidas de rendimento de testes diagnósticos são habitualmente analisadas por\nmeio do quadro \"2x2\" que relaciona a\npresença ou não de uma doença com o resultado de um\nteste: Qual das fórmulas abaixo descreve corretamente o cálculo da ESPECIFICIDADE de um teste\ndiagnóstico?","options":{"A":"D/C+","B":"D/B+D","C":"A/A+C","D":"A/A+B"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-362452","number":"362452","sourceNumber":"362452","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Você é médico de uma equipe de Estratégia Saúde da Família de uma cidade\ninteriorana e, em certo dia, o secretário de\nsaúde do município o convocou para avaliar a\nimplantação de um programa de rastreamento para uma determinada doença cardíaca. Durante a\nrevisão da literatura sobre o tema você constata que de cada 2000 pessoas com essa doença que\nnão fazem o rastreamento, 400 morrem, enquanto com o rastreamento, o número de mortes é de\n\n200. Considerando os dados, qual das alternativas descreve CORRETAMENTE o número de\npessoas a serem rastreadas para se evitar um\nóbito?","options":{"A":"5","B":"10","C":"20","D":"40"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-362517","number":"362517","sourceNumber":"362517","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Supondo que a taxa de mortalidade anual de câncer de pulmão numa dada\ncomunidade seja de 20 por 100.000 nos fumantes\ne de 2 por 100.000 nos não fumantes, qual o\nrisco relativo e o risco absoluto dos fumantes em relação aos não fumantes, de morrer por câncer\nde pulmão, respectivamente:","options":{"A":"9 e 20 por 100.000.","B":"10 e 18 por 100.000.","C":"18 e 10 por 100.000.","D":"38 e 20 por 100.000."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-327305","number":"327305","sourceNumber":"327305","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo comparou, durante dez anos, a mortalidade por câncer de mama em dois\ngrupos de mulheres que fizeram ou não o exame de mamografia de rastreamento, com a intenção\nde avaliar o impacto do exame na redução do desfecho óbito. Ambos os grupos eram compostos\npor 1.000 mulheres. No primeiro grupo foi realizada mamografia a cada dois anos, e ao final do\ntempo de estudo houve 4 óbitos por câncer de mama. O segundo grupo era composto também por\n\n1.000 mulheres, sendo que neste grupo não foi realizada mamografia, sendo constatados 6 óbitos\npor câncer de mama. Considerada a mortalidade\nem ambos os grupos, podemos inferir que o\nNúmero Necessário a Tratar (NNT) da mamografia para a prevenção do desfecho óbito, neste\nestudo, foi de:","options":{"A":"500.","B":"1.000.","C":"50.","D":"100."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-327319","number":"327319","sourceNumber":"327319","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Você foi convidado pelo secretário de saúde para ser consultor na implementação de\num teste de rastreamento de uma determinada\ndoença cuja prevalência é de 1% na população de\nseu município, que é de 5.000 habitantes. Ao fazer uma revisão da literatura, você constata que o\nteste proposto possui uma sensibilidade de 50% e uma especificidade de 90%. Considerando os\ndados, você conclui que para cada exame realizado que seja verdadeiro-positivo haverá um\nnúmero de testes falso-positivos de aproximadamente: (não considerando casa decimal).","options":{"A":"19.","B":"25.","C":"495.","D":"4.950."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-298271","number":"298271","sourceNumber":"298271","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O raciocínio clínico em Atenção Primária à Saúde deve partir dos dados e informações\na respeito da probabilidade de existência de uma\ndoença específica em um dado momento no\ntempo. Esta probabilidade, a qual chamamos de pré-teste, possui um sinônimo pelo qual é mais\ncomumente conhecida. Qual é?","options":{"A":"Valor Preditivo Positivo","B":"Incidência","C":"Prevalência","D":"Valor Preditivo Negativo"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-286783","number":"286783","sourceNumber":"286783","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Marlene, 26 anos, vem à consulta com queixas de disúria e polaciúria há dois dias.\nRelata que percebeu sangue ao secar-se. Você ficou na dúvida a respeito da confiabilidade dos\ndados da história, para definir o diagnóstico de cistite, ou se seriam necessários exames\ncomplementares, como EAS e urinocultura, e foi fazer uma busca na internet. Você encontra um\nartigo que menciona que a combinação de disúria, polaciúria e ausência de corrimento tem um\nvalor preditivo positivo (VPP) de 95%. Isto significa que:","options":{"A":"É a probabilidade de 5% de o exame de urina indicar infecção urinária.","B":"É a probabilidade de 95% de Marlene apresentar o diagnóstico de cistite diante dos sintomas\ncitados.","C":"É a estimativa de 95% de risco de cistite, confirmada pela urocultura.","D":"É a probabilidade pré-teste do diagnóstico de cistite através da urocultura."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-294495","number":"294495","sourceNumber":"294495","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Pesquisadores internacionais desejam testar cientificamente uma nova vacina para a\nmalária, no Brasil. Contam para isso com uma instituição nacional patrocinadora. O protocolo de\npesquisa implica em usar em voluntários uma dose da nova vacina, testando sua eficácia e\nsegurança. Identifique, entre os citados, o desenho metodológico mais apropriado para verificar os\ndesfechos primário e secundários da pesquisa.","options":{"A":"Ensaio clínico prospectivo randomizado duplo-cego.","B":"Estudo caso ? controle pareado e estratificado.","C":"Metanálise com inferência estatística.","D":"Estudo teste de sensibilidade e especificidade."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-284625","number":"284625","sourceNumber":"284625","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A incerteza no tratamento da COVID-19 gerou inúmeros trabalhos científicos e\nprotocolos. Temos assistido muitas\ncontrovérsias quanto ao uso criterioso de medicações para\ntratamento eficaz. As bases científicas prevêem princípios da Epidemiologia Clínica para a seleção\nde fármacos e de protocolos de tratamento. Indique o modelo de estudo (desenho metodológico)\nmais adequado para conhecer a eficácia de uma droga nova no tratamento de uma doença,\nimediatamente após ultrapassada a fase de segurança.","options":{"A":"Ensaio clinico prospectivo, duplo cego randomizado e controlado.","B":"Estudo de Coorte histórico e multicêntrico.","C":"Metanálise retrospectiva dos estudos clínicos de segurança.","D":"Estudo de Coorte transversal com amostra populacional."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-284626","number":"284626","sourceNumber":"284626","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A incerteza no tratamento da COVID-19 gerou inúmeros trabalhos científicos e\nprotocolos. Temos assistido muitas\ncontrovérsias quanto ao uso criterioso de medicações para\ntratamento eficaz. As bases científicas prevêem princípios da Epidemiologia Clínica para a seleção\nde fármacos e de protocolos de tratamento. É correto afirmar que o desfecho primário de uma\npesquisa clínica pode ser definido por:","options":{"A":"Uma variável que responde à pergunta da pesquisa.","B":"Conclusões da pesquisa a serem descritas na publicação.","C":"Finalização precoce da pesquisa devido a resultados insatisfatórios.","D":"Finalização precoce da pesquisa por resultados excepcionalmente bons."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-343376","number":"343376","sourceNumber":"343376","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Mesmo numa fase de escalada da variante Ômicron, quando novos questionamentos\npodem surgir sobre os riscos versus benefícios da\nvacinação em crianças e adolescentes jovens,\numa série de estudos publicados mais recentemente concluíram que a vacinação com RNAm\n(particularmente BNT162b2):","options":{"A":"Especialmente quando não reforçada com uma terceira dose, permanece altamente eficaz\ncontra formas graves da COVID-19, incluindo morte.","B":"Especialmente quando reforçada com uma terceira dose, permanece altamente eficaz contra\nformas graves da COVID-19, incluindo morte.","C":"Especialmente quando reforçada com uma terceira dose, não permanece altamente eficaz\ncontra formas graves da COVID-19, incluindo morte.","D":"Especialmente quando reforçada com uma terceira dose, permanece altamente eficaz contra\nformas graves da COVID-19, excluindo morte."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-343381","number":"343381","sourceNumber":"343381","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A cultura para micobactérias de material respiratório apresenta sensibilidade em torno\nde 80% e especificidade de 98%. Sendo correto\nque:","options":{"A":"Os métodos para cultura que utilizam a semeadura em meios líquidos, como o\n\nLöwenstein-Jensen e não o Ogawa-Kudoh, são os mais comumente utilizados por apresentarem a\nvantagem de ter menor custo e um baixo índice de contaminação.","B":"Os métodos para cultura que utilizam a semeadura em meios sólidos, como o\n\nLöwenstein-Jensen e o Ogawa-Kudoh, são os mais comumente utilizados por apresentarem a\nvantagem de ter maior custo e um elevado índice de contaminação.","C":"Os métodos para cultura que utilizam a semeadura em meios sólidos, como o\n\nLöwenstein-Jensen e o Ogawa-Kudoh, são os mais comumente utilizados por apresentarem a\nvantagem de ter menor custo e um baixo índice de contaminação.","D":"Os métodos para cultura que não utilizam a semeadura em meios sólidos, como o\nLöwenstein-Jensen e o Ogawa-Kudoh, são os mais comumente utilizados por apresentarem a\nvantagem de ter menor custo e um baixo índice de contaminação."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-283863","number":"283863","sourceNumber":"283863","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A bioética se constitui numa ciência que possui caráter eminentemente multidisciplinar.\nTrata-se de um ramo do conhecimento\nfundamental para a área da saúde e traz princípios e\nfundamentos que auxiliam na reflexão acerca dos avanços da ciência e suas possíveis implicações\npara a vida das pessoas (JUNQUEIRA, 2011). Em relação aos princípios da bioética, analise as\nassertivas e identifique com V as verdadeiras e com F as falsas. ( ) O princípio da autonomia\nprecede o princípio da beneficência, considerando que as pessoas têm a capacidade de decidir\nsobre suas vidas. ( ) O princípio da justiça dialoga com o conceito de equidade, no sentido de dar a\ncada pessoa o que lhe é devido segundo suas necessidades. ( ) A chamada objeção de\nconsciência representa o direito de um profissional realizar um procedimento a despeito do paciente\nnegar o tratamento. ( ) Pelo princípio da beneficência, sempre que o profissional propuser um\ntratamento, ele deverá reconhecer a dignidade do paciente e considerá-lo em sua totalidade. A\nalternativa que contém a sequência correta, de cima para baixo, é","options":{"A":"V F V F","B":"V F F V","C":"F F V V","D":"F V V F","E":"F V F V"},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-181190","number":"181190","sourceNumber":"181190","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"À respeito de evidencias cientificas que impactam na pratica clínica, não podemos\nconcordar completamente com a seguinte alternativa:","options":{"A":"As evidências científicas que determinam mudanças na prática clínica devem ser baseadas nos\ndesfechos de saúde-doença, como morte.","B":"As evidências científicas que determinam mudanças na prática clínica não devem ser baseadas\nnos desfechos de saúde-doença, como incidência\nde doença.","C":"Dados de pesquisas que interferem em desfechos substitutos (marcadores fisiopatológicos,\nbioquímicos, etc.) têm menor impacto direto na\nprática clínica.","D":"Dados de pesquisas que interferem em desfechos substitutos (marcadores fisiopatológicos,\nbioquímicos, etc.) podem ser relevantes para melhor\ncompreensão da doença e desenvolvimento\nde metodologias terapêuticas."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-157686","number":"157686","sourceNumber":"157686","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A respeito das dificuldades em se conseguir dados relacionados à mortalidade do\nDiabetes, assinale a alternativa INCORRETA.","options":{"A":"Frequentemente, na declaração de óbito, não se menciona DM pelo fato de serem suas\ncomplicações, particularmente as cardiovasculares e cerebrovasculares, as causas da morte.","B":"No início do século 21, estimou-se que se atribuíram 5,2% de todos os óbitos no mundo ao\ndiabetes, o que torna essa doença a quinta principal causa de morte.","C":"Estudos brasileiros sobre mortalidade por DM, na análise das causas múltiplas de morte, ou\nseja, quando se menciona DM na declaração de\nóbito, mostram que a taxa de mortalidade por essa\nenfermidade aumenta até 20 vezes.","D":"A parcela importante desses óbitos é prematura."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134788","number":"134788","sourceNumber":"134788","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Para estudar o efeito do fumo na gravidez sobre a saúde dos futuros bebês,\nselecionaram-se dois grupos de estudo, sendo, o\nprimeiro, o de crianças com mais de 5\ninternações por ano por bronquite e pneumonia e, outro, com crianças que tiveram, no máximo, 1\ninternação por ano devido a essas doenças. Observou-se que filhos de mães que fumavam na\ngravidez, apresentaram um número significativamente maior de admissões hospitalares por\nbronquite e pneumonia, se comparado àquele de mães que não fumavam. Esse estudo é do tipo:","options":{"A":"Coorte.","B":"Caso-controle.","C":"Ecológico.","D":"Prevalência."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134694","number":"134694","sourceNumber":"134694","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Com o objetivo de analisar fatores associados à transmissão vertical do HIV, foi\nconduzido um estudo envolvendo 252 filhos de gestantes soropositivas, atendidas na rede\npública de Goiânia, entre 1999 e 2005. Resultados parciais são apresentados na tabela a seguir:\n(VER IMAGEM) Os dados da tabela indicam que:","options":{"A":"O parto vaginal foi associado a aumento no risco de as crianças se infectarem pelo HIV.","B":"As três variáveis analisadas (idade materna, aleitamento e tipo de parto) mostraram associação\nestatisticamente significante com o risco de infecção pelo HIV.","C":"A idade materna inferior a 20 anos foi identificada como fator associado à transmissão vertical\ndo HIV. Esse resultado apresenta significância\nestatística, porém não possui significância clínica.","D":"As crianças que receberam aleitamento materno apresentaram menores riscos de infecção pelo\nHIV em relação àquelas que não receberam esse tipo de alimentação."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134755","number":"134755","sourceNumber":"134755","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Para estudar o efeito do fumo na gravidez sobre a saúde dos futuros bebês,\nselecionaram-se dois grupos de estudo, sendo, o primeiro, o de crianças com mais de 5\ninternações por ano por bronquite e pneumonia e, outro, com crianças que tiveram, no máximo, 1\ninternação por ano devido a essas doenças. Observou-se que filhos de mães que fumavam na\ngravidez, apresentaram um número significativamente maior de admissões hospitalares por\nbronquite e pneumonia, se comparado àquele de mães que não fumavam. Esse estudo é do tipo:","options":{"A":"Coorte.","B":"Caso-controle.","C":"Ecológico.","D":"Prevalência."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-134769","number":"134769","sourceNumber":"134769","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na avaliação crítica da evidência, a primeira etapa realizada é a apreciação da validade\ninterna do estudo. Nesse passo, é levada em consideração a:","options":{"A":"Aplicabilidade dos resultados ao paciente.","B":"Significância clínica vista nas medidas de efeito.","C":"Significância estatística dos resultados.","D":"Qualidade metodológica do estudo."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-111853","number":"111853","sourceNumber":"111853","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Dentre os campos de aplicação da epidemiologia, podemos incluir a:","options":{"A":"estatística, um dos pilares da epidemiologia moderna.","B":"investigação social, baseada na premissa da distribuição desigual dos agravos à saúde,\nproduto da ação de fatores que se distribuem desigualmente na população.","C":"avaliação do impacto das ações, propostas para alterar situações de saúde, envolvendo\nquestões relacionadas aos programas e serviços de saúde.","D":"definição de amostras e populações, em investigações em saúde."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-111865","number":"111865","sourceNumber":"111865","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Nos estudos epidemiológicos, são utilizadas diversas medidas de frequência e de efeito\nde doenças. Quais são as medidas MAIS\nadequadas para avaliar o impacto de intervenções de\nsaúde pública?","options":{"A":"Risco Atribuível na População e Fração Etiológica na População.","B":"Razão de Chances (ou OddsRatio) e Risco Relativo (ou Razão de Riscos).","C":"Razão de Prevalência e Razão de Chances (ou OddsRatio).","D":"Risco Atribuível e Fração Etiológica nos Expostos."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-111873","number":"111873","sourceNumber":"111873","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Num estudo, foram recrutadas 30 pessoas com certo tipo de câncer (grupo X) e 90\npessoas sem essa doença (grupo Y). Foi\naplicado questionário em todas as 120 pessoas, que\nrevelou o seguinte: no grupo X, 30% foram expostos a um determinado fator de interesse e no\ngrupo Y, 20%. O valor bruto da medida de associação MAIS apropriada entre exposição e efeito foi:","options":{"A":"RR = 1,50.","B":"OR = 0,58.","C":"RR = 0,68.","D":"OR = 1,71."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-199824","number":"199824","sourceNumber":"199824","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Médica de Unidade Básica de Saúde em área rural foi procurar evidências de\nintervenções efetivas para redução das mortes\npor Doenças Cardiovasculares (DCV) na sua\ncomunidade. Encontrou um artigo sobre um ensaio clínico, duplo-cego, randomizado, que foi\nconduzido com pacientes após infarto agudo do miocárdio primário para comparar o efeito da dieta\ndo mediterrâneo na prevenção de mortes por DCV. Considerando o desfecho, houve 100 eventos\nno grupo da dieta mediterrânica com azeite extravirgem (n = 850), 90 no grupo dieta mediterrânea\ncom nozes (n = 800) e 150 no grupo-controle (n = 850). Em outro estudo, utilizando avaliação de\nmetanálise, observou-se 9% de mortes por DCV entre os participantes alocados nos grupos de\nestatina e 2% em grupos com atividade física intensa em comparação com 10% entre os controles.\nBaseado nas evidências acima, qual a intervenção que apresenta o NNT de melhor benefício na\nmortalidade cardiovascular?","options":{"A":"Organização de grupos de atividade física supervisionados pelo NASF.","B":"Orientação nutricional para a adoção de dieta mediterrânea.","C":"Prescrição de estatinas para prevenção secundária.","D":"Adição de azeite extravirgem nas refeições."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-350824","number":"350824","sourceNumber":"350824","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sua equipe de saúde decide aplicar um questionário para identificação de casos\nsugestivos de asma brônquica em grupos de\nsintomáticos respiratórios, após o relato de uma\nusuária de que havia alta taxa de absenteísmo escolar de crianças com quadros respiratórios. Para\nse familiarizar com o instrumento, a equipe decide por inicialmente aplicar o questionário em uma\namostra representativa da população adulta da área. A amostra continha 200 adultos sintomáticos\nrespiratórios e era sabida uma prevalência de 10% de asma nessa população. O teste diagnóstico\ntinha especificidade de 60% e sensibilidade de 80%. Assinale a alternativa que indica corretamente\na acurácia do instrumento aplicado.","options":{"A":"18,2%","B":"44%","C":"62%","D":"96,4%"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-350826","number":"350826","sourceNumber":"350826","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Você e sua equipe de saúde decidiram investigar os casos de crianças sintomáticas\nrespiratórias de sua área, depois do relato\nde uma usuária sobre a alta taxa de absenteísmo infantil\nescolar. Vocês decidem aplicar um instrumento validado para todas as faixas etárias de\nidentificação de casos sugestivos de asma brônquica em sintomáticos respiratórios, mas,\ninicialmente, aplicam o teste em uma amostra da população adulta da área, em que a prevalência\nda asma é sabida de 10%. O teste tinha especificidade de 60% e sensibilidade de 80%. Após a\nequipe se familiarizar com o instrumento, é feita uma nova reunião para os últimos alinhamentos\nantes da nova etapa da intervenção, em que o questionário seria aplicado na população infantil. Os\ndados do município apontam uma prevalência de 20% de crianças asmáticas entre as crianças com\nsintomas respiratórios crônicos. A sua equipe, no entanto, questiona a validade do instrumento na\naplicação em uma população diferente e também indaga sobre o que esperar dos resultados do\nnovo teste. Assinale a alternativa que traz a assertiva correta sobre as características de\nvalidação\ndo teste diagnóstico e os fatores que influenciam seus valores preditivos.","options":{"A":"O questionário não pode ser aplicado na amostra de crianças, pois não se sabe a especificidade\ne a sensibilidade do teste nessa nova\namostra.","B":"A probabilidade pré-teste dos dois testes é a mesma, dado que se tratam de duas amostras da\nsua mesma população adscrita e o instrumento é\no mesmo.","C":"Dado que a prevalência de asma brônquica na população infantil é maior que na população\nadulta, é esperado que o valor preditivo\nnegativo do teste aumente.","D":"Dado que a prevalência de asma brônquica na população infantil é maior que na população\nadulta, é esperado que o valor preditivo\npositivo do teste aumente."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-350849","number":"350849","sourceNumber":"350849","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Você e sua equipe de saúde decidiram investigar os casos de crianças sintomáticas\nrespiratórias de sua área, depois do relato de\numa usuária sobre a alta taxa de absenteísmo infantil\nescolar. Vocês decidem aplicar um instrumento validado para todas as faixas etárias de\nidentificação de casos sugestivos de asma brônquica em sintomáticos respiratórios. O teste tinha\nespecificidade de 60% e sensibilidade de 80%. A amostra de crianças na área é de 400 e a\nprevalência sabida de crianças asmáticas entre crianças sintomáticas respiratórias é de 20%.\n\nAssinale a alternativa que traz respectivamente o valor preditivo positivo e a acurácia do teste.","options":{"A":"16% e 48%.","B":"16% e 52%.","C":"33% e 64%.","D":"92% e 64%."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-321343","number":"321343","sourceNumber":"321343","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Durante a reunião estratégica da sua equipe na UBS, foi relatado que não constavam\npessoas em tratamento para tuberculose em\nnenhuma das microáreas sob sua responsabilidade. A\nbase de dados do seu município indicava uma prevalência de tuberculose pulmonar bacilífera de 80\ncasos a cada 100.000 habitantes e a população adscrita nas suas microáreas era de 10.000\nhabitantes. Diante disso, os agentes comunitários foram capacitados para realizar busca ativa,\natravés da aplicação de questionário para identificação de Sintomáticos Respiratórios (SR),\ndetectando a presença de 100 SR. Considerando que a prevalência de SR na população geral é de\n1% e que há uma proporção de 4 doentes com tuberculose bacilífera a cada 100 SR, assinale a\nalternativa com a sensibilidade do questionário aplicado para a realização da busca ativa na\npopulação.","options":{"A":"50%.","B":"65,50%.","C":"75,75%.","D":"85,50%."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-321344","number":"321344","sourceNumber":"321344","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Durante a reunião estratégica da sua equipe na UBS, foi relatado que não constavam\npessoas em tratamento para tuberculose em\nnenhuma das microáreas sob sua responsabilidade. A\nbase de dados do seu município indicava uma prevalência de tuberculose pulmonar bacilífera de 80\ncasos a cada 100.000 habitantes e a população adscrita nas suas microáreas era de 10.000\nhabitantes. Diante disso, os agentes comunitários foram capacitados para realizar busca ativa,\natravés da aplicação de questionário para identificação de Sintomáticos Respiratórios (SR),\ndetectando a presença de 100 SR. Considerando que a prevalência de SR na população geral é de\n1% e que há uma proporção de 4 doentes com tuberculose bacilífera a cada 100 SR, assinale a\nalternativa com a acurácia do questionário aplicado para a realização da busca ativa na população.","options":{"A":"80%.","B":"90%.","C":"95%.","D":"99%."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-321345","number":"321345","sourceNumber":"321345","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A aplicação de testes para rastreamento de condições de saúde em grupos\npopulacionais é uma ferramenta para a\ndetecção precoce de agravos. Quando realizamos um\nrastreamento, qual a característica do teste que nos permite afastar a hipótese de doença em\nindivíduos com resultado negativo?","options":{"A":"Acurácia.","B":"Valor preditivo positivo.","C":"Valor preditivo negativo.","D":"Razão de verossimilhança positiva."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-259755","number":"259755","sourceNumber":"259755","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere um cenário hipotético em que prevalência de lesões neoplásicas em\npacientes com a Pesquisa de Sangue Oculto\n(PSO) positivo é de 1%, e que o PSO tem\nSensibilidade (S) de 85%, Especificidade (E) de 75%, Valor Preditivo Positivo (VPP) de 3,3% e o\nValor Preditivo Negativo (VPN) de 99,8%. Se o PSO for positivo, qual a chance de o paciente ter a\ndoença?","options":{"A":"3,30%.","B":"75%.","C":"85%.","D":"99,80%."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-259757","number":"259757","sourceNumber":"259757","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma médica iniciou, em fevereiro de 2020, sua atuação como plantonista de um\nhospital que era referência para o tratamento\nde pacientes com COVID-19. Após atender os\nprimeiros pacientes, resolveu ler um artigo para ter mais segurança no manejo clínico destes.\nConsiderando os princípios da Medicina Baseada em Evidências (MBE) e os dados de um estudo\ntransversal apresentados na tabela, qual a interpretação mais adequada para este artigo?","options":{"A":"A não realização de tomografia foi mais associada à evolução para óbito e a associação\napresentou significância estatística.","B":"Ter idade menor que 60 anos foi associado a maior chance de evoluir para o óbito por\nCOVID-19, mas não teve significância estatística.","C":"Pacientes do sexo masculino morreram mais que do sexo feminino e esse achado teve\nsignificância estatística.","D":"O uso de azitromicina foi mais prevalente entre os pacientes que evoluíram para óbito e um\nestudo transversal é o mais adequado para respaldar a tomada de decisão para uma conduta\nclínica."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-234078","number":"234078","sourceNumber":"234078","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Dr. Luís Arthur assumiu a coordenação da atenção básica em um município no interior\ndo Ceará, com o objetivo de reduzir a\nmortalidade infantil. Com base no estudo epidemiológico\nabaixo que investigou os fatores preditores da mortalidade infantil neonatal, podemos afirmar que:","options":{"A":"O Risco Relativo das meninas evoluírem a óbito foi de 70%.","B":"A prematuridade não mostrou diferença significativa no risco de morte.","C":"O baixo peso ao nascer pode ser considerado preditor de óbito neonatal.","D":"A escolaridade da mãe é fator de proteção em relação ao óbito neonatal."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-234081","number":"234081","sourceNumber":"234081","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Ana Maria trabalha em uma unidade de saúde e foi aprovada em mestrado\nprofissionalizante com dois anos de duração. Na\nsua área de abrangência, existem algumas\ncrianças acompanhadas por microcefalia. No seu projeto de pesquisa, ela pretende identificar se\nexiste relação entre as crianças com microcefalia e a exposição das mães ao vírus zika durante a\ngestação. Qual o desenho de estudo mais adequado para tentar responder a esse\nquestionamento?","options":{"A":"Série de casos.","B":"Caso-controle.","C":"Coorte prospectiva.","D":"Transversal descritivo."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-199818","number":"199818","sourceNumber":"199818","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Para dar uma entrevista sobre programas brasileiros que tiveram impacto positivo na\nsaúde, um médico fez a leitura crítica de um estudo ecológico que avaliou se a cobertura da\nestratégia de saúde da família estava associada à menor mortalidade por eventos sensíveis à\natenção primária à saúde entre grupos raciais. A tabela abaixo apresenta os principais resultados\nobservados no referido estudo. Podemos afirmar que a cobertura da estratégia de saúde da família\ntem efeito, com significância estatística, na redução de mortalidade por:","options":{"A":"DCV somente em negros/pardos.","B":"DPOC e asma somente em brancos.","C":"Diabetes somente em negros/pardos.","D":"Doenças infecciosas em negros/pardos e brancos."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-173038","number":"173038","sourceNumber":"173038","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Médica de uma Unidade Básica de Saúde irá começar um grupo de puérperas para\nincentivar o aleitamento materno. Para selecionar e orientar o grupo, estudou sobre os motivos da\nintrodução precoce do leite de vaca, e observou a tabela abaixo em um dos artigos publicados.\n\nQual dos aspectos indica maior vulnerabilidade ao desmame, segundo o artigo apresentado?","options":{"A":"Idade da mãe.","B":"Renda familiar.","C":"Tempo fora de casa.","D":"Trabalhar durante a gravidez."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-127002","number":"127002","sourceNumber":"127002","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Você é recém-chegado para trabalhar em um PSF no interior e o secretário de saúde\ndo município pede para você ajudá-lo a decidir\nsobre o custo benefício em rastrear 3 doenças (A, B\ne C) presentes na comunidade local. A tabela abaixo contém a mortalidade das três doenças,\ncalculada a partir de estudo prévio realizado na população em questão. (VER IMAGEM) Qual\norientação deve ser transmitida ao secretário de saúde?","options":{"A":"A doença A tem o maior custo benefício de ser rastreada, já que o Número Necessário\npara Rastrear a mesma é menor em relação às\ndoenças B e C.","B":"A doença B tem o maior custo benefício de ser rastreada, já que tem maior redução de Risco\nAbsoluto em relação às doenças A e C.","C":"A doença C tem o maior custo benefício de ser rastreada, já que o Número Necessário para\nRastrear é o menor entre as três doenças.","D":"As doenças A e C devem ser rastreadas, uma vez que apresentam a mesma redução de Risco\nRelativo."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-127022","number":"127022","sourceNumber":"127022","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em uma consulta anterior, você solicitou à Marta, 58 anos, um exame específico para\navaliar uma queixa clínica. Você pesou a relação entre custo e benefício ao solicitar o exame X e\ndecidiu pelo mesmo, pois entendeu que a exclusão de neoplasia traria grande proteção à Marta.\n\nPara esta decisão, você considerou seus conhecimentos de que o exame X é capaz de detectar\nsinais precoces de neoplasia. Você avaliou também\nas consequências de um possível resultado\nalterado do exame, e pesquisou que uma biópsia poderia ser necessária, o que lhe deixou\napreensivo, uma vez que este procedimento pode ser doloroso e invasivo, possui alguns riscos, e\nvocê conhece bem o medo de Marta em realizar alguns procedimentos médicos. Marta volta\npara lhe mostrar o resultado do exame X. Você não se recorda quais os valores considerados\npara a suspeita de neoplasia, e por um erro, o exame veio sem os índices normais de referência.\nVocê explica à Marta a situação, diz que vai estudar o assunto, e pede para ela voltar no dia\nseguinte para que você a explique o resultado do exame. Você lê alguns artigos e muitos deles\ntrazem o gráfico a seguir, que demonstra os pontos de\n\ncorte e suas relações probabilísticas com o diagnóstico de câncer. De acordo com a interpretação\ndo gráfico e seus conhecimentos sobre\nsensibilidade e especificidade dos testes diagnósticos, qual\nseria o ponto de corte que indicaria a biópsia? (VER IMAGEM)","options":{"A":"O ponto de corte de 25 mm apresenta baixas especificidade e sensibilidade, sendo o\nindicado para diagnóstico definitivo da doença.","B":"O ponto de corte de 15 mm deve ser o escolhido por apresentar elevada especificidade,\no que diminuiria indicações desnecessárias de\nbiópsia.","C":"O ponto de corte de 10 mm deve ser o escolhido por apresentar alta sensibilidade e\nalta especificidade, sendo útil no rastreio da doença.","D":"O ponto de corte de 5 mm apresenta a maior sensibilidade e pouca perda de\nespecificidade,\n\ndevendo ser escolhido na indicação da biópsia."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-102127","number":"102127","sourceNumber":"102127","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Paciente de 60 anos, diabética há 10 anos, procura o seu médico de família e\ncomunidade para avaliação de rotina. Durante\na consulta, o médico propõe a substituição do\nhipoglicemiante oral que usa há 8 anos (droga ?A?) por outro mais efetivo (droga ?B?), porém logo\né questionado sobre os reais benefícios da troca. Para ajudar na decisão, são apresentadas as\nincidências de complicações associadas ao diabetes de um ensaio clínico randomizado realizado\npor 10 anos: Grupo que utilizou a droga ?A?: 20%. Grupo que utilizou a droga ?B?: 5%. Que\npercentual de complicações associadas ao diabetes previstas no Grupo ?A? seriam evitadas nas\npessoas do Grupo ?B??","options":{"A":"15%","B":"25%","C":"75%","D":"85%"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-365604","number":"365604","sourceNumber":"365604","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um paciente procurou o pronto-socorro com queixa de febre de 39 °C, mialgia, cefaleia\nretro-orbitária e náusea. O médico solicitou o teste rápido para detecção de antígeno NS1, porém\nalertou o paciente que, se desse positivo, o diagnóstico estaria praticamente confirmado. Por outro\nlado, se desse negativo, o diagnóstico pensado pelo médico se manteria como principal hipótese,\npois, apesar de esse exame apresentar, com frequência, resultado falso negativo, o quadro clínico\nera muito característico. Conforme orientação dada pelo médico, assinale a alternativa correta.","options":{"A":"O exame mencionado é mais especifico do que sensível.","B":"O quadro clínico considerado como suspeito para o diagnóstico é mais especifico do que o\nexame de NS1.","C":"O teste rápido NS1 possui elevado valor preditivo positivo, independentemente da região em\nque ele aplicado.","D":"O teste rápido NS1 possui elevado valor preditivo negativo, independentemente da região em\nque ele é aplicado."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-365600","number":"365600","sourceNumber":"365600","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo observacional prospectivo com pacientes internados em unidade de\nterapia intensiva (UTI), infectados por enterobactérias, o desfecho primário foi mortalidade em 30\ndias, sendo analisados fatores que poderiam estar associados ao aumento ou à diminuição dessa\nmortalidade. Na análise, determinada variável evidenciou um risco relativo de 0,48 (IC 95% 0,26 -\n0,72 p - 0.001), ou seja, essa variável gerou","options":{"A":"aumento de mortalidade de forma estatisticamente significativa.","B":"redução de mortalidade de forma estatisticamente significativa.","C":"aumento de mortalidade de forma estatisticamente não significativa.","D":"redução de mortalidade de forma estatisticamente não significativa."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-365594","number":"365594","sourceNumber":"365594","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"No que se refere aos estudos científicos, assinale a alternativa correta.","options":{"A":"A opinião de especialista apresenta um nível de evidência acima dos estudos de caso-controle\nquando o expert possui mestrado e\ndoutorado. Do contrário, a opinião de um especialista sem\nvivência acadêmica aprofundada se encontra na base da pirâmide do nível de evidência.","B":"Os estudos de coorte prospectivo possuem a vantagem de serem baratos e rápidos.","C":"Em um estudo transversal, os dados são coletados no mesmo momento de tempo.","D":"Os ensaios clínicos são estudos cada vez menos realizados por infrigirem a ética científica, uma\nvez que, se a suspeição de um medicamento\napresentar benefício, é antiético não o administrar a\num paciente."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-365593","number":"365593","sourceNumber":"365593","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo científico, o viés que ocorre quando um fator de risco não foi\ncontemplado e está associado a outro fator de risco que se busca estudar é o de","options":{"A":"aferição.","B":"confusão.","C":"seleção.","D":"amostragem."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-349707","number":"349707","sourceNumber":"349707","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um surto de casos de hepatite A foi identificado nas populações de 3 estados\nbrasileiros em 2022. Esses casos ocorreram no\nperíodo de abril a junho e um grupo de\nepidemiologistas foi chamado para identificar a fonte da contaminação, tendo sido observado que\n52 casos ocorreram nessa janela de tempo; foi, então, selecionado um grupo controle de 104\npacientes para comparação com os pacientes que desenvolveram hepatite A. Após entrevistas e\ncoletas de dados, observou-se que 97% dos pacientes que desenvolveram hepatite A nesse\nperíodo havia consumido água engarrafada da mesma fonte, enquanto apenas 10% dos controles\nhaviam consumido a água engarrafada dessa fonte. A metodologia de estudo realizada para a\ninvestigação desse surto foi","options":{"A":"Estudo Transversal.","B":"Estudo Coorte.","C":"Ensaio Clínico Randomizado.","D":"Estudo Ecológico.","E":"Estudo de Caso-controle."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-322215","number":"322215","sourceNumber":"322215","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um grupo de pesquisadores pretende avaliar a associação entre tabagismo e episódios\nde pneumonia bacteriana entre adultos em certa\ncomunidade. Para isso, decidem acompanhar toda\na população adulta de uma pequena cidade e registrar todos os casos de pneumonia bacteriana ao\nlongo de um ano. A informação sobre a exposição ao tabaco será obtida através de um\nquestionário, o qual será enviado por correio antes do início do estudo, aos seis meses de\nacompanhamento e logo após o final do estudo. Com base no exposto, é CORRETO afirmar que\nse trata de um estudo:","options":{"A":"Observacional, prospectivo de coorte.","B":"Experimental, prospectivo de coorte.","C":"Experimental, retrospectivo de coorte.","D":"Observacional, retrospectivo de caso-controle.","E":"Observacional, de coorte transversal."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-322219","number":"322219","sourceNumber":"322219","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Marcos, 22 anos, HIV positivo, participou de um estudo sobre testes rápidos para HIV e\nseu resultado foi o único negativo entre as 50\npessoas soropositivas do estudo, com um total de\n100 participantes. Nesse caso, qual foi a sensibilidade do teste?","options":{"A":"96%.","B":"99%.","C":"49%.","D":"98%.","E":"50%."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-322220","number":"322220","sourceNumber":"322220","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Paulo, 67 anos, engenheiro civil, casado e previamente hígido, recebeu diagnóstico de\nadenocarcinoma de cólon e, após toda adequada explicação do médico assistente sobre o caso,\nopta por não realizar o tratamento. Qual princípio ético deve ser respeitado nesse caso?","options":{"A":"Não maleficência.","B":"Justiça.","C":"Beneficência.","D":"Tolerância.","E":"Autonomia."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-305350","number":"305350","sourceNumber":"305350","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A pirâmide das evidências apresenta uma hierarquia da qualidade da evidência para\nperguntas clínicas segundo o desenho do estudo utilizado. A qualidade do estudo, por sua vez, é\ninversamente relacionada ao risco de vieses do estudo. Em conformidade com os princípios da\nPrática em Saúde Baseada em Evidências e com a proposta da \"nova pirâmide das evidências\", o\ndesenho de estudo cuja evidência apresenta a melhor qualidade é","options":{"A":"opinião de especialista.","B":"revisão sistemática com meta-análise.","C":"ensaio clínico randomizado.","D":"estudo de coorte.","E":"variável, a depender do tipo de pergunta."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-305352","number":"305352","sourceNumber":"305352","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um grupo de pesquisa desenvolveu um novo teste sorológico, significativamente mais\nbarato, para o diagnóstico de infecção pelo vírus SARS-Cov-2. Para a avaliação da acurácia desse\nteste, foi feito um estudo transversal com 5.000 participantes. Comparado ao padrão-ouro definido,\nos resultados desse novo teste foram os seguintes: Considerando esses resultados, assinale a\nalternativa CORRETA.","options":{"A":"A sensibilidade do novo teste foi 86%.","B":"A especificidade do novo teste foi superior a 90%.","C":"A razão de verossimilhança positiva foi 7,0.","D":"A razão de verossimilhança negativa foi 0,16.","E":"A acurácia do teste foi inferior a 86%."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-305364","number":"305364","sourceNumber":"305364","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Carla, residente de pediatria, recebe um folder de um representante de laboratório em\nque consta a informação de que um novo\npolivitamínico desse laboratório reduziu em 31% o risco\nde anemia, comparado ao uso do sulfato ferroso, para lactentes entre 6 e 24 meses de vida.\n\nIntrigada com um resultado tão expressivo, ela decide analisar melhor o estudo. Trata-se de um\nensaio clínico randomizado duplo-cego, aparentemente bem conduzido e sem vieses importantes,\nexceto por seu financiamento da indústria e consequente conflito de interesse. Ao chegar na seção\nde resultados do artigo, Carla se depara com a seguinte tabela: Considerando os resultados do\nnovo polivitamínico para a prevenção de anemia sobre o sulfato ferroso na população estudada,\nassinale a alternativa correta.","options":{"A":"A redução absoluta de risco foi de 31%.","B":"A diferença entre o odds ratio (OR) e o risco relativo (RR) foi inferior a 1%.","C":"A chance de anemia no grupo do sulfato ferroso foi 2,97%.","D":"A redução do risco relativo (RRR) foi maior do que 1.","E":"O número necessário para tratar (NNT) foi inferior a 50."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-298936","number":"298936","sourceNumber":"298936","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um paciente de 35 anos de idade compareceu à consulta na unidade básica de saúde\n(UBS) com queixa de disúria e presença de\nsecreção peniana há dois dias. Relata relações sexuais\ndesprotegidas nas últimas duas semanas. Ao exame físico, observou-se presença de drenagem de\nsecreção mucopurulenta na uretra. Foram realizados testes rápidos, na UBS, para HIV, hepatites B\ne C e sífilis, obtiveram-se resultados não reagentes. Considerando esse caso clínico e com base\nnos conhecimentos médicos correlatos, julgue o item a seguir. Os testes rápidos realizados\npossuem alta sensibilidade, sendo indicados para triagens diagnósticas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-298953","number":"298953","sourceNumber":"298953","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma paciente de 65 anos de idade compareceu à consulta com queixa de polidipsia,\npolifagia, poliúria e perda ponderal de 5 kg\nnos últimos três meses. Queixa-se também de humor\ndeprimido, anedonia e avolia. Tabagista, possui diagnósticos de hipertensão arterial sistêmica\n(HAS), doença pulmonar obstrutiva crônica (DPOC) e depressão. Faz uso de amitriptilina 25 mg à\nnoite, enalapril 10 mg, 2 vezes ao dia, hidroclorotiazida 25 mg, 1 vez ao dia e salbutamol\ninalatório\nsob demanda. Ao exame físico, apresenta mancha hiperpigmentada em região de dobra cervical,\naveludada à palpação. Observou-se PA = 160 mmHg x 110 mmHg em ambos os membros\nsuperiores. Foi realizada medida de HGT, com resultado de 320 mg/dL. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Caso fosse decidido realizar\num relato de caso a partir do exposto no enunciado, este seria classificado como um estudo\nanalítico, capaz de investigar a associação entre fatores de risco e a ocorrência de determinados\nagravos à saúde.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-274419","number":"274419","sourceNumber":"274419","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"No cenário da Atenção Primária à Saúde (APS), na qual em geral temos uma\npopulação com baixa prevalência de doenças, a\nprobabilidade de um exame cujo resultado indique\nqualquer alteração de fato representar alguma doença será menor que a probabilidade em um\ncenário de alta prevalência de doenças, como hospitais secundários e terciários. Esse conceito\nrefere-se a qual característica dos testes diagnósticos?","options":{"A":"Sensibilidade.","B":"Especificidade.","C":"Valor preditivo positivo.","D":"Acurácia.","E":"Prevalência."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-274420","number":"274420","sourceNumber":"274420","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale a alternativa que representa corretamente os quatro princípios que orientam a\nética médica.","options":{"A":"Beneficência, Não maleficência, Autonomia e Justiça.","B":"Beneficência, Não maleficência, Coordenação e Acesso.","C":"Acesso, Longitudinalidade, Coordenação e Autonomia.","D":"Longitudinalidade, Integralidade, Coordenação e Acesso.","E":"Beneficência, Integralidade, Autonomia e Longitudinalidade."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-261310","number":"261310","sourceNumber":"261310","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Certo estudo acompanhou pacientes tabagistas que desejavam parar de fumar e que\nfizeram uso de medicamento como método auxiliar, e também pacientes tabagistas que desejavam\nparar de fumar e que não fizeram uso de medicamento, observando-se, posteriormente, os\nresultados de sucesso, ou não, na cessação do tabagismo nos dois grupos. Acerca desse caso e\ntendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. Trata-se de um estudo\nde coorte, estudo observacional e longitudinal que compara grupos expostos e não expostos a\ndeterminado fator.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-261311","number":"261311","sourceNumber":"261311","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Certo estudo acompanhou pacientes tabagistas que desejavam parar de fumar e que\nfizeram uso de medicamento como método auxiliar, e também pacientes tabagistas que desejavam\nparar de fumar e que não fizeram uso de medicamento, observando-se, posteriormente, os\nresultados de sucesso, ou não, na cessação do tabagismo nos dois grupos. Acerca desse caso e\ntendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. Enquanto os estudos\ndo tipo caso-controle são retrospectivos, os estudos do tipo coorte sempre são prospectivos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-261312","number":"261312","sourceNumber":"261312","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Certo estudo acompanhou pacientes tabagistas que desejavam parar de fumar e que\nfizeram uso de medicamento como método auxiliar, e também pacientes tabagistas que desejavam\nparar de fumar e que não fizeram uso de medicamento, observando-se, posteriormente, os\nresultados de sucesso, ou não, na cessação do tabagismo nos dois grupos. Acerca desse caso e\ntendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. Ao avaliar se estudos\nsão válidos e confiáveis, deve-se atentar aos erros sistemáticos, como o viés de seleção e o viés de\naferição, e avaliar se o p < 0,05.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-261323","number":"261323","sourceNumber":"261323","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Todo profissional médico deve ter algum conhecimento a respeito de atendimento ao\npaciente politraumatizado e medicina de emergência. No que se refere a essa informação e aos\nconhecimentos médicos correlatos, julgue o item a seguir. Em um atendimento de emergência,\npode-se dispensar os princípios da beneficência e da não maleficência.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-250160","number":"250160","sourceNumber":"250160","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Foi realizado um estudo de coorte para avaliar a ocorrência de acidente vascular\ncereblar (AVC) em pacientes com diagnóstico\nde hipertensão arterial sistêmica (HAS) e diabetes\nmelito (DM). Ao todo, duzentos pacientes foram incluídos no estudo, sendo 105 pacientes no grupo\nHAS e DM controlados e 95 pacientes no grupo HAS e DM não controlados. No grupo de pacientes\ncom HAS e DM não controlados, noventa pacientes tiveram AVC e, no grupo de pacientes com\nHAS e DM controlados, apenas dez pacientes tiveram AVC. Com base nesse caso hipotético,\njulgue o item a seguir. O cálculo do odds ratio (OR) para avaliação de fator de risco nos estudos de\ncoorte é mais adequado que o cálculo do risco relativo (RR). No estudo em questão, OR = 1,98.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-250169","number":"250169","sourceNumber":"250169","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O rastreamento é definido como o exame de pessoas assintomáticas para a\nidentificação presuntiva de doença previamente não\nconhecida. No que se refere ao rastreamento\nde doenças, julgue o item a seguir. A sensibilidade de um teste de rastreamento é medida pela\nproporção de indivíduos sem a doença que têm teste negativo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-239355","number":"239355","sourceNumber":"239355","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Acerca dos conhecimentos de bioestatística, das políticas de saúde e dos\nconhecimentos médicos correlatos, julgue o item a seguir. Estudos de coorte prospectivos\nfavorecem o estudo de doenças raras.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-239356","number":"239356","sourceNumber":"239356","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Acerca dos conhecimentos de bioestatística, das políticas de saúde e dos\nconhecimentos médicos correlatos, julgue o item\na seguir. O erro tipo 1, em um teste de hipóteses,\nconsiste na rejeição da hipótese nula, quando ela é verdadeira.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-239357","number":"239357","sourceNumber":"239357","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Acerca dos conhecimentos de bioestatística, das políticas de saúde e dos\nconhecimentos médicos correlatos, julgue o item a\nseguir. A eficácia de um estudo traduz o poder\nque esse tem de reproduzir, para distintas populações e circunstâncias, desfechos semelhantes\naos encontrados na pesquisa clínica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-255775","number":"255775","sourceNumber":"255775","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo do tipo caso-controle, 100 pacientes portadores de câncer de pulmão\nforam comparados com 200 pacientes sem a doença.\nDos pacientes portadores de câncer de\npulmão, 60 apresentavam história de tabagismo, e dos pacientes sem a doença, 40 apresentavam\nhistória de tabagismo. A respeito do exposto, julgue o item a seguir. Nos estudos do tipo\n\ncaso-controle, podem-se estudar vários fatores de exposição, mas apenas 1 desfecho.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-196613","number":"196613","sourceNumber":"196613","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Suponha que o secretário de Saúde de uma metrópole brasileira com cerca de 5\nmilhões de habitantes precise gerenciar a\nalocação dos recursos da própria pasta entre as diversas\nnecessidades do sistema de saúde municipal, incluindo os serviços primário, secundário e terciário\nnas respectivas ações de prevenção, tratamento e reabilitação. Acerca de todo o planejamento que\nenvolve a função desse servidor público, julgue o item a seguir. Os dados de prevalência de\ndeterminada doença na população dessa metrópole são essenciais para o cálculo dos exatos\nvalores preditivos negativo e positivo para os testes diagnósticos nessa região.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-214441","number":"214441","sourceNumber":"214441","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Qualquer sistema de saúde, público ou privado, deve organizar estratégias de\npromoção de saúde e prevenção de doenças,\nvisando a diminuir a morbimortalidade da respectiva\npopulação assistida e reduzir os custos associados a determinadas doenças. Com base no\nexposto, considere que o gestor responsável por determinada Secretaria Estadual de Saúde\nprecise realizar o planejamento de objetivos e custos do próximo ano, incluindo todos os diferentes\nníveis de atenção à saúde, estratégias de promoção à saúde e prevenção de doenças. Acerca\ndesse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. Os\ntestes de rastreamento apresentam sensibilidade e especificidade constantes, independentemente\nda população. Entretanto, os valores preditivos desses testes variam conforme a prevalência da\ndoença em cada população.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-214444","number":"214444","sourceNumber":"214444","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Qualquer sistema de saúde, público ou privado, deve organizar estratégias de\npromoção de saúde e prevenção de doenças,\nvisando a diminuir a morbimortalidade da respectiva\npopulação assistida e reduzir os custos associados a determinadas doenças. Com base no\nexposto, considere que o gestor responsável por determinada Secretaria Estadual de Saúde\nprecise realizar o planejamento de objetivos e custos do próximo ano, incluindo todos os diferentes\nníveis de atenção à saúde, estratégias de promoção à saúde e prevenção de doenças. Acerca\ndesse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. Os\ntestes diagnósticos que apresentam alta especificidade e baixa sensibilidade são mais úteis para o\nraciocínio diagnóstico quando se apresentam negativos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-177659","number":"177659","sourceNumber":"177659","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"No contexto da Atenção Primária à Saúde, eventualmente, encontram-se prontuários\nque relatam todo o curso de vida de certo\npaciente, desde o período gestacional até a idade adulta,\nincluindo-se o período reprodutivo. Suponha que o M.S.F., atualmente com 28 anos de idade, foi\nacompanhada, no posto de saúde, durante toda a sua vida, desde a própria gestação da qual foi\nfruto. Ao longo de sua vida, várias estratégias de prevenção e programas de rastreamento foram\nefetuados e, eventualmente, continuarão sendo utilizados ao longo de seu envelhecimento. A\npaciente é sexualmente ativa, solteira, negra, com dois filhos (2 e 4 anos de idade), secretária,\nnão\ntabagista, não etilista, fisicamente ativa, com IMC = 22,5 e PA = 125 mmHg x 70 mmHg na última\nconsulta. A respeito dessas estratégias e desses programas e considerando as recomendações\ndos cadernos de Atenção Básica do Ministério da Saúde, julgue o item a seguir. Em testes com\nresultados quantitativos, diminuir um ponto de corte para aumentar a sensibilidade pode\ncomprometer a especificidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-152167","number":"152167","sourceNumber":"152167","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O processo de trabalho na atenção básica em saúde pressupõe o envolvimento de\nequipe multidisciplinar nos cuidados ao paciente.\nAs interfaces desfazem as barreiras de uma\n\"assistência médica para a doença\" seguindo no sentido da \"medicina dos doentes\". Contudo, a\nmesmo tempo que ocorre uma mudança significativa de algumas práticas, outras permanecem de\nforma latente ao longo do tempo. Nesse contexto, a ética profissional e a bioética têm papel\nfundamental como norteadores na análise das condutas dos sujeitos envolvidos e na orientação\ndas boas práticas. Quanto aos conflitos éticos e bioéticos surgidos no exercício da medicina, julgue\no item a seguir. Os valores constituem crenças específicas em determinados modelos de conduta\nsocialmente aceitos, enquanto a moral é o conjunto desses mesmos valores.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-152135","number":"152135","sourceNumber":"152135","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O processo de trabalho na atenção básica em saúde pressupõe o envolvimento de\nequipe multidisciplinar nos cuidados ao paciente.\nAs interfaces desfazem as barreiras de uma\n\"assistência médica para a doença\" seguindo no sentido da \"medicina dos doentes\". Contudo, a\nmesmo tempo que ocorre uma mudança significativa de algumas práticas, outras permanecem de\nforma latente ao longo do tempo. Nesse contexto, a ética profissional e a bioética têm papel\nfundamental como norteadores na análise das condutas dos sujeitos envolvidos e na orientação\ndas boas práticas. Quanto aos conflitos éticos e bioéticos surgidos no exercício da medicina, julgue\no item a seguir. Um conflito existe quando se lançam as lentes da bioética sobre a ética\nprofissional, isto é, quando se pondera a autonomia profissional com as vedações de conduta\nimpostas pelo código de ética médico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-152158","number":"152158","sourceNumber":"152158","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um inventigador planeja estudar a relação entre infecção por clamídia e doença\ninflamatória pélvica em mulheres usuárias de contraceptivos injetáveis, nas mulheres do\nambulatório de doenças sexualmente transmissíveis (com ou sem infecção). No momento da\nentrevista, ele avaliará o uso de preservativos no último ano (com ou sem exposição).\n\nConsiderando o desenho desse estudo hipotético e com base nos conhecimentos médicos a\nrespeito da epidemiologia clínica e da\nvigilância epidemiológica, julgue o item a seguir. Esse se\ntrata de um estudo descritivo tipo transversal, em que se coletam informações e o desfecho/doença\nem um grupo de indivíduos, em um ponto fixo de tempo ou em um período específico do tempo.\n\nCom esse desenho, podem-se obter informações quanto à razão de prevalência ou de prevalência\nrelativa, porém não se pode distinguir se a\nexposição ocorreu antes do desenvolvimento da\ndoença, pois a coleta de informações é simultânea durante a entrevista.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-152163","number":"152163","sourceNumber":"152163","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um investigador planeja estudar a relação entre infecção por clamídia e doença\ninflamatória pélvica em mulheres usuárias de contraceptivos injetáveis, nas mulheres do\nambulatório de doenças sexualmente transmissíveis (com ou sem infecção). No momento da\nentrevista, ele avaliará o uso de preservativos no último ano (com ou sem exposição).\n\nConsiderando o desenho desse estudo hipotético e com base nos conhecimentos médicos a\nrespeito da epidemiologia clínica e da\nvigilância epidemiológica, julgue o item a seguir. Esse é o\ndesenho de um estudo tipo coorte retropesctiva, podendo ser ou não sem exposição. Nesse caso,\na categorização é feita na presença ou não de exposição, com sujeitos seguidos transversalmente.\nÉ adequado para acompanhar a incidência do agravo em saúde, não importando se os sujeitos\nestão livres de doença.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-152171","number":"152171","sourceNumber":"152171","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um inventigador planeja estudar a relação entre infecção por clamídia e doença\ninflamatória pélvica em mulheres usuárias de contraceptivos injetáveis, nas mulheres do\nambulatório de doenças sexualmente transmissíveis (com ou sem infecção). No momento da\nentrevista, ele avaliará o uso de preservativos no último ano (com ou sem exposição).\n\nConsiderando o desenho desse estudo hipotético e com base nos conhecimentos médicos a\nrespeito da epidemiologia clínica e da\nvigilância epidemiológica, julgue o item a seguir. Para\nestabelecer a relação de causalidade, o delineamento mais adequado seria o experimental, em que\nos sujeitos da pesquisa seriam alocados para receber o fator de exposição, e outro grupo não\nreceberia o fator de forma randomizada. Desse modo, esse é o desenho mais adequado para o\nenquadramento da pesquissa do problema citado, por não impactar significativamente os\ndesfechos e a eticidade da pesquisa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-152138","number":"152138","sourceNumber":"152138","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um investigador planeja estudar a relação entre infecção por clamídia e doença\ninflamatória pélvica em mulheres usuárias de contraceptivos injetáveis, nas mulheres do\nambulatório de doenças sexualmente transmissíveis (com ou sem infecção). No momento da\nentrevista, ele avaliará o uso de preservativos no último ano (com ou sem exposição).\n\nConsiderando o desenho desse estudo hipotético e com base nos conhecimentos médicos a\nrespeito da epidemiologia clínica e da\nvigilância epidemiológica, julgue o item a seguir. Na\navaliação de propriedades e na escolha de um teste diagnóstico, deve-se considerar a\nsensibilidade e a especificidade. Nesse contexto, emerge o valor preditivo, que é diretamente\ndependente da sensibilidade, da especificidade e da incidência da doença (probabilidade pré-teste\nda doença).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-135037","number":"135037","sourceNumber":"135037","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Com relação à epidemiologia, julgue o item subsecutivo. Os ensaios clínicos\nrandomizados são estudos experimentais que\ntestam novas abordagens com o objetivo de prevenir\ne de tratar doenças. Os participantes desses estudos são alocados aleatoriamente em grupos\npassíveis ou não de receber a intervenção proposta.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-135051","number":"135051","sourceNumber":"135051","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Com relação à epidemiologia, julgue o item subsecutivo. As hipóteses a respeito tanto\nde distribuição de agravos quanto de relação\nentre causa e efeito não devem ser formuladas por\nmeio de estudos descritivos, em decorrência da limitação que estes apresentam, bem como da\nimpossibilidade de serem feitas análises de possíveis associações entre exposição e efeito-doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-135081","number":"135081","sourceNumber":"135081","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Julgue o item que se segue, relativo à Bioética: a autonomia do paciente deve ser\nconsiderada quando houver manifestação consciente de suas vontades no que diz respeito a\nintervenções de caráter preventivo, diagnóstico ou terapêutico; no entanto prioriza-se a decisão\nfinal do médico, uma vez que ela é respaldada por evidências científicas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-105540","number":"105540","sourceNumber":"105540","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A tomada de decisão em medicina é essencial para um bom e eficaz atendimento ao\npaciente. Uma das formas de se escolher bem um teste, ou exame, diagnóstico é atender aos\ncritérios de adequação estabelecidos. Entre esses, está o valor preditivo positivo do teste, que é\ndefinido como a:","options":{"A":"Porcentagem de pacientes com a doença que têm um resultado realmente anormal.","B":"Porcentagem de pacientes sem a doença que têm um resultado normal.","C":"Porcentagem de pacientes com resultado anormal e que realmente têm a doença.","D":"Porcentagem de pacientes com um teste normal e que não têm a doença.","E":"Probabilidade de ocorrência da doença naquele local."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-105546","number":"105546","sourceNumber":"105546","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em relação às origens desenvolvimentistas da saúde e da doença, há estudos que\nfazem a ponte entre os achados de estudos\nexperimentais e sua aplicação para humanos, trazendo\nmaior compreensão a diferentes fenômenos e patologias. Com base nessa informação, assinale a\nalternativa que apresenta a classificação desses estudos.","options":{"A":"Translacionais.","B":"Clínicos.","C":"Transversais.","D":"Epidemiológicos.","E":"Caso-controle."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-108213","number":"108213","sourceNumber":"108213","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Julgue o próximo item, referente à bioética. Na realização de uma pesquisa clínica\nexigem-se alguns princípios éticos, como o\nconsentimento dos participantes; privacidade das\ninformações relacionadas ao sujeito de pesquisa e aprovação pelos pares no que concerne a\nrelevância e qualidade científica da pesquisa e a relação entre os benefícios que a pesquisa poderá\nproduzir e os riscos que ela poderá causar.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352340","number":"352340","sourceNumber":"352340","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo conduzido em 18 clínicas de saúde sexual, o objetivo foi avaliar a\neficácia da profilaxia pré-exposição para o\nvírus HIV (PrEP). Foram selecionados 546 homens que\nfazem sexo com homens e relataram não utilizar preservativo durante o coito anal nos últimos 90\ndias, sendo soronegativos para o HIV. Os participantes foram aleatoriamente divididos em dois\ngrupos: o grupo precoce e o grupo tardio. Aqueles no grupo precoce iniciaram o uso da PrEP\nimediatamente, enquanto o grupo tardio começou após um ano de observação. Ambos os grupos\nforam acompanhados mensalmente com exames laboratoriais e responderam a questionários\nsobre aderência e atividade sexual. A incidência de HIV nos grupos foi avaliada. No grupo precoce,\na incidência foi de 1,2 casos por 100 pessoas-ano (IC de 90%; 0,4-2,9), em comparação com 9\ncasos por 100 pessoas-ano (IC de 90%: 6,1-12,8; p=0,0001) no grupo tardio. A diferença foi de 7,8\ncasos por 100 pessoas-ano (IC de 90%; 4,3-11,3). Com base no estudo apresentado, a teoria\nepidemiológica e conhecimentos correlatos, julgue o item a seguir. O estudo mencionado é um\nestudo de coorte, pois é conduzido de forma prospectiva, acompanhando a incidência no grupo de\nindivíduos expostos e não expostos a uma determinada conduta, em clínicas distintas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352339","number":"352339","sourceNumber":"352339","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo conduzido em 18 clínicas de saúde sexual, o objetivo foi avaliar a\neficácia da profilaxia pré-exposição para o\nvírus HIV (PrEP). Foram selecionados 546 homens que\nfazem sexo com homens e relataram não utilizar preservativo durante o coito anal nos últimos 90\ndias, sendo soronegativos para o HIV. Os participantes foram aleatoriamente divididos em dois\ngrupos: o grupo precoce e o grupo tardio. Aqueles no grupo precoce iniciaram o uso da PrEP\nimediatamente, enquanto o grupo tardio começou após um ano de observação. Ambos os grupos\nforam acompanhados mensalmente com exames laboratoriais e responderam a questionários\nsobre aderência e atividade sexual. A incidência de HIV nos grupos foi avaliada. No grupo precoce,\na incidência foi de 1,2 casos por 100 pessoas-ano (IC de 90%; 0,4-2,9), em comparação com 9\ncasos por 100 pessoas-ano (IC de 90%: 6,1-12,8; p=0,0001) no grupo tardio. A diferença foi de 7,8\ncasos por 100 pessoas-ano (IC de 90%; 4,3-11,3). Com base no estudo apresentado, a teoria\nepidemiológica e conhecimentos correlatos, julgue o item a seguir. No estudo, ser soronegativo\npara o HIV é um exemplo de critério de inclusão, enquanto o caso de HIV é um exemplo de\ndesfecho. Uma possível opção para um critério de exclusão, que não está especificada, seria a\npresença de alergia conhecida ao fármaco utilizado no estudo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352338","number":"352338","sourceNumber":"352338","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo conduzido em 18 clínicas de saúde sexual, o objetivo foi avaliar a\neficácia da profilaxia pré-exposição para o\nvírus HIV (PrEP). Foram selecionados 546 homens que\nfazem sexo com homens e relataram não utilizar preservativo durante o coito anal nos últimos 90\ndias, sendo soronegativos para o HIV. Os participantes foram aleatoriamente divididos em dois\ngrupos: o grupo precoce e o grupo tardio. Aqueles no grupo precoce iniciaram o uso da PrEP\nimediatamente, enquanto o grupo tardio começou após um ano de observação. Ambos os grupos\nforam acompanhados mensalmente com exames laboratoriais e responderam a questionários\nsobre aderência e atividade sexual. A incidência de HIV nos grupos foi avaliada. No grupo precoce,\na incidência foi de 1,2 casos por 100 pessoas-ano (IC de 90%; 0,4-2,9), em comparação com 9\ncasos por 100 pessoas-ano (IC de 90%: 6,1-12,8; p=0,0001) no grupo tardio. A diferença foi de 7,8\ncasos por 100 pessoas-ano (IC de 90%; 4,3-11,3). Com base no estudo apresentado, a teoria\nepidemiológica e conhecimentos correlatos, julgue o item a seguir. O estudo demonstrou que\naproximadamente 12,8 pessoas precisaram receber PrEP tardia para evitar um caso de HIV em\ncomparação com o grupo que recebeu PrEP precoce.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352337","number":"352337","sourceNumber":"352337","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo conduzido em 18 clínicas de saúde sexual, o objetivo foi avaliar a\neficácia da profilaxia pré-exposição para o\nvírus HIV (PrEP). Foram selecionados 546 homens que\nfazem sexo com homens e relataram não utilizar preservativo durante o coito anal nos últimos 90\ndias, sendo soronegativos para o HIV. Os participantes foram aleatoriamente divididos em dois\ngrupos: o grupo precoce e o grupo tardio. Aqueles no grupo precoce iniciaram o uso da PrEP\nimediatamente, enquanto o grupo tardio começou após um ano de observação. Ambos os grupos\nforam acompanhados mensalmente com exames laboratoriais e responderam a questionários\nsobre aderência e atividade sexual. A incidência de HIV nos grupos foi avaliada. No grupo precoce,\na incidência foi de 1,2 casos por 100 pessoas-ano (IC de 90%; 0,4-2,9), em comparação com 9\ncasos por 100 pessoas-ano (IC de 90%: 6,1-12,8; p=0,0001) no grupo tardio. A diferença foi de 7,8\ncasos por 100 pessoas-ano (IC de 90%; 4,3-11,3). Com base no estudo apresentado, a teoria\nepidemiológica e conhecimentos correlatos, julgue o item a seguir. Embora seja recomendável,\nnem sempre é possível realizar o cegamento nos estudos. No caso do estudo apresentado, devido\na um dos grupos não receber medicamento por um ano, o cegamento não é viável.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352336","number":"352336","sourceNumber":"352336","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo conduzido em 18 clínicas de saúde sexual, o objetivo foi avaliar a\neficácia da profilaxia pré-exposição para o\nvírus HIV (PrEP). Foram selecionados 546 homens que\nfazem sexo com homens e relataram não utilizar preservativo durante o coito anal nos últimos 90\ndias, sendo soronegativos para o HIV. Os participantes foram aleatoriamente divididos em dois\ngrupos: o grupo precoce e o grupo tardio. Aqueles no grupo precoce iniciaram o uso da PrEP\nimediatamente, enquanto o grupo tardio começou após um ano de observação. Ambos os grupos\nforam acompanhados mensalmente com exames laboratoriais e responderam a questionários\nsobre aderência e atividade sexual. A incidência de HIV nos grupos foi avaliada. No grupo precoce,\na incidência foi de 1,2 casos por 100 pessoas-ano (IC de 90%; 0,4-2,9), em comparação com 9\ncasos por 100 pessoas-ano (IC de 90%: 6,1-12,8; p=0,0001) no grupo tardio. A diferença foi de 7,8\ncasos por 100 pessoas-ano (IC de 90%; 4,3-11,3). Com base no estudo apresentado, a teoria\nepidemiológica e conhecimentos correlatos, julgue o item a seguir. Para pesquisas envolvendo\nseres humanos, é obrigatória a aplicação de um Termo de Consentimento Livre e Esclarecido\n(TCLE). Além disso, é fundamental esclarecer todas as dúvidas relacionadas à pesquisa que o\nparticipante está prestes a se submeter e garantir que ele tenha o direito de sair do estudo a\nqualquer momento, mesmo sem a necessidade de apresentar qualquer justificativa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352334","number":"352334","sourceNumber":"352334","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo conduzido em 18 clínicas de saúde sexual, o objetivo foi avaliar a\neficácia da profilaxia pré-exposição para o\nvírus HIV (PrEP). Foram selecionados 546 homens que\nfazem sexo com homens e relataram não utilizar preservativo durante o coito anal nos últimos 90\ndias, sendo soronegativos para o HIV. Os participantes foram aleatoriamente divididos em dois\ngrupos: o grupo precoce e o grupo tardio. Aqueles no grupo precoce iniciaram o uso da PrEP\nimediatamente, enquanto o grupo tardio começou após um ano de observação. Ambos os grupos\nforam acompanhados mensalmente com exames laboratoriais e responderam a questionários\nsobre aderência e atividade sexual. A incidência de HIV nos grupos foi avaliada. No grupo precoce,\na incidência foi de 1,2 casos por 100 pessoas-ano (IC de 90%; 0,4-2,9), em comparação com 9\ncasos por 100 pessoas-ano (IC de 90%: 6,1-12,8; p=0,0001) no grupo tardio. A diferença foi de 7,8\ncasos por 100 pessoas-ano (IC de 90%; 4,3-11,3). Com base no estudo apresentado, a teoria\nepidemiológica e conhecimentos correlatos, julgue o item a seguir. Os participantes que,\neventualmente, demonstraram baixa adesão à PrEP no estudo apresentado devem ser excluídos\nda análise dos dados, a fim de preservar o verdadeiro efeito da droga nos resultados. No entanto,\nnão é recomendada a mudança de grupo durante o estudo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352333","number":"352333","sourceNumber":"352333","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo conduzido em 18 clínicas de saúde sexual, o objetivo foi avaliar a\neficácia da profilaxia pré-exposição para o\nvírus HIV (PrEP). Foram selecionados 546 homens que\nfazem sexo com homens e relataram não utilizar preservativo durante o coito anal nos últimos 90\ndias, sendo soronegativos para o HIV. Os participantes foram aleatoriamente divididos em dois\ngrupos: o grupo precoce e o grupo tardio. Aqueles no grupo precoce iniciaram o uso da PrEP\nimediatamente, enquanto o grupo tardio começou após um ano de observação. Ambos os grupos\nforam acompanhados mensalmente com exames laboratoriais e responderam a questionários\nsobre aderência e atividade sexual. A incidência de HIV nos grupos foi avaliada. No grupo precoce,\na incidência foi de 1,2 casos por 100 pessoas-ano (IC de 90%; 0,4-2,9), em comparação com 9\ncasos por 100 pessoas-ano (IC de 90%: 6,1-12,8; p=0,0001) no grupo tardio. A diferença foi de 7,8\ncasos por 100 pessoas-ano (IC de 90%; 4,3-11,3). Com base no estudo apresentado, a teoria\nepidemiológica e conhecimentos correlatos, julgue o item a seguir. Uma das limitações do estudo\nem questão são as perdas por abandono de seguimento. Quando isso ocorre, para minimizar o\nprejuízo na análise de dados, pode-se optar por repetir o último valor aferido como se esse fosse o\nresultado encontrado nos momentos em que o sujeito não compareceu.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352406","number":"352406","sourceNumber":"352406","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo conduzido em 18 clínicas de saúde sexual, o objetivo foi avaliar a\neficácia da profilaxia pré-exposição para o\nvírus HIV (PrEP). Foram selecionados 546 homens que\nfazem sexo com homens e relataram não utilizar preservativo durante o coito anal nos últimos 90\ndias, sendo soronegativos para o HIV. Os participantes foram aleatoriamente divididos em dois\ngrupos: o grupo precoce e o grupo tardio. Aqueles no grupo precoce iniciaram o uso da PrEP\nimediatamente, enquanto o grupo tardio começou após um ano de observação. Ambos os grupos\nforam acompanhados mensalmente com exames laboratoriais e responderam a questionários\nsobre aderência e atividade sexual. A incidência de HIV nos grupos foi avaliada. No grupo precoce,\na incidência foi de 1,2 casos por 100 pessoas-ano (IC de 90%; 0,4-2,9), em comparação com 9\ncasos por 100 pessoas-ano (IC de 90%: 6,1-12,8; p=0,0001) no grupo tardio. A diferença foi de 7,8\ncasos por 100 pessoas-ano (IC de 90%; 4,3-11,3). Com base no estudo apresentado, a teoria\nepidemiológica e conhecimentos correlatos, julgue o item a seguir. A grande vantagem da\nrandomização é a capacidade de \"equilibrar\" os grupos de estudo, distribuindo os participantes com\ncaracterísticas diferentes entre eles, mesmo que essas características não sejam percebidas pelo\npesquisador, ajudando a evitar vieses.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-343467","number":"343467","sourceNumber":"343467","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere o seguinte estudo: Em 1975 foram avaliadas 40.268 mulheres com 20 anos\nou mais, enquanto as amostras de 1989 e 1997\nforam de 7.160 e 5.137 mulheres, respectivamente.\nPara cada um dos levantamentos, foram calculadas as proporções de mulheres subnutridas (índice\nde massa corpórea ? IMC < 18,5 kg/m2) e de mulheres obesas (IMC > 30 kg/m2), agrupadas por\nnível de renda. Observou-se uma clara mudança na condição nutricional das mulheres brasileiras:\nem 1975 havia 2 mulheres subnutridas para cada mulher obesa, enquanto em 1997 a relação\npassou a ser de 2 casos de obesidade para cada caso de subnutrição. Em 1997, as mulheres de\nmenor renda apresentavam risco significativamente maior de desnutrição e de obesidade,\ncomparadas às mais ricas. O tipo de estudo realizado é:","options":{"A":"Ensaios clínicos.","B":"Estudos de coorte.","C":"Estudos caso-controle.","D":"Estudos de corte transversal."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-343469","number":"343469","sourceNumber":"343469","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Com relação aos tipos de estudos epidemiológicos, é CORRETO afirmar:","options":{"A":"Nos estudos de corte transversal é sempre possível estabelecer relações de causa e efeito.","B":"Os estudos de série de casos são estudos mais complexos, sendo irrelevantes para descrever\nprocedimentos inovadores testados com um pequeno número de pacientes.","C":"Os estudos do tipo caso-controle são recomendados principalmente para a pesquisa de fatores\nde risco para doenças raras e doenças\ncongênitas.","D":"Os estudos de coorte geralmente apresentam baixo custo e tempo abreviado para a execução\ndo estudo."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-343471","number":"343471","sourceNumber":"343471","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma alternativa para controlar os fatores de confusão em um estudo observacional é:","options":{"A":"Amostra aleatória.","B":"Viés de seleção.","C":"Alocação randomizada.","D":"Análise multivariada."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-273352","number":"273352","sourceNumber":"273352","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um intensivista pesquisador seleciona um grande grupo de pacientes submetidos a\nventilação mecânica e vai analisar se diversos fatores conseguem predizer o surgimento de\npneumonia. Qual o desenho deste estudo?","options":{"A":"Estudo clínico experimental.","B":"Estudo observacional descritivo.","C":"Estudo analítico de coorte.","D":"Estudo experimental não randomizado."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-273353","number":"273353","sourceNumber":"273353","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Seguindo a hierarquia das evidências em Medicina Baseada em Evidência, assinale a\nalternativa CORRETA.","options":{"A":"Os estudos de coorte são menos relevantes em termos metodológicos que os relatos de caso.","B":"Os ensaios clínicos randomizados (ECR) representam o mais alto nível da pirâmide de evidência\nencontrada.","C":"As revisões sistemáticas com metanálise são estudos desenvolvidos a partir de estudos\nprimários.","D":"Os estudos de caso controle, ECR e Coorte são exemplos de estudos observacionais."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-268927","number":"268927","sourceNumber":"268927","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na cidade de Hope Valley, nos Estados Unidos da América, com 500 mil habitantes,\nalguns indivíduos têm apresentado sinais e\nsintomas respiratórios estranhos. Essa doença acomete\nmais adolescentes. Duzentos indivíduos já manifestaram os mesmos sinais e sintomas, mas não se\ntem ideia da quantidade de afetados, pois nem todos procuraram o serviço de saúde. Eles moram\nem diferentes bairros da cidade. Os médicos não identificaram que doença é essa, mas\ndescartaram muitas que são conhecidas. Eles sabem que os indivíduos apresentam a doença por\nmais de 40 dias, têm falta de ar, alterações neurológicas, astenia, taquicardia e não há febre. Não\nfoi identificada muita coisa a respeito da história natural da doença até o momento, inclusive,\nfator\netiológico e nem fatores de exposição. Considerando esse histórico, para a investigação\nepidemiológica desse evento, qual modelo de estudo epidemiológico é mais apropriado, para o\nlevantamento de hipóteses iniciais e qual a justificativa dessa escolha?","options":{"A":"Ecológico, porque é mais fácil e ágil para se obterem os dados agregados em populações de\ngrande tamanho.","B":"Transversal, porque permite fazer inferências estatísticas a partir de amostras representativas\nda\npopulação e obter razões de prevalências.","C":"Caso-controle, porque se podem investigar diversos fatores ou exposições passadas suspeitas e\npermite estimar o que aconteceu no passado próximo.","D":"Coorte, porque nele a relação entre exposição e doença é melhor definida e permite o cálculo do\nrisco relativo, que é a melhor medida de efeito da relação exposição ou fator e doença ou condição.","E":"Série de casos, porque nele se pode agrupar os mesmos sinais e sintomas e as diferentes\nmanifestações."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-273357","number":"273357","sourceNumber":"273357","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma curva ROC (receiver operating characteristic) é construída para um novo teste\ndesenvolvido para diagnosticar a doença X. Todas as seguintes afirmações sobre a curva ROC são\nverdadeiras, EXCETO:","options":{"A":"Uma crítica à curva ROC é que ela foi desenvolvida para testar apenas um teste ou parâmetro\nclínico, com exclusão de outros dados\npotencialmente relevantes.","B":"A curva ROC permite a seleção de um valor limite para um teste que produz a melhor\nsensibilidade com o menor número de testes falso- positivos.","C":"Os eixos da curva ROC são sensibilidade versus 1 - especificidade","D":"A curva ROC ideal terá um valor de 0,5."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-266488","number":"266488","sourceNumber":"266488","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Wilson, de 63 anos de idade, negro, aposentado, procurou uma unidade básica de\nsaúde (UBS) na região administrativa de São\nSebastião, por apresentar tosse havia 4 semanas,\nfebre vespertina e um episódio de hemoptise. Luísa, médica recém-formada, o atendeu no\nconsultório reservado para casos suspeitos de covid-19. Wilson realizou o teste rápido IgG/IgM\npara SARS-CoV-2, que resultou positivo. Considerando que a sensibilidade do referido teste rápido\nseja de 80% e que a sua especificidade seja de 90%, julgue o item a seguir, referentes ao caso\nclínico apresentado. O teste rápido para SARS-CoV-2 apresenta maior valor preditivo positivo\n(VPP) quando realizado em um contexto de pandemia do que fora desse período.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-266489","number":"266489","sourceNumber":"266489","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Wilson, de 63 anos de idade, negro, aposentado, procurou uma unidade básica de\nsaúde (UBS) na região administrativa de São\nSebastião, por apresentar tosse havia 4 semanas,\nfebre vespertina e um episódio de hemoptise. Luísa, médica recém-formada, o atendeu no\nconsultório reservado para casos suspeitos de covid-19. Wilson realizou o teste rápido IgG/IgM\npara SARS-CoV-2, que resultou positivo. Considerando que a sensibilidade do referido teste rápido\nseja de 80% e que a sua especificidade seja de 90%, julgue o item a seguir, referentes ao caso\nclínico apresentado. Considerando-se que a prevalência de covid-19 em São Sebastião seja de\n5%, é correto afirmar que, em um universo de 200.000 testes realizados nessa região\nadministrativa, o número de falsos-positivos é de 19.000.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-274672","number":"274672","sourceNumber":"274672","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O estudo observacional onde a pesquisa tem como escopo analisar e verificar a\nexposição passiva à fumaça de cigarro e a\nincidência de câncer no pulmão, selecionando um grupo\nde indivíduos expostos ao fator de risco e outro grupo de não expostos, é denominado:","options":{"A":"Estudo ecológico.","B":"Ensaio clínico.","C":"Estudo de coorte.","D":"Estudo de comunidade."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-274673","number":"274673","sourceNumber":"274673","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Criança, 8 anos, com quadro de asma, pode ser apontado como determinante causal\nproximal da doença:","options":{"A":"Fator socioeconômico.","B":"Fator biológico.","C":"Fator hereditário.","D":"Evento infeccioso prévio."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-266503","number":"266503","sourceNumber":"266503","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considerando que uma das vacinas contra a covid-19 esteja na fase III de teste, julgue\no seguinte item. A fase III dos ensaios clínicos\né conhecida como farmacovigilância e consiste em\num estudo do tipo caso-controle, com a ampliação do número de indivíduos assintomáticos\nparticipantes da pesquisa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-274685","number":"274685","sourceNumber":"274685","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considerando as medidas de associação entre exposição e doença, quanto ao risco\nrelativo, é CORRETO afirmar:","options":{"A":"Fornece a diferença entre as medidas de frequência de um grupo exposto a um fator de risco e\nde um grupo não exposto àquele fator.","B":"Fornece o risco de desenvolver a doença devido, exclusivamente, ao fator de risco estudado,\napós a remoção do risco devido a outras\ncausas.","C":"Fornece a força da associação entre a exposição e a doença.","D":"Permite avaliar o impacto de uma intervenção que vise eliminar a exposição ao fator de risco."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-274686","number":"274686","sourceNumber":"274686","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em textos de epidemiologia, o termo ?fator de risco? é frequentemente usado para\ndesignar:","options":{"A":"Uma exposição que apresenta associação causal com uma doença, ou seja, pessoas expostas\nao fator de risco têm maior probabilidade de\ndesenvolver a doença do que pessoas não expostas a\ntal fator.","B":"Qualquer fator ou característica que possa estar associado à doença, como idade, contato\nprofissional com metais pesados, infecção viral na gravidez, ambiente familiar ou classe social.","C":"O indivíduo que apresenta a doença ou outro evento de interesse.","D":"Qualquer evento ou resultado de interesse, como o início de uma doença propriamente dita,\nsuas diversas formas de evolução, óbito ou a decisão de procurar atendimento médico."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-244507","number":"244507","sourceNumber":"244507","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Estudo que identifica indivíduos com a doença (casos) e, para efeito de comparar,\nindivíduos sem a doença (controles) e, depois,\ndetermina-se (mediante entrevista ou consulta a\nprontuários) qual é a odds da exposição entre casos e controles. Essas informações referem-se ao\nestudo denominado","options":{"A":"coorte.","B":"secional.","C":"ecológico.","D":"caso-controle.","E":"analítico."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-227443","number":"227443","sourceNumber":"227443","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considerando a prática de saúde baseada em evidências, empregada para apoiar a\nprática clínica, a tomada de decisão, bem como os processos de ensino-aprendizagem, julgue o\nitem a seguir. Em pacientes classificados como de maior risco cardiovascular, quanto menor for o\nnúmero necessário para tratar (NNT), maior será o benefício da terapia com uso de estatinas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-227444","number":"227444","sourceNumber":"227444","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considerando a prática de saúde baseada em evidências, empregada para apoiar a\nprática clínica, a tomada de decisão, bem como os processos de ensino-aprendizagem, julgue o\nitem a seguir. Opiniões e decisões manifestadas com base em evidências clínicas e estudos\ndescritivos constantes de pareceres técnicos elaborados por especialistas de notória competência\ntécnica constituem evidência de nível I.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-212038","number":"212038","sourceNumber":"212038","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Testes Rápidos (TRs) para diagnóstico da dengue estão disponíveis no mercado; no\nentanto, para uma adequada gestão clínica dos casos, os médicos devem escolher um TR\nacurado. Nesse contexto, para avaliar a acurácia de determinado TR, um estudo foi conduzido com\n452 pessoas com suspeita de dengue. Todas foram submetidas a exame considerado padrão-ouro,\ne apenas 206 delas realmente apresentaram dengue. Ademais, o TR foi positivo em 161 pessoas,\ndas quais quatro tiveram resultados considerados falsos-positivos. Nessa situação hipotética, a\nprobabilidade de uma pessoa com TR positivo ter a doença superou os 97%.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-212133","number":"212133","sourceNumber":"212133","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Testes Rápidos (TRs) para o diagnóstico da dengue estão disponíveis no mercado; no\nentanto, para uma adequada gestão clínica dos casos, os médicos devem escolher um TR\nacurado. Nesse contexto, para avaliar a acurácia de determinado TR, um estudo foi conduzido com\n452 pessoas com suspeita de dengue. Todas foram submetidas a exame considerado padrão-ouro,\ne apenas 206 delas realmente apresentaram dengue. Ademais, o TR foi positivo em 161 pessoas,\ndas quais quatro tiveram resultados considerados falsos positivos. Nessa situação hipotética, a\nprobabilidade de uma pessoa com o teste negativo não ter a doença foi de aproximadamente 83%.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-212030","number":"212030","sourceNumber":"212030","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Testes Rápidos (TRs) para o diagnóstico da dengue estão disponíveis no mercado; no\nentanto, para uma adequada gestão clínica dos casos, os médicos devem escolher um TR\nacurado. Nesse contexto, para avaliar a acurácia de determinado TR, um estudo foi conduzido com\n452 pessoas com suspeita de dengue. Todas foram submetidas a exame considerado padrão-ouro,\ne apenas 206 delas realmente apresentaram dengue. Ademais, o TR foi positivo em 161 pessoas,\ndas quais quatro tiveram resultados considerados falsos-positivos. Nessa situação hipotética, o TR\napresentou uma alta sensibilidade (98,4%) e um alto valor preditivo positivo (97,5%),\nproporcionando aos clínicos um TR acurado, com alta probabilidade de detectar a doença e de\ndescartar a hipótese diagnóstica quando o resultado for negativo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-212122","number":"212122","sourceNumber":"212122","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"As infecções pneumocócicas em idosos preocupam os profissionais de saúde devido\nao risco de complicações como a pneumonia.\nNesse contexto, um ensaio clínico randomizado foi\nconduzido para avaliar a eficácia de uma nova vacina antipneumocócica, considerando a\nprevenção da Pneumonia Pneumocócica (PP) como desfecho. Os idosos foram divididos\nrandomicamente em dois grupos: um grupo de 502 idosos foi vacinado, e o segundo grupo,\ncomposto por 504 idosos, recebeu placebo. Entre os idosos não vacinados, 37 foram\ndiagnosticados com PP e, entre os vacinados, 488 permaneceram saudáveis. O acompanhamento\nde ambos os grupos foi realizado por 26 meses. Com relação às informações do estudo\nanteriormente descrito e à vacina antipneumocócica, julgue o item subsequente. Com base nos\nresultados apresentados no estudo em questão, a vacina apresentou uma eficácia (redução relativa\ndo risco) de aproximadamente 60%.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-212126","number":"212126","sourceNumber":"212126","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"As infecções pneumocócicas em idosos preocupam os profissionais de saúde devido\nao risco de complicações como a pneumonia.\nNesse contexto, um ensaio clínico randomizado foi\nconduzido para avaliar a eficácia de uma nova vacina antipneumocócica, considerando a\nprevenção da Pneumonia Pneumocócica (PP) como desfecho. Os idosos foram divididos\nrandomicamente em dois grupos: um grupo de 502 idosos foi vacinado, e o segundo grupo,\ncomposto por 504 idosos, recebeu placebo. Entre os idosos não vacinados, 37 foram\ndiagnosticados com PP e, entre os vacinados, 488 permaneceram saudáveis. O acompanhamento\nde ambos os grupos foi realizado por 26 meses. Com relação às informações do estudo\nanteriormente descrito e à vacina antipneumocócica, julgue o item subsequente. Conclui-se, com\nbase nos dados apresentados pelo estudo em apreço, que 10 idosos precisam receber a vacina\nantipneumocócica para que um caso de pneumonia pneumocócica em idoso seja evitado.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-177252","number":"177252","sourceNumber":"177252","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A prática médica atual deve ser embasada nos conhecimentos advindos da medicina\nbaseada em evidências. Embora não se devam\ndesconsiderar as particularidades advindas da\nprática, os conhecimentos obtidos com estudos científicos de boa qualidade são fundamentais para\ngarantir uma boa assistência médica a toda a população, mesmo quando assistida por um médico\npouco experiente. Com base no exposto e considerando os diversos desenhos metodológicos dos\nestudos científicos, assinale a alternativa correta.","options":{"A":"Os estudos de coorte classicamente iniciam-se com a seleção de um grupo que apresente\ndeterminado desfecho, para então se verificarem os possíveis fatores de risco.","B":"A séries de caso são estudos experimentais.","C":"Para se aumentar a qualidade dos ensaios clínicos, eles idealmente devem ser randomizados e,\nsempre que possível, devem apresentar cegamento para pacientes, médicos assistentes e\nprofissionais que realizam a análise estatística.","D":"Ensaios clínicos randomizados realizados em ambiente controlado, com medicações\nconsumidas sob observação profissional,\ncostumam ter uma boa validade interna, o que gera boa\nvalidade externa.","E":"Um estudo transversal é idealizado para avaliar o efeito de uma dada intervenção em uma\npopulação."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-177249","number":"177249","sourceNumber":"177249","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Durante a investigação de doenças e nos programas de rastreamento na atenção\nbásica, podem-se utilizar diversas estratégias no que se refere à solicitação de exames\ncomplementares. A respeito dessas estratégias, assinale a alternativa CORRETA:","options":{"A":"A solicitação de vários exames complementares, simultaneamente, com um mesmo objetivo\ndiagnóstico, configura uma estratégia de testes em\nparalelo, que costuma ser mais específica que a\nestratégia de testes em série.","B":"Durante o planejamento de uma estratégia de rastreio de doenças, deve-se optar por testes com\ngrande especificidade, em detrimento da sensibilidade.","C":"A especificidade e a sensibilidade são características inerentes a um teste, independentemente\nda prevalência da doença em determinada população.","D":"Um dos meios de se analisar a relação entre a sensibilidade e a especificidade dos diversos\nvalores de referência de um teste de\ndiagnóstico quantitativo é a Receiver Operator Characteristic\nCurve (ROC), na qual plota-se a sensibilidade no eixo X e a especificidade no eixo Y.","E":"A estratégia de testes em série é mais indicada para triagem de patologias, por ter alta\nsensibilidade."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-183949","number":"183949","sourceNumber":"183949","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Julgue o item a seguir, acerca de vigilância epidemiológica e de epidemiologia clínica:\nestudos desenhados para a avaliação de eficácia de tratamentos são realizados apenas por meio\nde desenhos longitudinais.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-168457","number":"168457","sourceNumber":"168457","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A figura abaixo representa as fases da Influenza Pandêmica de 2009 estabelecidas\npela Organização Mundial da Saúde (OMS).\nAtualmente, a fase de alerta pandêmico para H1N1 é\na de pós-pandemia (conforme imagem no caderno de questões). Considerando a figura e as\ninformações apresentadas, assinale a alternativa correta sobre o estado de preparação e resposta\nà pandemia de H1N1.","options":{"A":"Na fase 3, a transmissão direta de pessoa a pessoa do vírus recombinante já é suficiente,\nsegundo a OMS, para sustentar surtos em comunidades.","B":"Na fase 4, a OMS realiza o desenvolvimento e a distribuição de insumos voltados para a\nprodução de vacinas específicas para controle da pandemia.","C":"Na fase 5, a maioria dos países está sob risco de ocorrência dessa doença e, por essa razão,\nela é considerada como pandêmica pela OMS.","D":"Na fase 6, a OMS agiliza todo o processo de revisão da disseminação do vírus, por meio de\ntransmissão direta, para controle de pandemia."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-158050","number":"158050","sourceNumber":"158050","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudante de medicina do terceiro ano resolveu iniciar uma pesquisa junto ao\nserviço de nefrologia de seu\nhospital-escola. Nessa pesquisa, resolveu-se acompanhar todos os\ntransplantados renais da instituição a partir de determinada data, separando-as em dois grupos:\naqueles que apresentavam anticorpos anti-HLA específicos contra seu doador, já existentes antes\ndo transplante renal, e os pacientes que eram desprovidos de tais anticorpos, comparando\ndesfechos posteriores relativos a mortalidade e sobrevida do enxerto. Considerando essa situação\nhipotética, determina-se que esse estudo se trata de um(a):","options":{"A":"Ensaio clínico randomizado.","B":"Estudo de coorte.","C":"Estudo caso-controle.","D":"Série de casos.","E":"Estudo transversal."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-157970","number":"157970","sourceNumber":"157970","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Entre as diversas questões estudadas no desenvolvimento de um programa de\nrastreamento universal, encontra-se o NNR (número\nnecessário para rastrear) que representa o\nnúmero de pessoas que devem ser rastreadas por certo período, para que se evite um determinado\ndesfecho. Em relação ao NNR, assinale a alternativa CORRETA.","options":{"A":"Depende, entre outros fatores, da prevalência da patologia em questão e da efetividade da\nintervenção disponível.","B":"Não é influenciado pela acurácia do teste utilizado no rastreio, sendo uma característica\nintrínseca da patologia.","C":"Por definição, é o oposto da redução do risco absoluto (RRA).","D":"É diretamente proporcional à prevalência da doença estudada.","E":"Não pode ser utilizado no cálculo do impacto econômico das políticas de rastreamento."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-158000","number":"158000","sourceNumber":"158000","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"No decorrer da análise de certo estudo científico, várias características devem ser\nobservadas durante sua interpretação, para que\no médico determine se os resultados desse estudo\ndevem ser aplicados em sua prática cotidiana. Acerca dessas questões, assinale a alternativa\nCORRETA.","options":{"A":"Ensaios clínicos randomizados com bom desenho de estudo e realizados em ambiente\ncontrolado (intra-hospitalar) costumam ter boa validade\ninterna, mas não necessariamente boa\nvalidade externa.","B":"A existência de uma relação estatisticamente significante entre duas variáveis indica que elas\napresentam uma relação de causalidade entre si.","C":"A existência de uma diferença estatisticamente significante entre dois grupos representa que as\nvariáveis estudadas apresentam uma relação que pode ser considerada clinicamente relevante.","D":"A existência de um p > 0,05 indica que dois grupos não apresentam diferença estatística para\ndeterminada variável, logo, são iguais.","E":"A determinação de diferenças estatisticamente significativas deve ser realizada apenas em\nensaios clínicos randomizados."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-168446","number":"168446","sourceNumber":"168446","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um homem com 54 anos de idade, casado, sem história familiar de câncer, solicita ao\nmédico de família e comunidade que o atende em consulta de rotina, em uma Unidade Básica de\nSaúde, exame de sangue para \"checar se tem câncer de próstata\". Tomando como referência que\na sensibilidade e a especificidade da dosagem do antígeno prostático específico (PSA) pelo método\ndo laboratório municipal, com ponto de corte em 4 ng/dL, são, respectivamente, 20% e 94%, com\nvalor preditivo positivo de 33%, assinale a opção em que é apresentada a orientação que deve ser\ndada pelo médico ao paciente acerca do rastreamento de câncer de próstata.","options":{"A":"A probabilidade de o resultado da dosagem do PSA estar acima de 4 ng/dL, no caso de o\npaciente ter câncer de próstata, é de 80%.","B":"A probabilidade de o paciente ser submetido desnecessariamente a biópsia, caso o resultado\nseja positivo para câncer de próstata, é de 67%.","C":"A probabilidade de o paciente ter câncer de próstata, caso o resultado da dosagem do PSA\nesteja acima de 4 ng/dL, é de 94%.","D":"A probabilidade de o paciente ter câncer de próstata e este não ser diagnosticado a partir da\ndosagem de PSA é de 33%."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-133965","number":"133965","sourceNumber":"133965","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale a alternativa correta quanto à área responsável pelo estudo de fatores causais\nque explicam a distribuição de enfermidades,\nas desigualdades dos níveis de saúde entre grupos\npopulacionais, a relação das situações de saúde, a identificação das causas, o modo como as\niniquidades são produzidas e a eficácia das intervenções pela saúde pública.","options":{"A":"Estudo epidemiológico observacional.","B":"Investigação epidemiológica.","C":"Epidemiologia descritiva.","D":"Epidemiologia analítica.","E":"Epidemiologia clínica."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-111266","number":"111266","sourceNumber":"111266","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Para obter melhor evidência científica sobre uma nova droga, um médico fará buscas\nna Internet. As palavras chave que o ajudarão a\nencontrar artigos de maior validade são:","options":{"A":"Randomização, odds ratio, ocultamento.","B":"Randomização, pareamento, odds ratio.","C":"Intenção de tratamento, placebo, pareamento.","D":"Placebo, duplo-cego, pareamento.","E":"Randomização, duplo-cego, ocultamento."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-111293","number":"111293","sourceNumber":"111293","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo epidemiológico acompanhou uma população de 49.000 recém-nascidos nos\nEstados Unidos com diagnóstico de asfixia neonatal (Apgar baixo), e os sem este diagnóstico\n(Apgar alto), com exames periódicos até os setes anos. Os resultados indicaram que 80% dos\nrecém-nascidos com Apgar baixo que sobreviveram não apresentaram retardo no desenvolvimento\nmental. Que tipo de estudo corresponde melhor à pesquisa relatada?","options":{"A":"Ensaio clínico.","B":"Estudo caso-controle.","C":"Estudo ecológico.","D":"Estudo de coorte.","E":"Estudo epidemiológico descritivo."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-111300","number":"111300","sourceNumber":"111300","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo de coorte sobre o efeito da vacinação no prognóstico de uma determinada\ndoença revelou que, dentre os 500 vacinados,\n50 morreram no prazo de 10 dias após a\nmanisfestação da doença. Já dentre as 400 pessoas não vacinadas, 100 morreram em\nconsequência dessa doença. Ao se montar uma tabela 2 X 2 e calcular a medida apropriada para\navaliar a associação entre vacinação e óbito por essa doença, obteve-se o valor:","options":{"A":"0,52.","B":"0,40.","C":"2,78.","D":"1,34.","E":"2,12."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-111311","number":"111311","sourceNumber":"111311","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Correlacione a 1ª e a 2ª colunas e assinale a resposta que apresenta a sequência\ncorreta: I. Estudo Transversal; II. Estudo\nCaso-controle; III. Estudo Ecológico; IV. Ensaio Clínico; 1.\nTrata-se de um estudo experimental. 2. A medida de associação mais apropriada para esse tipo de\nestudo é o odss ratio. 3. Trata-se de um estudo observacional. 4. Observação direta de\ndeterminada quantidade planejada de indivíduos em uma única oportunidade.","options":{"A":"I.1; II.2; III.4; IV.3;","B":"I.4; II.2; III. 1; IV.3;","C":"I.4; II.2; III.3; IV.1;","D":"I.2; II.1; III.3; IV.4;","E":"I.4; II.1; III.2; IV.3."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-111327","number":"111327","sourceNumber":"111327","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Segundo a Organização Mundial de Saúde, qual das seguintes afirmativas abaixo NÃO\né um requisito para estabelecimento de um\nprograma de rastramento para uma determinada\ndoença (screening)?","options":{"A":"Deve existir um tratamento para a doença.","B":"O programa deve ser financiado pelo governo.","C":"A doença deve ser um importante problema de saúde pública.","D":"O teste deve ser aceitável para a população.","E":"A história natural da doença deve ser bem compreendida."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-368160","number":"368160","sourceNumber":"368160","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo que realizou o monitoramento da saúde genética de humanos expostos\nacidentalmente à radiação ionizante de Césio-137 em Goiânia foi um dos diversos realizados a\npartir do evento ocorrido em 1987, e até hoje considerado o maior acidente radiológico do mundo.\nEsse estudo é do tipo","options":{"A":"transversal.","B":"coorte.","C":"caso controle.","D":"ecológico."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-368161","number":"368161","sourceNumber":"368161","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Analise as medidas estatísticas a seguir. I. Odds ratio II. Risco relativo III. Risco\natribuível IV. Fração atribuível na população\n?A chance de desenvolver doença no grupo de\nexpostos é maior ou menor do que no grupo de não expostos? e ?Qual a incidência da doença\natribuível à população?? caracterizam, respectivamente, as medidas estatísticas","options":{"A":"I e III, apenas.","B":"II e IV, apenas.","C":"I e IV, apenas.","D":"II e III, apenas."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352171","number":"352171","sourceNumber":"352171","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo caso-controle, a exposição a risco alimentar foi determinada pela\naplicação de um questionário aos\nparticipantes contendo questões do tipo \"no último ano, com que\nfrequência você ingeriu (alimento x): (a) diariamente; (b) semanalmente; (c) ocasionalmente; (d)\nnenhuma vez\". Esse tipo de aferição da exposição tem o potencial de inserir qual tipo de viés nesse\nestudo?","options":{"A":"Viés de seleção.","B":"Viés de informação.","C":"Viés de confusão.","D":"Viés de interação."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-359187","number":"359187","sourceNumber":"359187","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O acidente com césio-137 que ocorreu em Goiânia, no ano de 1987, é considerado o\nmaior acidente radiológico do mundo. Vários estudos foram desenvolvidos com a população\nexposta como um realizado por Curado (2019) sobre a incidência de casos de câncer na população\ncontaminada. É CORRETO afirmar que este estudo é do tipo:","options":{"A":"Transversal.","B":"Coorte.","C":"Caso controle.","D":"Ecológico."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352172","number":"352172","sourceNumber":"352172","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo que analisou o efeito de estatina na prevenção de acidente vascular\nencefálico fatal e não fatal, encontramos a seguinte figura: Com base na análise apresentada na\nfigura, trata-se de qual tipo de estudo?","options":{"A":"Ensaio clínico randomizado.","B":"Estudo de coorte.","C":"Estudo caso-controle.","D":"Revisão sistemática com metanálise."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352173","number":"352173","sourceNumber":"352173","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em relação à farmacoterapia para o tabagismo, temos os seguintes valores\naproximados de número necessário para\ntratar (NNT): reposição de nicotina (NNT=15); vareniclina\n(NNT=9); bupropiona (NNT=11); nortriptilina (NNT=11). Considerando apenas a informação de NNT\ndas medicações, qual seria a última a ser indicada dentre as citadas no tratamento do tabagismo?","options":{"A":"Reposição de nicotina.","B":"Vareniclina.","C":"Bupropina.","D":"Nortriptilina."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-359189","number":"359189","sourceNumber":"359189","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"É CORRETO afirmar que, em um estudo sobre a população cadastrada, as variáveis\n\"sexo\" e \"grau de instrução\", são\nrespectivamente classificadas como:","options":{"A":"Ordinal e discreta.","B":"Nominal e ordinal.","C":"Discreta e contínua.","D":"Contínua e nominal."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352174","number":"352174","sourceNumber":"352174","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em ensaios clínicos, a apresentação do tamanho do efeito é geralmente seguida da\napresentação do intervalo de confiança, como no exemplo \"(risco relativo [RR]: 1,39; IC95%:\n\n1,06-1,82)\". Sobre o intervalo de confiança, é certo afirmar que, quanto maior sua amplitude,\nmaior:","options":{"A":"A imprecisão acerca do verdadeiro tamanho do efeito na população de interesse.","B":"O poder estatístico da amostra para a determinação do tamanho do efeito.","C":"O tamanho amostral do estudo.","D":"A certeza sobre o verdadeiro tamanho do efeito na amostra do estudo."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-359190","number":"359190","sourceNumber":"359190","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"É CORRETO afirmar que, em um estudo epidemiológico, a chance de desenvolver\ndoença no grupo de expostos é maior ou menor\ndo que no grupo de não expostos, é representado\npor:","options":{"A":"Razão de chances (odds ratio).","B":"Risco relativo.","C":"Risco atribuível.","D":"Fração atribuível na população."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352175","number":"352175","sourceNumber":"352175","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os estudos transversais são adequados para medir ou identificar:","options":{"A":"Relação causa-efeito.","B":"Tendência temporal de uma doença.","C":"Prevalência de uma doença.","D":"Efeito de uma terapia em uma doença."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-352176","number":"352176","sourceNumber":"352176","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Não é um passo essencial na prática da medicina baseada em evidências no cotidiano\ndo médico:","options":{"A":"Formular questões clínicas.","B":"Realizar pesquisa básica com modelos animais.","C":"Analisar criticamente estudos científícos.","D":"Rastrear a literatura em busca das melhores evidências científicas."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-351631","number":"351631","sourceNumber":"351631","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os ensaios clínicos randomizados são, geralmente, considerados o ?padrão-ouro? dos\ndelineamentos de estudos, porém, possuem particularidades no delineamento e condução. Sobre\nos ensaios clínicos randomizados, é CORRETO afirmar que:","options":{"A":"O principal objetivo da randomização em um ensaio clínico randomizado é reduzir o viés de\nseleção na alocação para o tratamento.","B":"O delineamento de crossover planejado em um ensaio clínico randomizado só é possível quando\na nova terapia em estudo for cirúrgica.","C":"O ensaio clínico randomizado é considerado o delineamento ideal para avaliação da taxa de\nprevalência e incidência da doença.","D":"Em um ensaio clínico randomizado não há preocupações com a validade externa do estudo, já\nque a randomização permite a generalização dos resultados."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-359222","number":"359222","sourceNumber":"359222","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma faculdade desenvolveu um novo teste para diagnóstico de HIV com sensibilidade\nde 100% e Especificidade de 80% e resolveu\ntestar toda a população da cidade com 4.000.000 de\nhabitantes. Supondo que a prevalência do HIV, nesta população, seja de 0,5%, assinale a\nalternativa que apresenta CORRETAMENTE quantos verdadeiramente positivos e falso positivos\nsão esperados encontrar respectivamente.","options":{"A":"20.000 e 398.000.","B":"10.000 e 800.000.","C":"40.000 e 320.000.","D":"20.000 e 796.000."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-336265","number":"336265","sourceNumber":"336265","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um pesquisador diz que um determinado exame laboratorial tem sensibilidade de 99%\npara o diagnóstico de uma doença. Devido o alto valor, ele deseja utilizar esse exame para\nrastreamento da mesma. Baseado nessa afirmativa, é correto afirmar:","options":{"A":"Esse exame é indicado para rastreamento, pois apenas 1% dos indivíduos que têm a doença\napresentará resultado negativo no teste.","B":"Esse exame é mais indicado para confirmação diagnóstica da doença do que para seu\nrastreamento, já que 99% dos indivíduos que\nnão têm a doença apresentarão resultado negativo.","C":"Seria melhor utilizar um exame mais específico, pois 1% dos indivíduos que não possuem a\ndoença apresentará resultado positivo nesse teste.","D":"É coerente que o pesquisador utilize esse exame para rastreamento, já que 99% dos indivíduos\nque têm resultado positivo para essa doença\nserão verdadeiramente doentes."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-336267","number":"336267","sourceNumber":"336267","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo verificou a associação entre diversos fatores e mortalidade por HIV. Os\ndados estão na tabela abaixo. Pode-se afirmar\nque são fatores de risco para mortalidade por HIV:","options":{"A":"Ensino fundamental incompleto, falta de tratamento ou interrupção da TARV e menos de 1 ano\nde diagnóstico.","B":"Sexo masculino, ensino fundamental incompleto, transfusão.","C":"Sexo feminino, 50 anos ou mais, ensino universitário.","D":"Idade entre 9?29 anos, uso de drogas injetáveis e interrupção de tratamento com TARV."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-336273","number":"336273","sourceNumber":"336273","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Jovem, 19 anos, foi passar as férias no Nordeste onde se esbaldou na gastronomia\nlocal e não atentou-se o suficiente para os\ncuidados de higiene dos estabelecimentos alimentícios.\nEvoluiu com quadro de dor abdominal, fezes líquidas e volumosas, náusea, vômito e febre. Tentou\nalimentar-se e hidratar-se em casa, sem sucesso e diante à fraqueza e mal-estar incessante,\nprocurou a UPA local. Sabe-se que é comum doenças infecto contagiosas do trato gastrointestinal\nevoluírem com a desidratação do paciente e que esta tem alta taxa de mortalidade. Isso pode\nindicar:","options":{"A":"Alto risco de óbito na comunidade.","B":"Existem frequentemente muitos casos novos de desidratação.","C":"Alto índice de morte entre os doentes","D":"Alta potencialidade da gravidade da desidratação."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-336275","number":"336275","sourceNumber":"336275","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo verificou a influência do peso ao nascer e o desenvolvimento de diabetes\ntipo I na infância e adolescência. Para\nisso, recrutaram 500 jovens diabéticos, onde foram\ninterrogados sobre seu peso ao nascer a partir dos dados de registro da maternidade. Foram\nconsiderados como peso normal todos aqueles que nasceram com até 3,9kg e como peso elevado\naqueles que nasceram com mais de 3,9kg. Esses 500 jovens foram pareados por sexo e idade com\noutros 500 jovens não-diabéticos, aos quais também tiveram seu peso ao nascer verificado. Os\npesquisadores concluíram que o peso ao nascer não influenciou o desenvolvimento de diabetes\ntipo I. Sobre o desenho de estudo acima, é correto afirmar que trata-se de um estudo:","options":{"A":"Transversal","B":"Coorte","C":"Ecológico","D":"Caso-controle"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-334744","number":"334744","sourceNumber":"334744","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo objetivou verificar fatores associados à piora do estilo de vida, durante a\npandemia de COVID-19, entre trabalhadores por aplicativos residentes no Brasil. Para tal, aplicou\num questionário, contendo questões sociodemográficas e sobre o estado de saúde, a pessoas\nselecionadas aleatoriamente a partir de um banco de informações sobre trabalhadores de uma\nempresa de entrega de alimentos por aplicativo que opera nacionalmente. A aplicação do\nquestionário a cada trabalhador se deu entre os meses de outubro e dezembro de 2020, por\ntelefone, sendo entrevistados 1500 pessoas. Foi realizada análise estatística descritiva, bivariada\ne\nde regressão logística. O desenho do estudo descrito acima é:","options":{"A":"Ecológico.","B":"Transversal.","C":"Caso-controle.","D":"Coorte."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-334745","number":"334745","sourceNumber":"334745","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um novo teste para identificação de infecção pelo SARS-CoV-2 foi testado em 1000\npessoas. Os resultados foram: dentre as\n200 pessoas que estavam infectadas, o novo teste foi\npositivo em 170; e dentre as 800 pessoas que não estavam infectadas, o novo teste foi negativo em\n750. A sensibilidade desse novo teste é:","options":{"A":"77%.","B":"85%.","C":"93%.","D":"96%."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-335101","number":"335101","sourceNumber":"335101","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Certo estudo visou a verificar a associação entre o tempo diário de trabalho dos\nprofissionais da área de saúde e a ocorrência\nde dor lombar crônica. Foi registrada a carga horária\ndiária de cada trabalhador e verificada a incidência de dor lombar por um período de dois anos. Em\nrelação aos métodos epidemiológicos, assinale a alternativa correta.","options":{"A":"Esse é um estudo transversal.","B":"As horas de trabalho representam o desfecho.","C":"A dor lombar é a exposição.","D":"Esse é um estudo prospectivo."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-335103","number":"335103","sourceNumber":"335103","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Analise as seguintes variáveis de um estudo epidemiológico e seus exemplos. I.\nOrdinal: grau de instrução; II. Nominal: cor da pele; III. Contínua: IMC; IV. Discreta: número de\npessoas encaminhadas para a atenção secundária. Apresentam uma correta correlação de\nvariáveis e exemplos:","options":{"A":"I e II, apenas.","B":"III e IV, apenas.","C":"I, II e III, apenas.","D":"I, II, III e IV."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-321192","number":"321192","sourceNumber":"321192","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sobre as medidas de associação em epidemiologia, assinale a alternativa CORRETA:","options":{"A":"Os estudos de casos e controles e ensaio clínico são delineados para determinar se existe\nassociação entre exposição a um fator e desenvolvimento de uma doença.","B":"Se o risco relativo for maior do que 1, o risco em pessoas expostas é menor que o risco em\npessoas não expostas, evidenciando uma\nassociação negativa, e pode ser indicativo de efeito de\nproteção.","C":"Apesar de não se calcular o risco relativo em estudos de casos e controles, sob muitas\ncondições, pode-se obter uma ótima estimativa do risco relativo usando a odds ratio.","D":"A prevalência de uma doença na população é chamada de risco absoluto. O risco absoluto pode\nindicar a magnitude do risco em um grupo de pessoas sem exposição."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-321194","number":"321194","sourceNumber":"321194","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo foi desenvolvido na cidade de Bambuí, situada no interior de Minas Gerais,\npara determinar a prevalência e os fatores\nsociodemográficos associados à depressão. Um\nquestionário foi aplicado para identificar os indivíduos com depressão em uma amostra\nrepresentativa da população da cidade com 18+ anos de idade (1.041 participantes). Os episódios\ndepressivos atuais estavam associados ao sexo, à idade e à condição atual de trabalho.\n\nSaliente-se que as determinações do episódio depressivo atual e da ocupação foram feitas\nsimultaneamente, ou seja, não foi possível\nsaber se a ausência de trabalho foi anterior ou posterior\nao surgimento do episódio depressivo. Assinale a alternativa que apresenta CORRETAMENTE o\ntipo de estudo epidemiológico descrito:","options":{"A":"Caso controle.","B":"Coorte.","C":"Ecológico.","D":"Seccional."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-321196","number":"321196","sourceNumber":"321196","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A análise descritiva de dados em bioestatística, além da construção de tabelas e\ngráficos, consistem também no cálculo de medidas\nque são úteis na produção da visão global dos\ndados. Medidas de tendência central resumem o conjunto de dados em um único número. São\nmedidas de tendência central, EXCETO:","options":{"A":"Moda.","B":"Média.","C":"Amplitude.","D":"Mediana."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-345743","number":"345743","sourceNumber":"345743","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Quando comparadas às taxas de mortalidade da infecção pelo vírus SARS-Cov2 (0,1 a\n1,0 por 100.000 indivíduos entre 12 e 29 anos), bem como o risco de hospitalização, pode-se\nafirmar que:","options":{"A":"O benefício geral da vacina supera o risco de miocardite por ela induzida.","B":"O benefício geral da vacina não supera o risco de miocardite por ela induzida.","C":"O benefício geral da vacina é inferior ao risco de miocardite por ela induzida.","D":"O benefício geral da vacina supera o risco de miocardite por ela não induzida."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-337662","number":"337662","sourceNumber":"337662","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale o estudo epidemiológico que é o MAIS indicado para identificar os fatores de\nrisco de uma doença.","options":{"A":"Estudo transversal.","B":"Série de casos.","C":"Ensaio clínico.","D":"Estudo de coorte."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-345744","number":"345744","sourceNumber":"345744","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em relação à sensibilidade do método diagnóstico de baciloscopia do escarro na\ntuberculose:","options":{"A":"Uma redução de 10-20% na sensibilidade da baciloscopia pode ser obtido após centrifugação\ne/ou sedimentação do escarro.","B":"Um aumento de 10-20% na sensibilidade da baciloscopia também pode ser obtido após\ncentrifugação e não com a sedimentação do escarro.","C":"Um aumento de 10-20% na sensibilidade da baciloscopia também pode ser obtido após\ncentrifugação e/ou sedimentação do escarro.","D":"Um aumento de 90 % na sensibilidade da baciloscopia também pode ser obtido após\ncentrifugação e/ou sedimentação do escarro."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-345745","number":"345745","sourceNumber":"345745","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os benefícios proporcionados pela vacinação (prevenir a doença provocada pelo\nSARS-Cov2, ou hospitalizações, internações em UTI e óbitos associados):","options":{"A":"Não superaram os riscos de miocardite decorrente da vacina em todas as populações para as\nquais a vacinação foi recomendada.","B":"Superaram os riscos de miocardite decorrente da vacina em todas as populações para as quais\na vacinação foi recomendada.","C":"Superaram os riscos de miocardite decorrente da vacina em todas as populações para as quais\na vacinação não foi recomendada.","D":"Superaram os riscos de miocardite não decorrente da vacina em todas as populações para as\nquais a vacinação foi recomendada."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-306704","number":"306704","sourceNumber":"306704","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Buscando estimar a quantidade de pessoas com uma determinada doença na\npopulação, a secretaria de saúde de um\nmunicípio aplicou um teste com 80% de sensibilidade e\n70% de especificidade. O teste foi aplicado em um grupo de 1.000 pessoas, obtendo-se 415\nresultados positivos. Considerando que a prevalência encontrada nesse experimento seja de fato a\nprevalência da doença no município, quantas pessoas estavam acometidas pela doença?\n(População total do município: 400.000 pessoas).","options":{"A":"100.000","B":"92.000","C":"132.000","D":"40.000"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-313304","number":"313304","sourceNumber":"313304","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sobre os Estudos Epidemiológicos é correto afirmar que:","options":{"A":"Nos estudos seccionais, a exposição e a condição de saúde do participante são determinadas\nsimultaneamente. Estudos analíticos são aqueles delineados para examinar a existência de\nassociação entre uma exposição e uma doença ou condição relacionada à saúde. Os estudos\ndescritivos têm por objetivo determinar a distribuição de doenças ou condições relacionadas à\nsaúde, segundo o tempo, o lugar e/ou as características dos indivíduos.","B":"Nos estudos descritos, a exposição e a condição de saúde do participante são determinadas\nsimultaneamente. Estudos seccionais são aqueles delineados para examinar a existência de\nassociação entre uma exposição e uma doença ou condição relacionada à saúde. Os estudos\nanalíticos têm por objetivo determinar a distribuição de doenças ou condições relacionadas à\nsaúde, segundo o tempo, o lugar e/ou as características dos indivíduos.","C":"Nos estudos seccionais, a exposição e a condição de saúde do participante são determinadas\nsimultaneamente. Estudos descritivos são aqueles delineados para examinar a existência de\nassociação entre uma exposição e uma doença ou condição relacionada à saúde. Os estudos\nanalíticos têm por objetivo determinar a distribuição de doenças ou condições relacionadas à\nsaúde, segundo o tempo, o lugar e/ou as características dos indivíduos.","D":"Nos estudos analíticos, a exposição e a condição de saúde do participante são determinadas\nsimultaneamente. Estudos seccionais são aqueles delineados para examinar a existência de\nassociação entre uma exposição e uma doença ou condição relacionada à saúde. Os estudos\ndescritivos têm por objetivo determinar a distribuição de doenças ou condições relacionadas à\nsaúde, segundo o tempo, o lugar e/ou as características dos indivíduos.","E":"Nos estudos descritivos, a exposição e a condição de saúde do participante são determinadas\nsimultaneamente. Estudos analíticos são aqueles delineados para examinar a existência de\nassociação entre uma exposição e uma doença ou condição relacionada à saúde. Os estudos\nseccionais têm por objetivo determinar a distribuição de doenças ou condições relacionadas à\nsaúde, segundo o tempo, o lugar e/ou as características dos indivíduos."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-291955","number":"291955","sourceNumber":"291955","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um exame físico foi usado para rastreamento de câncer de próstata em 2500 homens\ncom carcinoma comprovado por biópsia, e em um\ngrupo controle de 5.000 homens emparelhados\npor idade e raça. Os resultados estão demonstrados na tabela a seguir: Assinale a alternativa que\napresenta CORRETAMENTE a sensibilidade do exame físico.","options":{"A":"69%.","B":"72%.","C":"84%.","D":"85%."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-304882","number":"304882","sourceNumber":"304882","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere o estudo resumido abaixo: O objetivo deste estudo é identificar os fatores\nassociados ao diagnóstico de Linfoma não\nHodgkin de células B (LNH) ou linfoma de Hodgkin em\npacientes com artrite reumatoide (AR). Trata-se de um estudo multicêntrico realizado na França.\nForam selecionados 54 pacientes que tiveram LNH de células B ou Linfoma de Hodgkin após o\ndiagnóstico de AR. Foram incluídos também 108 pacientes com AR acompanhados por 10 anos\nnos serviços de saúde inseridos no estudo. Os dois grupos de pacientes foram pareados por idade\ne suas características foram comparadas para identificar parâmetros associados à ocorrência de\nlinfoma. Na análise univariada, os fatores associados à ocorrência de linfoma foram sexo masculino\n(OR 3,3; IC 95% 1,7 a 6,7), anticorpos anti-proteínas citrulinadas positivo (OR 5,1; IC 95% 2,0 a\n\n15,7), fator reumatoide positivo (OR 2,0, IC 95% 1,6 a 12,2), presença de erosões nas radiográfias\n(OR 3,8, IC 95% 1,7 a 8,3) e nível de\natividade da AR permanecerem significativamente associados\na um risco maior de surgimento de linfoma (adaptafo de RMD Open 2021;7:e001698). Qual é o\ndelineamento metodológico deste estudo?","options":{"A":"Ensaio clínico.","B":"Corte transversal.","C":"Caso-controle.","D":"Coorte."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-304883","number":"304883","sourceNumber":"304883","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere a seguinte afirmação: \"Mulheres com achado de disúria e polaciúria, sem\ncorrimento ou irritação vaginal, tem uma probabilidade de 90% de ter um quadro de infecção\nurinária\". Dentre as alternativas abaixo, qual conceito epidemiológico melhor se aplica à afirmação\né:","options":{"A":"Sensibilidade.","B":"Valor preditivo positivo.","C":"Especificidade.","D":"Odds Ratio."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-291959","number":"291959","sourceNumber":"291959","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O viés tem sido definido como qualquer erro sistemático no delineamento, na condução\nou análise de um estudo que resulta em uma\nestimativa equivocada do efeito de uma exposição\nsobre o risco de doença. São tipos e fontes de viés de informação, EXCETO:","options":{"A":"Viés de memória.","B":"Viés de diagnóstico.","C":"Viés na obtenção de informações de registros.","D":"Viés de seleção."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-266391","number":"266391","sourceNumber":"266391","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Médico atende paciente com resultado positivo para sangue oculto nas fezes. O\npaciente está assintomático, não tem fatores\nde risco e não tem história familiar positiva. O médico\nse pergunta sobre a probabilidade deste paciente ter neoplasia de cólon. Qual característica do\nexame é mais relevante para esclarecer essa dúvida?","options":{"A":"Valor preditivo positivo.","B":"Sensibilidade.","C":"Especificidade.","D":"Valor preditivo negativo."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-266392","number":"266392","sourceNumber":"266392","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo de coorte, analisou-se o risco de desenvolvimento da doença \"X\" a partir\nda exposição a ''Y''. Após 10 anos de\nseguimento, entre 100 pessoas expostas, 10 desenvolveram\na doença. E entre 200 não expostos, cinco desenvolveram a doença. O Risco Relativo calculado\nnesse estudo é:","options":{"A":"0.1.","B":"1.","C":"4.","D":"8."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-266393","number":"266393","sourceNumber":"266393","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma das alternativas cogitadas ao longo do enfrentamento da pandemia em 2020 para\no tratamento de pacientes graves infectados\npelo Sars-COV-2 foi o uso de plasma convalescente.\nPara que os profissionais médicos tenham maior segurança da eficácia desta terapia, são\nfundamentais estudos com qual característica metodológica?","options":{"A":"Análises estatísticas multivariadas complexas.","B":"Randomização.","C":"Validade externa.","D":"Financiamento público da pesquisa."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-287361","number":"287361","sourceNumber":"287361","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere uma população fictícia de 1.000 pessoas, das quais sabemos que 100 têm\numa determinada doença e 900 não. Um teste de rastreamento foi utilizado para identificar as 100\npessoas com a doença e os resultados foram os seguintes: das 100 pessoas com a doença, 80\nforam positivas e 20 foram negativas no teste; das 900 pessoas sem a doença, 800 foram\nnegativas e 100 foram positivas. Considerando esse cenário, qual é a sensibilidade (%) do teste?","options":{"A":"44.","B":"80.","C":"89.","D":"97."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-287362","number":"287362","sourceNumber":"287362","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um ensaio clínico randomizado duplo-cego que avalia a eficácia de uma medicação\npara Doença Pulmonar Obstrutiva Crônica,\nobservou-se que a proporção de pacientes atualmente\nfumantes não era semelhante entre os grupos, sendo maior no grupo placebo. Em qual\nprocedimento do estudo muito provavelmente houve problema?","options":{"A":"Na definição dos critérios de inclusão e exclusão.","B":"No cálculo da amostra.","C":"No cegamento dos pesquisadores.","D":"Na randomização."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-257379","number":"257379","sourceNumber":"257379","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A estatística permite tratar a variabilidade de forma adequada e quantificar a incerteza\npor meio de cálculo de probabilidades. Ao\nlançar um kit de teste diagnóstico, o fabricante realiza\nestudos para comprovação de sua aplicabilidade. O bom uso de um teste diagnóstico requer, além\nde considerações clínicas, o conhecimento de medidas que caracterizam a sua qualidade\nintrínseca. Analise a tabela a seguir: Considerando a tabela, é CORRETO afirmar que:","options":{"A":"A sensibilidade do teste pode ser estimada pela fórmula: a/(a+c).","B":"A VPP é a probabilidade de o paciente não estar doente quando o resultado do teste é positivo.","C":"A especificidade é a probabilidade de o teste ser negativo sabendo-se que o paciente\nexaminado não tem a doença.","D":"A acurácia do teste pode ser estimada pela fórmula: (a+d)/(c+b)."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-257380","number":"257380","sourceNumber":"257380","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na análise descritiva de dados, são medidas de variabilidade, EXCETO:","options":{"A":"Moda.","B":"Amplitude.","C":"Desvio padrão.","D":"Variância."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-257381","number":"257381","sourceNumber":"257381","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"As discussões sobre as vacinas para o novo coronavírus, que estão em estudo, trazem\nmuitas dúvidas à população. O processo de pesquisa e desenvolvimento de uma nova vacina é\nconstituído de diversas etapas tratando-se, portanto, de um processo demorado, de alto\ninvestimento e associado a riscos elevados. Assinale a alternativa que apresenta o estudo\nADEQUADO para esse processo.","options":{"A":"Estudo de coorte concorrente.","B":"Estudo ecológico.","C":"Estudo de intervenção.","D":"Estudo seccional."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-283936","number":"283936","sourceNumber":"283936","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sobre o valor preditivo de um teste, analise as assertivas abaixo: I. Varia com a\nprevalência (probabilidade pré-teste) da doença. II. Para um mesmo teste, quanto maior a\nprevalência maior o VPP (Valor Preditivo Positivo) e menor o VPN (Valor Preditivo Positivo). III.\nQuanto mais sensível, melhor o VPN. IV. Quanto mais específico, melhor o VPP. Quais estão\ncorretas?","options":{"A":"Apenas II.","B":"Apenas I e II.","C":"Apenas III e IV.","D":"Apenas I, III e IV.","E":"I, II, III e IV."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-232108","number":"232108","sourceNumber":"232108","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Aponte o item cujo critério de causalidade empregado para esclarecer a associação\nentre um fator de risco e a doença seja aquele\nem que, quanto mais exposição ao fator de risco,\nmaior a chance de adoecer ou maior a gravidade da doença.","options":{"A":"Sequência cronológica.","B":"Consistência.","C":"Relação dose-resposta.","D":"Analogia.","E":"Plausibilidade Biológica."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-242994","number":"242994","sourceNumber":"242994","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A medicina baseada em evidências usa informações hierarquizadas para suportar a\ntomada de decisão clínica. Sobre essa hierarquia de evidências, marque V para as afirmativas\nverdadeiras e F para as falsas: ( ) prioridade à pesquisa em seres humanos, em especial àquelas\ncom desfechos clínicos voltados para a doença do paciente. ( ) valorização do rigor metodológico e\ndo baixo número de sujeitos participantes da pesquisa. ( ) importância da capacidade de estimar o\npotencial impacto das condutas clínicas sobre o problema estudado. ( ) baixa valorização de\ninformações baseadas em experiência de especialistas. Assinale a alternativa que representa a\nsequência CORRETA:","options":{"A":"F, V, V, F","B":"V, F, F, F","C":"F, F, V, V","D":"V, V, F, V","E":"V, V, V, V"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-242995","number":"242995","sourceNumber":"242995","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sobre o valor preditivo de um teste diagnóstico, analise as afirmativas: I - o valor\npreditivo negativo é a probabilidade de não ter\na doença quando o resultado do teste é negativo\n(normal) e será maior quanto mais sensível for o teste. II - o valor preditivo positivo é a\nprobabilidade de doença em paciente com o resultado de um teste positivo (anormal) e não\ndepende da prevalência da doença, sendo essa uma de suas vantagens. III - o valor preditivo\nnegativo é a probabilidade de um teste ser negativo, dado que o indivíduo não tem a doença e\ndepende da prevalência da doença. IV- o valor preditivo positivo de um exame, quando alto,\napresenta alta especificidade para diagnosticar a doença. Está CORRETO o que se afirmar em:","options":{"A":"I e II, apenas.","B":"I,II, III apenas.","C":"II e III, apenas.","D":"I e III, apenas.","E":"I e IV, apenas."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-246734","number":"246734","sourceNumber":"246734","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo realizado para avaliar um novo método para diagnóstico de Pneumonia\nverificou que o seu valor preditivo positivo\nera mais alto do que o observado no método de\nreferência (padrão-ouro). Portanto, pelo novo método, em comparação ao método de referência, a\nprobabilidade é maior de:","options":{"A":"existir doença em um paciente com resultado positivo.","B":"não existir doença em um paciente com resultado negativo.","C":"ocorrer resultado positivo.","D":"ocorrer resultado negativo.","E":"gerar resultados acurados."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-255647","number":"255647","sourceNumber":"255647","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Lind & Singer (1986) estudaram a qualidade da tomografia computadorizada para o\ndiagnóstico de metástase de carcinoma de fígado. Um total de 150 pacientes foram submetidos a\ndois exames: a tomografia computadorizada e a laparotomia. A laparotomia é o padrão ouro\n(classifica o paciente sem erro) para este caso. A tabela a seguir resume os resultados obtidos pelo\nestudo. Os autores gostariam de saber se a sensibilidade da tomografia era alta para o diagnóstico\nde metástase de carcinoma hepático. Qual é seu valor no estudo acima? MARQUE A CORRETA.","options":{"A":"77%","B":"89%","C":"85%","D":"55%"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-227275","number":"227275","sourceNumber":"227275","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"No Reino Unido, foram levantados os dados dos últimos 30 anos de 56.205 veteranos\nde guerra, os quais foram comparados com aqueles\nde 172.741 soldados que não foram à guerra,\npareados em relação a sexo, período de nascimento, período de serviço e ano de recrutamento.\n\nHouve 267 suicídios (0,48%) entre os veteranos, em comparação a 918 (0,53%) entre os que não\nforam à guerra. A diferença não foi estatisticamente significante (hazard ratio ajustada: 0,99;\nintervalo de confiança de 95%: 0,86 a 1,13) (Occupational Medicine London 2017; 67: 350-55).\n\nAssinale a opção correta quanto ao tipo de estudo:","options":{"A":"Coorte.","B":"Caso-controle.","C":"Corte transversal.","D":"Série de casos."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-255649","number":"255649","sourceNumber":"255649","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sobre o uso de ferramentas da epidemiologia clínica para o processo diagnóstico,\nanalise as afirmativas a seguir e assinale\ncada uma com V (verdadeira) e F (falsa). MARQUE A\nCORRETA: I. A especificidade caracteriza-se pela proporção de pessoas com a doença que\napresentam o teste negativo. II. Testes específicos devem ser selecionados para confirmar o\ndiagnóstico que foi sugerido por outros dados ou exames. III. A especificidade de um exame varia\nde acordo com a prevalência da doença na população em estudo. IV. Testes muito específicos\ndevem ser considerados quando resultados falso-positivos podem prejudicar o paciente.","options":{"A":"F ? V ? F ? V","B":"V ? V ? F ? V","C":"V ? V ? V ? V","D":"F ? F ? F - F"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-227276","number":"227276","sourceNumber":"227276","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um teste diagnóstico para uma doença rara identificou corretamente 93% dos\nacometidos e apresentou corretamente\nresultado negativo em 95% dos não acometidos. Aplicado\nem uma população com prevalência da doença de 0,3 por 100.000, entre os resultados positivos no\nteste, 1,3% correspondiam a pessoas com a doença. Entre os resultados negativos, 99,9% eram de\npessoas livres da doença. Assinale a alternativa que apresenta corretamente o significado destes\npercentuais em sua ordem sequencial (93%, 95%, 1,3% e 99,9%).","options":{"A":"Valor preditivo positivo, valor preditivo negativo, especificidade e sensibilidade.","B":"Sensibilidade, especificidade, valor preditivo positivo e valor preditivo negativo.","C":"Valor preditivo negativo, valor preditivo positivo, sensibilidade e especificidade.","D":"Especificidade, sensibilidade, valor preditivo positivo e valor preditivo negativo."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-255655","number":"255655","sourceNumber":"255655","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em relação aos estudos analíticos de coorte, MARQUE A CORRETA:","options":{"A":"São estudos intervencionais.","B":"Podem ser classificados prospectivos e retrospectivos.","C":"A medida de associação utilizada nesses estudos é a razão de chances (odds ratio).","D":"São mais eficientes para o estudo de doenças raras."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-227288","number":"227288","sourceNumber":"227288","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Dentre as mais recentes alternativas de tratamento da dislipidemia encontram-se os\ninibidores da pró-proteína convertase subtilisina/kexina tipo 9 (PCSK9). Dados os altos custos da\nmedicação e a insuficiência de evidências científicas para sua incorporação na prática clínica\nregular, sua prescrição deve ser feita com parcimônia. A tabela mostra o número necessário para\ntratar (NNT) para prevenir um desfecho cardiovascular adicionando PCSK9 a pacientes com\nvariados graus de risco cardiovascular (CV) global que já usam estatina. Considerando a tabela traz\ninformações sobre 15 perfis de pacientes (coluna 1), os que mais se beneficiaram do uso de\nPCSK9 seriam os de perfil: NNT de 5 anos para prevenir 1 evento cardiovascular em indivíduos\ncom risco cardiovascular muito alto, alto e moderado com uso de PCSK9 em pacientes que já usam\nestatina em dosagem máxima.","options":{"A":"1.","B":"5.","C":"8.","D":"15."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-227119","number":"227119","sourceNumber":"227119","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um pequeno estudo piloto, 23 homens com câncer de pulmão e 23 homens sem a\ndoença foram questionados sobre tabagismo\nprévio. Cada homem com câncer foi emparelhado por\nidade, raça, peso e condição social com um homem sem a doença. Assinale a alternativa que\napresenta CORRETAMENTE o tipo de delineamento desse estudo.","options":{"A":"Estudo coorte.","B":"Estudo transversal.","C":"Estudo experimental.","D":"Estudo caso-controle."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-227290","number":"227290","sourceNumber":"227290","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Médicos, em sua prática clínica, devem preferencialmente consultar os resultados de\nqual delineamento de estudo para mudar uma conduta medicamentosa?","options":{"A":"Estudos observacionais de coorte e caso-controle.","B":"Revisões sistemáticas com meta-análise de ensaios clínicos.","C":"Estudos populacionais ecológicos e transversais.","D":"Revisões narrativas, integrativas ou de escopo de ensaios clínicos."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-246396","number":"246396","sourceNumber":"246396","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo estatístico evidenciou um p valor igual a 0,005. Em relação a esse dado\nestatístico é correto afirmar que:","options":{"A":"A chance de o evento se dever ao acaso é inferior a 1%.","B":"Não há significância estatística em relação ao p valor encontrado.","C":"Só há relevância para o estudo caso o intervalo de confiança englobe a unidade","D":"Caso fosse desenhado um estudo de coorte, o p valor apresentaria maior significância\nestatística."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-227122","number":"227122","sourceNumber":"227122","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os dados obtidos em qualquer estudo devem ser analisados e interpretados com o\nauxílio de métodos estatísticos. A primeira etapa desta tarefa é a organização e a síntese dos\ndados. São medidas de variabilidade, EXCETO:","options":{"A":"Amplitude.","B":"Mediana.","C":"Variância.","D":"Desvio-padrão."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-243046","number":"243046","sourceNumber":"243046","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O termo de consentimento livre e esclarecido (TCLE) é o documento utilizado para\nesclarecimento e anuência do paciente convidado a participar de uma pesquisa clínica. O TCLE\ndeve conter, obrigatoriamente:","options":{"A":"explicitação da garantia de indenização do paciente diante da análise social da família em casos\nde eventuais danos decorrentes da pesquisa.","B":"explicitação ao paciente participante da pesquisa clínica que o recebimento de uma via do TCLE\né facultativo.","C":"apenas uma via, rubricada em todas as suas páginas e assinadas, ao seu término, pelo paciente\nconvidado a participar da pesquisa, ou por seu representante legal, assim como pelo cirurgião\npesquisador responsável, devendo as páginas de assinaturas estar na mesma folha.","D":"prestar informações em linguagem clara e acessível, utilizando-se das estratégias mais\napropriadas à cultura, faixa etária, condição socioeconômica e autonomia dos convidados a\nparticipar da pesquisa.","E":"garantia de plena liberdade ao participante da pesquisa, de recusar-se a participar da pesquisa\nou retirar seu consentimento apenas na fase\ninicial da pesquisa."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-243047","number":"243047","sourceNumber":"243047","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Devem ser submetidos para análise de um Comitê de ética em pesquisa com seres\nhumanos:","options":{"A":"projetos que propõem análise dados disponíveis no DATASUS.","B":"projetos que propõem realizar metanálise de estudos publicados.","C":"projetos que visam revisão sistemática da literatura científica.","D":"projetos que envolvam análise de dados de pacientes de prontuário médico.","E":"projetos que propõem uma revisão integrativa."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-202728","number":"202728","sourceNumber":"202728","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considerando que a prática da medicina baseada em evidências requer a prática do\nuso consciente, explícito e judicioso das\nmelhores evidências atuais disponíveis para tomada de\ndecisões sobre o cuidado dos pacientes, é correto afirmar que sua aplicação exige um constante e\nautocritico perguntar-responder. Quando as incertezas sobre uma determinada conduta justificam a\nbusca de maiores informações, esta prática requer acesso a um sistema para obter essas\ninformações, entre elas está a investigação das evidências. Sobre a investigação das evidências é\ncorreto afirmar:","options":{"A":"A qualidade do esclarecimento da informação torna-se irrelevante e não dependerá diretamente\nda fonte de investigação quando buscado junto a\ncolegas.","B":"O uso da internet se sustenta na confirmação da evidência se considerado o tempo mínimo de 2\nanos de publicação dos artigos disponíveis\nque tratam do assunto em questão.","C":"Os guidelines traduzem as evidências e, por si, sustentam a investigação das evidências, desde\nque publicados nos últimos 2 anos.","D":"As revisões sistemáticas, com o novo modelo de revisão utilizado, dificultam a confirmação das\nevidências por buscar responder questões com aplicabilidade clínica direta.","E":"O esclarecimento da questão clínica pode ser buscado junto a colegas ou a partir de um\nlivro-texto."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-202733","number":"202733","sourceNumber":"202733","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Com relação à avaliação de testes diagnósticos assinale a alternativa correta:","options":{"A":"O valor preditivo positivo é probabilidade do paciente com teste positivo ter a doença.","B":"O valor preditivo negativo é a probabilidade de um teste dar negativo na ausência da doença","C":"A especificidade é a proporção de verdadeiros negativos entre todos os indivíduos com teste\nnegativo.","D":"A sensibilidade depende da prevalência e avalia a capacidade do teste detectar doenças quando\npresente.","E":"A especificidade determina testes com valores positivos, independente da sensibilidade do\nmesmo."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-215167","number":"215167","sourceNumber":"215167","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sobre o Estudo de Coorte, considere as afirmações abaixo. I- Trata-se de um\nexperimento realizado com o objetivo de\nverificar, entre 2 ou mais tratamentos, qual é o mais\nefetivo. II- Tem-se 2 grupos de pacientes, expostos e não expostos a certo fator de risco, e se quer\nverificar se a proporção de pacientes que desenvolvem certa doença é a mesma nos 2 grupos ou\nnão. III- Parte do efeito (doença) para a investigação da causa (exposição). Qual(is) alternativa(s)\nestá(ão) CORRETA(S)?","options":{"A":"Apenas I.","B":"Apenas I e III.","C":"Apenas II.","D":"Apenas II e III.","E":"I, II e III."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-199520","number":"199520","sourceNumber":"199520","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em 2011, um artigo de revisão sistemática, publicado na Database da Cochrane, quis\navaliar o efeito do rastreamento para câncer de mama através da mamografia sobre a mortalidade\ne morbidade de uma série de pacientes. Sete ensaios clínicos randomizados foram elegíveis e\n\n600.000 mulheres foram randomizadas para realizar ou não mamografias, ao longo de 10 anos. O\nestudo chegou à conclusão que a cada 2000 mulheres que realizassem mamografia, uma teria sua\nvida prolongada. Dentre essas 2000 mulheres, 10 mulheres saudáveis, que não teriam sido\ndiagnosticadas se não houvesse o rastreamento, seriam diagnosticadas como pacientes com\ncâncer de mama e seriam tratadas desnecessariamente. Além disso, mais de 200 mulheres\npadeceram de importante sofrimento psicológico por muitos meses por causa de resultados\n\nfalso-positivos. Sobre as revisões sistemáticas, é INCORRETO afirmar que:","options":{"A":"É um tipo de delineamento de estudo que coleta todas as evidências a partir de pesquisas\noriginais, incluídas a partir de critérios de elegibilidade e com o mínimo de viés.","B":"É um tipo de estudo secundário, que facilita a elaboração de diretrizes clínicas, sendo muito\nútil\npara tomadores de decisão na área de saúde.","C":"É possível a inclusão de meta-análises no desenvolvimento de uma revisão sistemática, no\nentanto, elas não são normalmente incluídas por serem impossíveis de serem representadas\ngraficamente.","D":"É considerada o melhor nível de evidência para tomada de decisão em saúde."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-199526","number":"199526","sourceNumber":"199526","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"José atendeu uma mulher de 25 anos e seu hemograma mostrava níveis baixos de\nhemoglobina, hemácias hipocrômicas e microcíticas. Suspeitou de anemia ferropriva. Durante o\nestudo para o caso se deparou com uma revisão sistemática que analisava a ferritina sérica como\nteste diagnóstico para anemia ferropriva. José queria saber se a especificidade da ferritina era\nalta\npara o diagnóstico de anemia ferropriva. Assinale a alternativa que apresenta CORRETAMENTE\nseu valor considerando a revisão sistemática do quadro apresentado.","options":{"A":"85%.","B":"90%.","C":"41%.","D":"61%."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-220309","number":"220309","sourceNumber":"220309","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo epidemiológico selecionou 5.436 gestantes em 8 estados brasileiros para\navaliar a relação entre tabagismo,\netilismo e uso de drogas ilícitas na gestação e o aparecimento de\nleucemias durante infância. O estudo teve duração de 10 anos. É CORRETO afirmar que se trata\nde estudo:","options":{"A":"Coorte.","B":"Caso-controle.","C":"Ensaio clínico.","D":"Ecológico."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-199530","number":"199530","sourceNumber":"199530","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"José atendeu uma mulher de 25 anos e seu hemograma mostrava níveis baixos de\nhemoglobina, hemácias hipocrômicas e microcíticas. Suspeitou de anemia ferropriva. Durante o\nestudo para o caso se deparou com uma revisão sistemática que analisava a ferritina sérica como\nteste diagnóstico para anemia ferropriva. José estava muito curioso a respeito das razões das\nprobabilidades (likelihood ratio) desse estudo em particular. Para iniciar essa avaliação,\nnecessitava\ndo valor da probabilidade pré-teste, ou seja, da prevalência da anemia ferropriva na população\nestudada na revisão sistemática. Assinale a alternativa que apresenta CORRETAMENTE esse\nvalor.","options":{"A":"32%.","B":"28%.","C":"38%.","D":"15%."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-199533","number":"199533","sourceNumber":"199533","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sobre o uso de ferramentas da epidemiologia clínica para o processo diagnóstico,\nassinale a alternativa INCORRETA :","options":{"A":"A sensibilidade caracteriza-se pela proporção de indivíduos com a doença que tem um teste\npositivo para a doença (verdadeiros positivos).","B":"Testes altamente sensíveis são utilizados em situações nas quais se quer detectar todos os\nindivíduos com uma determinada condição na população.","C":"A sensibilidade de um exame varia de acordo com a prevalência da doença na população em\nestudo.","D":"Testes muito sensíveis têm um papel importante no início do diagnóstico, quando muitas\npossibilidades estão sendo consideradas e se quer reduzi-las."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-199609","number":"199609","sourceNumber":"199609","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Precisão e acurácia são duas propriedades fundamentais das medidas em estudos\nepidemiológicos. Entre os conceitos relacionados a elas, é CORRETO afirmar que:","options":{"A":"Precisão é a capacidade de refletir a realidade da população e acurácia é a proximidade entre o\nvalor medido e o real.","B":"Precisão é uma propriedade influenciada pelo método de seleção da amostra e acurácia é\ndeterminada pelo cálculo do seu tamanho.","C":"Precisão é a propriedade de impedir a ocorrência de erros aleatórios e acurácia é a propriedade\nde impedir erros sistemáticos.","D":"Precisão pode ser estimada pela crítica aos métodos e acurácia pela observação das\nestimativas por intervalo."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-199562","number":"199562","sourceNumber":"199562","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo publicado pelo Jama Pediatrics em 2018 analisa a relação entre prescrição\nde antibióticos ou medicações capazes de\nsuprimir a produção de ácido gástrico e\ndesenvolvimento de alergia da infância. Uma amostra constituída por 792.130 crianças nascidas\nentre 1° de outubro de 2001 e 30 de setembro de 2013 foi avaliada quanto à prescrição das\nreferidas medicações e o registro posterior de fenômenos alérgicos. Foram registrados os\ndesfechos alérgicos que ocorreram até dezembro de 2014, sendo os dados analisados entre abril\nde 2015 e janeiro de 2018. As maiores razões de danos foram encontradas entre supressores da\nprodução de ácido gástrico e alergia alimentar (2,18 para bloqueadores histamínicos e 2,59 para\ninibidores da bomba de prótons), mas razões de danos entre 1 e 2 também foram evidenciadas\ncom relação a alergia a medicamentos, anafilaxia, rinite alérgica e asma. Quanto aos antibióticos,\nfoi observada razão de danos de 2,09 com relação a asma entre 1 e 2 com relação a rinite alérgica,\nanafilaxia e conjuntivite. Sobre as características de classificação e medida de efeito deste\nestudo,\né CORRETO dizer que:","options":{"A":"É retrospectivo, analítico, do tipo de caso-controle, com efeitos pequenos a moderados.","B":"É prospectivo, descritivo, do tipo série de casos, com efeitos moderados a grandes.","C":"É retrospectivo, analítico, do tipo coorte, com efeitos pequenos a moderados.","D":"É prospectivo, descritivo, do tipo ecológico, com efeitos moderados a grande."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-199576","number":"199576","sourceNumber":"199576","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"As avaliações de testes diagnósticos se baseiam em medidas de probabilidade\ncondicional que podem ter como elemento\ncondicionante o desfecho ou o teste . A especifidade e o\nvalor preditivo positivo são medidas que variam paralelamente, no sentido de confirmar a presença\nde um desfecho. Assim, pode-se afirmar que:","options":{"A":"A especificidade tem como elemento condicionante o teste e o valor preditivo positivo o\ndesfecho.","B":"A especificidade é medida entre aqueles que têm o desfecho e o valor preditivo positivo entre\naqueles que o têm ou não.","C":"A especificidade é aumentada por um teste em paralelo e o valor preditivo positivo por um teste\nem série.","D":"A especifidade indica o desfecho ausente e o valor preditivo positivo indica se o resultado\npositivo corresponde à presença do desfecho."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-199585","number":"199585","sourceNumber":"199585","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sobre os modelos de estudos epidemiológicos, é CORRETO afirmar que:","options":{"A":"O corte transversal é um modelo que parte dos desfechos em busca de frequência de\nexposições.","B":"O estudo caso-controle tem realização demorada e custo alto quando comparado a outros\nmodelos.","C":"O coorte é um modelo que, por sua característica prospectiva, facilita a avaliação de desfechos\nraros.","D":"O ensaio clínico é um modelo em que se sacrifica a capacidade de generalização em troca de\numa maior validade interna."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-199592","number":"199592","sourceNumber":"199592","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A figura mostra a evolução de dois pacientes com neoplasia, sendo um diagnosticado\nno período sintomático (A) e um a partir de\nrastreamento da doença (B). O viés de rastreamento\nilustrado na figura é o:","options":{"A":"Viés de seleção.","B":"Viés de sobrediagnóstico (overdiagnosis).","C":"Viés de tempo de antecipação (lead time bias).","D":"Viés de tempo de duração (lenght time bias)."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-174384","number":"174384","sourceNumber":"174384","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Qual critério estabelecido pelo postulado de Bradford-Hill (1965) é utilizado para\nidentificar evidências para uma associação de causa e efeito, quando algo é observado\nrepetidamente por diferentes pessoas em locais, circunstâncias e tempos diferentes?","options":{"A":"Temporalidade.","B":"Consistência.","C":"Reversibilidade.","D":"Analogia.","E":"Eloquência."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-172524","number":"172524","sourceNumber":"172524","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo clínico prospectivo, randomizado e multicêntrico:","options":{"A":"É suficiente para definir uma questão clínica e deve ser imediatamente incorporado nos\nguidelines específicos e servir para pronta mudança universal de condutas.","B":"É a melhor ferramenta para estudos das doenças raras, para evitar que essas sejam tratadas\napenas com base em relatos de casos ou\nopinião de especialistas.","C":"É menos difundido em cirurgia, por ser mais laborioso e custoso do que situações clínicas, além\nde diversos desafios práticos e metodológicos para sua realização no âmbito da cirurgia.","D":"Tem valor quase nulo com menos de 1000 pacientes arrolados.","E":"É limitado por não conseguir estimar o risco relativo e não ter capacidade de responder questões\nespecíficas."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-172533","number":"172533","sourceNumber":"172533","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Odds ratio:","options":{"A":"É uma outra forma de cálculo direto e preciso do risco relativo.","B":"Deve ser usado em estudo de coorte para cálculo de incidência e de risco relativo.","C":"Calcula indiretamente uma estimativa do risco relativo.","D":"Em doenças raras erra grosseiramente a estimativa do risco relativo, por isso não deve ser\naplicado.","E":"Não deve ser usado em estudos tipo caso-controle."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-187427","number":"187427","sourceNumber":"187427","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"? A Justiça é extremamente técnica e bem clara ao julgar erro médico. Exige três\npré-requisitos, a saber: dano ao paciente, procedimento médico e nexo causal. Comprovada a\n\nexistência de pré-requisitos, a Justiça então avalia o comportamento do médico. Abaixo, marque a\nalternativa que você considera a mais CORRETA.","options":{"A":"Negligência: o médico não fez o que deveria ter feito.","B":"Imprudência: o médico fez o que não deveria ter feito.","C":"Imperícia: o médico fez errado.","D":"As alternativas A, B e C estão corretas.","E":"Nenhuma das alternativas acima está correta."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-187433","number":"187433","sourceNumber":"187433","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Para avaliarmos a magnitude do efeito de uma intervenção médica, podemos lançar\nmão, dentre outras ferramentas, do NNT (Número Necessário para Tratar). Leia as alternativas\nabaixo e marque a resposta CORRETA:","options":{"A":"Um NNT de 45 significa que se tratarmos 100 pacientes, 45 serão beneficiados.","B":"O cálculo do NNT é feito multiplicando 0,75 por 100.","C":"Quanto mais elevado o valor numérico do NNT obtido, maior a magnitude de efeito da\nintervenção médica estudada.","D":"O valor do NNT é obtido dividindo-se 1 pela RRA (Redução do Risco Absoluto).","E":"Nenhuma das alternativas acima está correta."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-172788","number":"172788","sourceNumber":"172788","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sensibilidade e especificidade são propriedades dos testes diagnósticos que têm\ndiferentes aplicações. A este respeito, assinale a alternativa correta:","options":{"A":"Uma sensibilidade baixa permite confirmar a presença da doença.","B":"Uma sensibilidade alta permite excluir a presença da doença.","C":"Uma especificidade baixa permite confirmar a presença da doença.","D":"Uma especificidade alta permite excluir a presença da doença."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-172822","number":"172822","sourceNumber":"172822","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere o resumo de artigo apresentado abaixo: Aproximadamente 72% dos casos\nde tuberculose (TB) na Inglaterra ocorrem entre\nos indivíduos que não são nascidos no Reino\nUnido, principalmente como resultado de reativação de TB infecção latente (LTBI). O rastreamento\nprogramático de LTBI é uma intervenção chave da estratégia contra TB da Inglaterra. Este artigo\nanalisa os resultados de um rastreamento de longa duração da LTBI na Inglaterra. Uma abordagem\nfoi criada por meio da ligação probabilística entre os dados de rastreamento da LTBI e as\nnotificações nacionais de casos de TB. As pessoas selecionadas foram seguidas até morrerem,\ntornaram-se casos, emigrarem ou até o fim do acompanhamento. As taxas de incidência de TB e\nrazões de taxas (IRR) foram calculadas. Noventa e sete de 1820 rastreados para LTBI foram\nnotificados como portadores de TB ativa. As taxas de incidência bruta entre os indivíduos positivos\npara LTBI virgens de tratamento foram de 4,1 e 2,3 por cada 100 pessoas-ano nos grupos de\nQuantiFERON e teste cutâneo à tuberculina, respectivamente. No grupo do QuantiFERON, a\nregressão de Poisson mostrou que a positividade de LTBI (IRR 22.6, IC 95% 6-8-74.6)e a ausência\nde quimioprofilaxia aumentaram a probabilidade de se tornar um caso de TB (IRR 0,17, IC 95%\n0,05-0,6). Os autores encontraram altas taxas de tuberculose em indivíduos LTBI positivos não\ntratados e uma forte associação entre nenhum tratamento e se tornar um caso de tuberculose,\ndemonstrando viabilidade e efetividade do rastreamento de LTBI e fornecendo lições políticas\nimportantes para a triagem de LTBI na Inglaterra e além [Eur Respir J, 2017;50(1), pii: 1602505].\n\nSobre o delineamento deste estudo, é correto dizer que é um estudo observacional:","options":{"A":"descritivo de caráter transversal.","B":"analítico de caráter longitudinal.","C":"descritivo de base agregada.","D":"analítico de caráter transversal."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-155446","number":"155446","sourceNumber":"155446","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em uma pesquisa foram selecionadas 60 mil indivíduos, na faixa etária de 12 a 16\nanos, com a finalidade de, ao longo de 5\nanos, se observar os fatores de risco para bulimia. Ao final\nidentificou-se quantos desenvolveram a doença. Qual o tipo de estudo realizado?","options":{"A":"Estudo de coorte.","B":"Estudo de caso-controle.","C":"Ensaio clínico.","D":"Estudo de caso.","E":"Metanálise."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-155451","number":"155451","sourceNumber":"155451","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O resultado obtido quando calculamos a diferença entre o risco absoluto de\ndeterminada doença em pessoas expostas, menos o\nrisco absoluto em pessoas não expostas,\ncorresponde ao cálculo de:","options":{"A":"Odds ratio.","B":"Risco atribuível.","C":"Risco relativo.","D":"Razão de risco.","E":"Risco populacional."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-155457","number":"155457","sourceNumber":"155457","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Observando abaixo a distribuição em ordem crescente das idades em um grupo de 12\nalunos de uma turma, qual a moda e a mediana desses 12 valores, respectivamente? 8; 8; 10; 10;\n10; 11; 11; 12; 13; 13; 13; 13","options":{"A":"12,66.","B":"13,66.","C":"8,13.","D":"13,11.","E":"8,11."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-155482","number":"155482","sourceNumber":"155482","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale o item em que todos são critérios de causalidade empregados para esclarecer\na associação entre um fator de risco e uma doença.","options":{"A":"Força de associação, Coerência e Evidência experimental.","B":"Plausibilidade, Efetividade e Relação dose-resposta.","C":"Sequência cronológica, Analogia e Especificidade.","D":"Especificidade, Coerência e Consistência.","E":"Eficácia, Eficiência e Efetividade."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-155450","number":"155450","sourceNumber":"155450","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em diagnóstico, uma forma de expressar a relação entre a sensibilidade e a\nespecificidade de um determinado Teste é...","options":{"A":"Verificar a exposição frequente a fatores de risco.","B":"Realizar ensaios randomizados grandes e simples.","C":"Interpretar as estimativas de risco individual.","D":"Construir uma curva ROC (receiver operator characteristic).","E":"Verificar resposta através da incidência cumulativa."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-155366","number":"155366","sourceNumber":"155366","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"?A palavra bioética designa um conjunto de pesquisas, de discursos e práticas, via de\nregra pluridisciplinares, que têm por objeto\nesclarecer e resolver questões éticas suscitadas pelos\navanços e a aplicação das tecnociências biomédicas. A rigor, a bioética não é nem uma disciplina,\nnem uma ciência, nem uma nova ética, pois sua prática e seu discurso se situam na interseção\nentre várias tecnociências (em particular, a medicina e a biologia, com suas múltiplas\nespecializações); ciências humanas (sociologia, psicologia, politologia, psicanálise e disciplinas\nque\nnão são propriamente ciências: a ética, para começar; o direito e, de maneira geral, a filosofia e a\nteologia. A complexidade da bioética é, de fato, tríplice. Em primeiro lugar, está na encruzilhada\nentre um grande número de disciplinas. Em segundo lugar, o espaço de encontro, mais ou menos\nconflitivo, de ideologias, morais, religiões, filosofias. Por fim, ela é um lugar de importantes\nembates\npara uma multidão de grupos de interesses e de poderes constitutivos da sociedade civil:\nassociação de pacientes; corpo médico; defensores dos animais; associações paramédicas; grupos\necologistas; agrobusiness; indústrias farmacêuticas e de tecnologias médicas; bioindústria em\ngeral. ? Fonte: HOTTOIS, G. Nouvelle encyclopédie de bioéthique. Bruxelles: De Boeck, 2001, pp.\n124-126. Desse modo, entende-se que:","options":{"A":"A bioética restringe-se às pesquisas científicas em humanos e animais de laboratório.","B":"A bioética é de atenção exclusiva de outros profissionais da saúde, com exceção do médico.","C":"A bioética é uma linha de pensamento que surge para justificar os deslizes éticos do profissional\nmédico.","D":"A bioética é parte obrigatória do pensamento reflexivo do profissional médico em suas atividades\ndiárias.","E":"A bioética nada tem a ver com o exercício da profissão do médico no seu dia a dia."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-148623","number":"148623","sourceNumber":"148623","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A osteonecrose não traumática induzida por tratamento tem sido relatada cada vez\nmais em crianças tratadas para leucemia\nlinfoblástica aguda. Vários fatores de risco para\nosteonecrose foram identificados em pacientes com câncer da infância. No entanto, o poder\ndiagnóstico e prognóstico dos estudos foi limitado e a etiologia da doença permanece incerta.\nAssim, um esforço contínuo tem sido direcionado para a identificação adicional de fatores de risco.\nFoi realizado um estudo retrospectivo de 313 crianças com diagnóstico de leucemia linfoblástica\naguda para verificar a associação entre a ocorrência de osteonecrose naquelas tratadas com\nterapias para leucemia linfoblástica aguda e polimorfismos em genes-alvo potenciais: tiopurina\n\nS-metiltransferase(TPMT; 460G> A, 719A> G), 5,10 redutase-metilenotetrahidrofolato(MTHFR;\n677C> T, 1298A> C), estrogênio receptor alfa\n1 (ESR1; Xbal) e colágeno tipo I, a1 (COL1A1; SP1).\nNo grupo em questão, maior idade e protocolos de tratamento mais recentemente desenvolvidos\nforam fatores de risco independentes para osteonecrose. Em crianças com mais de 14,5 anos de\nidade, o genótipo TPMT modulou o risco de osteonecrose. Além disso, em crianças com menos de\n12,9 anos, genótipos ESR1 também foram implicados na patogênese da osteonecrose. Além de\nmaior idade e protocolos de tratamento mais recentes, fatores genéticos (polimorfismos em genes\nESR1 e TPMT) foram implicados na patogênese da osteonecrose e poderiam ser potencialmente\nutilizados como marcadores prognósticos genéticos para osteonecrose [ Experimental and\ntherapeutic medicine 2016; 12(2): 840-846]. Assinale a alternativa que apresenta a classificação\ncorreta do estudo:","options":{"A":"Caso-controle.","B":"Coorte.","C":"Corte transversal.","D":"Série de casos.","E":"Ecológico."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-148621","number":"148621","sourceNumber":"148621","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma doença X acomete dez indivíduos em cada 100 em uma determinada população.\nUm teste diagnóstico aplicado a 50 indivíduos\ndoentes detectou corretamente a doença em 45.\n\nAplicado a 50 indivíduos saudáveis, acertou na determinação da ausência de doença em 43. Sobre\nas propriedades do teste, assinale a alternativa\ncorreta:","options":{"A":"Sensibilidade: 94%; Especificidade: 85%; Valor Preditivo Positivo: 42,2%; Valor Preditivo\nNegativo: 96,8%.","B":"Sensibilidade: 91%; Especificidade: 82%; Valor Preditivo Positivo: 43,4%; Valor Preditivo\nNegativo: 95,6%.","C":"Sensibilidade: 93%; Especificidade: 84%; Valor Preditivo Positivo: 47,6%; Valor Preditivo\nNegativo: 99,4%.","D":"Sensibilidade: 92%; Especificidade: 87%; Valor Preditivo Positivo: 40,8%; Valor Preditivo\nNegativo: 97,2%.","E":"Sensibilidade: 90%; Especificidade: 86%; Valor Preditivo Positivo: 41,7%; Valor Preditivo\nNegativo: 98,7%."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-148622","number":"148622","sourceNumber":"148622","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere o estudo a seguir: Introdução: Os fatores dietéticos podem afetar a doença\ncardíaca coronária (CHD). Os resultados de\nestudos anteriores sobre a associação entre a dieta e a\ndoença cardíaca coronária não são consistentes em diferentes países. Não houve dados sobre\nesta associação na Armênia. Objetivo: Objetivos deste estudo foram avaliar a associação entre\nfatores nutricionais e doença cardíaca coronária entre armênios em Yerevan. Metódos: Durante\n2010 e 2011, foram selecionados aleatoriamente 320 pacientes coronarianos, com doença\ncoronária há menos de 6 meses, e 320 indivíduos sem doença cardíaca coronária (com idade maior\nou igual a 30 anos) dos hospitais e policlínicas em Yerevan. A ingestão dietética relacionada a 135\nitens alimentares ao longo dos últimos 12 meses foi avaliada por meio de um questionário de\nfrequência alimentar semi-quantitativo. Resultados: Após ajuste para alguns fatores de risco para\ndoença coronariana, ingestão elevada de ácidos graxos poliinsaturados (AGPI) e ácidos graxos\nmonoinsaturados (AGM) foi associada com um risco reduzido de doença cardíaca coronária,\nenquanto esta associação não foi observada para ácidos graxos saturados (SFA). Além disso, os\nresultados indicaram uma relação inversa entre vitaminas (E, B6 e B12, ácido fólico) e fibras com\ndoença cardíaca coronária. Nesta população, tabagismo, hipertensão e síndrome metabólica (SM)\nforam significativamente mais comuns entre os pacientes com doença cardíaca coronária.\n\nConclusão: A ingestão de vitaminas E, B6 e B12, ácido fólico, ácidos graxos poliinsaturados, ácidos\ngraxos monoinsaturados e fibras parece ser preditora de doença coronária, independentemente de\noutros fatores de risco (Diabetes & Metabolic Syndrome. 2016. Epub ahead of print). Em relação à\nassociação entre fatores nutricionais e doença cardíaca coronariana, hipertensão e tabagismo\npodem atuar como (assinale a alternativa correta):","options":{"A":"Erros aleatórios.","B":"Fatores de confusão.","C":"Desfechos.","D":"Vieses de seleção.","E":"Vieses de informação."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-148613","number":"148613","sourceNumber":"148613","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo caso-controle, foi avaliada a associação entre a presença de fumantes\nem casa e doenças respiratórias em crianças.\nEntre 120 casos, 90 tinham pelo menos uma pessoa\nfumante em casa, ao passo que, entre 360 controles, tal presença foi evidenciada para 120. A\nmedida de efeito, nesta situação, é (assinale a alternativa correta):","options":{"A":"Risco 60% maior nos expostos.","B":"Risco 38,6% maior nos expostos.","C":"Risco seis vezes maior nos expostos.","D":"Risco 3,86 vezes maior nos expostos.","E":"Risco 40% a quatro vezes maior de acordo com a força da exposição."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-148585","number":"148585","sourceNumber":"148585","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Para avaliar a saúde, a epidemiologia lida com certos atributos que foram conceituados\nvisando à sua ultilização no processo. Em\nrelação a tais conceitos, assinale a alternativa correta:","options":{"A":"Cobertura é a extensão na qual a organização e a estrutura de um programa facilitam a\nparticipação dos usuários.","B":"Acessibilidade é a extensão na qual um programa alcança a sua população alvo.","C":"Eficácia é a capacidade de produzir o efeito desejado quando o serviço e colocado em\ncondições ideais de uso.","D":"Efetividade é a medida de relação entre o impacto do programa e o custo das ações.","E":"Eficiência é a capacidade do programa produzir o efeito desejado quando o serviço opera em\nuso rotineiro."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-149146","number":"149146","sourceNumber":"149146","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere que um novo teste está sendo usado para identificar pacientes com\npolineuropatia e esse teste foi usado em 400\npessoas, sendo que, 200 tinham a doença e 200 não\ntinham a doença. O teste foi positivo em 120 pacientes que tinham a doença e foi negativo em 170\npacientes que não tinham a doença. Qual é a probabilidade de um teste positivo indicar um\npaciente com polineuropatia?","options":{"A":"85%.","B":"80%.","C":"88%.","D":"90%.","E":"100%."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-162574","number":"162574","sourceNumber":"162574","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em 1 de janeiro de 1993, teve início um estudo de todas as crianças nascidas naquele\nano em uma cidade de porte pequeno. Esse\nestudo teve a duração de 4 anos e foram estudadas\ncerca de 600 variáveis. A primeira fase foi realizada nos hospitais por ocasião do nascimento, e as\nfases subsequentes incluíram visitas domiciliares às crianças quando estavam, em média, com\ndoze, vinte e 43 meses de idade. Esse tipo de estudo, chama-se:","options":{"A":"Transversal.","B":"Coorte.","C":"Longitudinal retrospectivo.","D":"Ecológico.","E":"Caso-controle."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-149149","number":"149149","sourceNumber":"149149","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A evidência de que um tratamento realmente funciona em pacientes com uma\ndeterminada doença, em condições experimentais\nrigorosas e ensaios clínicos randomizados, é\nconhecida como?:","options":{"A":"Efetividade.","B":"Eficácia.","C":"Análise de eficiência.","D":"Magnidade absoluta","E":"Custo-efetividade."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-162584","number":"162584","sourceNumber":"162584","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em 1 de janeiro de 1993, teve início um estudo de todas as crianças nascidas naquele\nano em uma cidade de porte pequeno. Esse\nestudo teve a duração de 4 anos e foram estudadas\ncerca de 600 variáveis. A primeira fase foi realizada nos hospitais por ocasião do nascimento, e as\nfases subsequentes incluíram visitas domiciliares às crianças quando estavam, em média, com\ndoze, vinte e 43 meses de idade. Esse tipo de estudo","options":{"A":"é de difícil análise.","B":"é de fácil execução.","C":"é adequado para estudo de doenças raras.","D":"tem baixo custo.","E":"possui um alto poder analítico."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-162589","number":"162589","sourceNumber":"162589","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em 1 de janeiro de 1993, teve início um estudo de todas as crianças nascidas naquele\nano em uma cidade de porte pequeno. Esse\nestudo teve a duração de 4 anos e foram estudadas\ncerca de 600 variáveis. A primeira fase foi realizada nos hospitais por ocasião do nascimento, e as\nfases subsequentes incluíram visitas domiciliares às crianças quando estavam, em média, com\ndoze, vinte e 43 meses de idade. Esse tipo de estudo:","options":{"A":"Permite estabelecer associação de causalidade.","B":"Só pode ser desenvolvido com populações com menos de 1000 pessoas.","C":"Não tem perdas de participantes.","D":"É muito comum no Brasil.","E":"Dá resultados em curto espaço de tempo."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-162595","number":"162595","sourceNumber":"162595","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O risco relativo representa:","options":{"A":"Uma comparação matemática entre o risco de adoecer em um grupo exposto a um fator\nqualquer e o risco correspondente em um grupo não exposto ao mesmo fator.","B":"Uma razão entre os produtos cruzados da distribuição das células de tabelas de contingência,\nque tem a propriedade matematicamente\ndemonstrável de aproximar-se do valor do risco relativo\nquanto mais rara for uma doença.","C":"A possibilidade de um indivíduo adquirir uma determinada doença quando exposto a\ndeterminados fatores ou condições.","D":"A possibilidade de indivíduos morrerem ao completar 65 anos de idade quando expostos a\ndeterminados fatores ou condições.","E":"A possibilidade de uma criança morrer antes de completar 12 meses de idade ao nascer com\nmenos de 2 quilos."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-162598","number":"162598","sourceNumber":"162598","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo de coorte sobre diabetes como fator de risco para doença renal crônica, o\nrisco relativo foi de 3,0; e o resultado foi estatisticamente significativo ao nível de p = 0,04. Em\nrelação às informações apresentadas é correto afirmar que:","options":{"A":"4% dos pacientes com doença renal crônica tinham diabetes.","B":"de todos os pacientes diabéticos, apenas 4% desenvolveram doença renal crônica.","C":"o histórico de diabetes era 4% mais frequente entre os pacientes com doença renal crônica do\nque entre os que não desenvolveram a doença.","D":"existe a possibilidade de 4% de que a associação observada entre a diabetes e a doença renal\ncrônica seja devida ao acaso.","E":"o desenvolvimento de doença renal crônica foi 4% maior entre os pacientes com diabetes do\nque entre os não diabéticos."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-137827","number":"137827","sourceNumber":"137827","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um dos objetivos da epidemiologia é realizar diagnósticos levando em consideração a\ntríade epidemiológica, com isso, utiliza-se frequentemente das medidas de frequência para\nrealiza-las, e entre elas, a Prevalência que expressa a:","options":{"A":"Variabilidade de ocorrência de casos novos de doenças.","B":"Vulnerabilidade dos suscetíveis frente às doenças.","C":"Probabilidade de doenças antes de o teste ser realizado.","D":"Magnitude das doenças em relação à população alvo.","E":"Transcendência das doenças sobre populações."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-137833","number":"137833","sourceNumber":"137833","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em uma pesquisa para tentar corrigir, minimizar ou evitar o Viés de Seleção, um dos\nmétodos utilizados é o Ajuste Multivariável que buscar ajustar:","options":{"A":"As diferenças em um grande número de fatores relacionados ao desfecho, utilizando técnicas de\nmodelamento matemático.","B":"Matematicamente as taxas brutas de uma ou de algumas características, de forma que um peso\nidêntico seja atribuído para estratos de risco semelhante.","C":"Resultados que poderiam diferir nas condições mais extremas, ou simplesmente pouco\nprováveis, considerando os atributos de cada variável estudada.","D":"O total de pacientes em um grupo selecionando um ou mais pacientes com a mesma\ncaracterística, exceto a que está sob estudo, para um grupo comparação.","E":"O número de pacientes em estudo para os grupos de uma forma que possibilite a cada paciente\numa probabilidade igual de ficar em um ou outro\ngrupo."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-137837","number":"137837","sourceNumber":"137837","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A Reversibilidade é um critério que busca mostrar evidências de que uma associação\nseja de causa e efeito, isso significa dizer\nque:","options":{"A":"Existe sentido, de acordo com o conhecimento biológico da época.","B":"A redução na exposição é seguida por taxas mais baixas da doença.","C":"Ocorre uma relação de causa e efeito já estabelecida para uma exposição.","D":"Exposições maiores à causa associam-se com taxas mais elevadas da doença.","E":"Repetidamente observam-se pessoas diferentes, em diferentes lugares e circunstâncias."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-137835","number":"137835","sourceNumber":"137835","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Dividindo-se o número de mortes por dengue hemorrágica pelo número de casos\nexistentes em um mesmo período, encontramos a taxa determinada de:","options":{"A":"Coeficiente de letalidade.","B":"Mortalidade específica.","C":"Coeficiente de morbidade.","D":"Mortalidade proporcional.","E":"Coeficiente de prevalência."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-126916","number":"126916","sourceNumber":"126916","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O erro aleatório ocorre quando o valor medido na amostra do estudo diverge, devido ao\nacaso, do verdadeiro valor da população. O erro aleatório decorre de medida imprecisa da\nassociação. As principais causas de erro aleatório são, EXCETO:","options":{"A":"Variação biológica individual.","B":"Erro de amostragem.","C":"Viés de mensuração.","D":"Erros de medida."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-126919","number":"126919","sourceNumber":"126919","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"São estudos do tipo coorte mais adequados para todos os tipos de pesquisa abaixo,\nEXCETO:","options":{"A":"Pesquisa de causa rara.","B":"Pesquisa de períodos prolongados de latência.","C":"Teste de múltiplos efeitos de causa.","D":"Mensuração direta da incidência."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-126921","number":"126921","sourceNumber":"126921","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A realização de uma metanálise inclui os seguintes passos, EXCETO:","options":{"A":"Formulação do problema e delineamento do estudo.","B":"Identificação dos estudos relevantes e exclusão dos estudos pobremente conduzidos ou\ndaqueles com maiores problemas metodológicos.","C":"Medição, combinação e interpretação dos resultados.","D":"Aplicação do resultado em uma amostra para validação da pesquisa."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-127194","number":"127194","sourceNumber":"127194","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A cirurgia bariátrica é atualmente a terapia mais eficaz para induzir a perda de peso em\npacientes obesos mórbidos. Um estudo com uma intervenção de dois anos teve como objetivo\ncomparar a eficácia de duas abordagens não cirúrgicas com a cirurgia bariátrica em termos de\nmudança de peso corporal e parâmetros metabólicos em pacientes obesos mórbidos. Os pacientes\nforam aleatorizados para uma intervenção intensiva relacionada a estilo de vida (ILI) (n = 60) ou\nterapia convencional contra a obesidade (COT) (n = 46). O grupo ILI recebeu terapia\ncomportamental e aconselhamento nutricional. O grupo COT recebeu tratamento médico padrão.\n\nEles foram comparados com um terceiro grupo: grupo obesidade cirúrgico (SOG) (n = 37). Os\npacientes que receberam ILI tiveram maior\nporcentagem de perda de peso do que os pacientes que\nreceberam COT (-1.3% versus - 1.6%; p < 0.0044). Curiosamente, 31,4% dos pacientes incluídos\nno grupo de ILI não eram mais obesos mórbidos após apenas seis meses de intervenção,\naumentando para 44.4% após 24 meses de intervenção. A perda de peso do grupo SOS foi -29,6%\napós o mesmo período de tempo. Conclusões: ILI foi associada com perda de peso significativa em\nrelação a COT nesta comparação de intervenções contra a obesidade. Uma abordagem ILI poderia\nser uma alternativa terapêutica para pacientes com obesidade que não são candidatos a se\nsubmeterem à cirurgia bariátrica (Int. J. Endocrinol. Jul 2015). O estudo em questão é:","options":{"A":"Corte transversal.","B":"Ecológico.","C":"Caso-controle.","D":"Coorte.","E":"Ensaio clínico."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-127235","number":"127235","sourceNumber":"127235","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Evidências crescentes sugerem que o tabagismo ativo é um fator de risco para\nhipertensão, mas pouco se sabe sobre os\nefeitos do tabagismo passivo sobre esta condição. Na\nChina, o tabagismo passivo entre as mulheres é generalizado e grave, devido à alta proporção de\nhomens que fumam, particularmente nas áreas rurais. Este estudo avaliou se o tabagismo passivo\nestá associado com aumento do risco de hipertensão arterial em mulheres não fumantes na China\nrural. Um total de 392 mulheres não fumantes de uma área rural da província de Shanxi (norte da\nChina) participaram deste estudo transversal. Os dados sobre o tabagismo passivo feminino e\noutros fatores conhecidos por influenciar a hipertensão foram coletados durante as entrevistas\nface-a-face. A regressão logística foi usada para avaliar a associação após o ajuste para possíveis\nfatores concorrentes. No total, 162 das 392 participantes eram hipertensas (41,3%); 118\nparticipantes (30,1%) relataram exposição ao fumo passivo, das quais 88,4% foram expostas à\nfumaça em casa. Após o ajuste para idade, IMC, escolaridade, ocupação, hábito de beber,\natividade física e situação em relação à menopausa, o fumo passivo conferiu uma razão de\nchances ajustada de 1,99 (intervalo de confiança de 95%: 1,16 a 3,39). As razões de chances\najustadas para níveis de exposição ao tabagismo passivo de uma a três, quatro a seis, e mais de\nseis vezes por semana foram 1,01 (0,39-2,62), 2,57 (1,05-6,30) e 2,59 (1,18-5,69),\nrespectivamente. CONCLUSÃO: Em áreas rurais do norte da China, o tabagismo passivo feminino\nno lar é prevalente. A exposição frequente ao fumo passivo é um fator de risco para hipertensão\narterial em mulheres não fumantes, o que sugere que devem ser tomadas medidas para evitar o\nfumo passivo nesta população (J.Hypert., 2015. Ago, 7). Assinale a alternativa CORRETA no que\ndiz respeito à analise dos dados:","options":{"A":"A razão das chances revela um risco quase duas vezes maior de hipertensão arterial entre os\nexpostos e a regressão logística controla os vieses de confusão.","B":"A razão das chances revela um risco quase dois por cento maior de hipertensão arterial entre os\nexpostos e a regressão logística controla os vieses de seleção.","C":"A razão das chances revela a frequência de exposição quase no percentil dois da população e a\n\nregressão logística controla o erro aleatório incidente na amostra.","D":"A razão das chances revela uma proteção quase duas vezes maior contra a hipertensão entre\nos não expostos e a regressão logística\ncontrola os vieses de informação.","E":"A razão das chances revela uma proteção de quase dois por cento contra a hipertensão arterial\nentre os não expostos e a regressão\nlogística controla os vieses de procedência."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-127247","number":"127247","sourceNumber":"127247","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um trabalho realizado em 2014 no Espírito Santo que avaliou todos os pacientes\nportadores de Doença Inflamatória\nIntestinal (DII) que receberam medicação pela Farmácia Cidadã\nEstadual, observou que 1484 pacientes estavam recebendo a medicação. A média de idade dos\npacientes com Doença de Crohn (DC) foi de 38,01 anos (± 15,9 anos) e na Retocolite Ulcerativa\n(RCU) a média de idade foi de 44,18 anos (± 15,9 anos), com p= 0,025. Quando avaliado o uso de\nMesalazina na terapêutica da DII observou-se que esta medicação foi usada por 65% dos\npacientes com RCU e 58% daqueles com DC, com a Razão de Chance (Oldd Ratio -OD) de 1,18,\ncom Intervalo de Confiança (IC) de 0,89 - 1,32. Considerando que no censo populacional do ano de\n2014, a população do Espírito Santo foi de 3.885.049 pessoas e que todos os pacientes com DII\nestão representados nesta amostra, observe as afirmativas abaixo e depois responda. I- A\nincidência de DII no Espírito Santo foi de 38,2/100.000 habitantes; II- A diferença de média de\nidade\nentre DC e RCU apresentou significância estatística; III- A Razão de Chance do uso de Mesalazina\nna RCU não apresentou significância estatística.","options":{"A":"Todas as afirmativas estão corretas.","B":"As afirmativas I e II estão corretas.","C":"As afirmativas II e III estão corretas.","D":"As afirmativas I e III estão corretas.","E":"Todas as afirmativas estão erradas."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-102771","number":"102771","sourceNumber":"102771","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os estudos tipo coorte são os mais adequados para os tipos de pesquisas abaixo,\nEXCETO:","options":{"A":"Mensuração da relação temporal.","B":"Pesquisa de períodos prolongados de latência.","C":"Teste de múltiplos efeitos de causa.","D":"Mensuração direta da incidência."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-102745","number":"102745","sourceNumber":"102745","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Dentre as desvantagens dos diversos tipos de pesquisa, a que possui maior\npossibilidade de viés de seleção é/são:","options":{"A":"Os casos e controles.","B":"O coorte.","C":"O ecológico.","D":"O transversal."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-102750","number":"102750","sourceNumber":"102750","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O tipo de amostragem, que possui alta capacidade de generalização e se caracteriza\npor listar todos os indivíduos elegíveis para o\nestudo, e, por meio de sorteio, se seleciona um\nsubconjunto que formará a amostra do estudo, é chamado de:","options":{"A":"Amostragem aleatória simples.","B":"Amostragem sistemática.","C":"Amostragem por conglomerados.","D":"Amostragem aleatória estratificada."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-111579","number":"111579","sourceNumber":"111579","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Num estudo epidemiológico com o objetivo de testar hipótese etiológica entre um\ndeterminado fator de risco e\n\numa doença específica, verificou-se a incidência do agravo, durante um período de tempo, em um\ngrupo de estudo constituído por 300 pessoas. Nesse período, foram registrados, dentre as 100\npessoas expostas ao fator de risco, 20 casos da doença, e, dentre as não expostas, 10 casos da\ndoença. Esse estudo epidemiológico é do tipo:","options":{"A":"caso-controle.","B":"corte.","C":"corte transversal.","D":"prevalência.","E":"transversal."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-111584","number":"111584","sourceNumber":"111584","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Num estudo epidemiológico com o objetivo de testar hipótese etiológica entre um\ndeterminado fator de risco e\n\numa doença específica, verificou-se a incidência do agravo, durante um período de tempo, em um\ngrupo de estudo constituído por 300 pessoas. Nesse período, foram registrados, dentre as 100\npessoas expostas ao fator de risco, 20 casos da doença, e, dentre as não expostas, 10 casos da\ndoença. O risco relativo é igual a:","options":{"A":"1.","B":"3.","C":"4.","D":"7.","E":"13."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-111591","number":"111591","sourceNumber":"111591","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Num estudo epidemiológico com o objetivo de testar hipótese etiológica entre um\ndeterminado fator de risco e\n\numa doença específica, verificou-se a incidência do agravo, durante um período de tempo, em um\ngrupo de estudo constituído por 300 pessoas. Nesse período, foram registrados, dentre as 100\npessoas expostas ao fator de risco, 20 casos da doença, e, dentre as não expostas, 10 casos da\ndoença. O risco atribuível é igual a:","options":{"A":"0,15%","B":"1,3%.","C":"10,0%","D":"13,0%","E":"15,0%."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-111597","number":"111597","sourceNumber":"111597","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Para testar associações etiológicas com uma doença de baixa incidência no município,\ndesenvolveu-se um estudo longitudinal e retroanalítico, iniciando-se pela seleção de um grupo de\npessoas com a doença em estudo e outro, sem a doença. Trata-se de um estudo do tipo:","options":{"A":"análise de prevalência.","B":"caso controle.","C":"coorte.","D":"coorte concorrente.","E":"ensaio clínico randomizado."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-106393","number":"106393","sourceNumber":"106393","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um adulto jovem de 30 anos é admitido com dor torácica. Ele não tem qualquer fator de\nrisco para doença coronária. O médico da emergência solicita um teste de esforço após as\nprimeiras enzimas cardíacas e eletrocardiograma terem sido avaliados e eram normais. O teste de\nesforço realizado é considerado positivo para isquemia miocárdica. Você é chamado para uma\nconsulta cardiológica para este paciente e estima que a probabilidade de doença coronária\n\npré-esforço era de 10%. Você julga, então, que a prova de esforço é provavelmente um exame\nfalso-positivo, com baixa probabilidade pós-exame de doença arterial coronária. O caso exposto\ntrata-se de um exemplo de qual dos seguintes princípios usados na tomada de decisão clínica?","options":{"A":"Teorema de Bayes","B":"Valor preditivo positivo alto","C":"Alta especificidade","D":"Valor preditivo negativo baixo","E":"Baixa sensibilidade"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-106399","number":"106399","sourceNumber":"106399","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Qual dos seguintes valores é afetado pela prevalência da doença em uma população?","options":{"A":"Número necessário para tratar.","B":"Razão de probabilidade positiva.","C":"Valor preditivo positivo.","D":"Sensibilidade.","E":"Especificidade."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-100968","number":"100968","sourceNumber":"100968","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A epidemiologia descritiva atende ao objetivo primário desta ciência que é a descrição\npadrão de distribuição das doenças. Ao\nfazê-lo, a epidemiologia descritiva utiliza três conjuntos de\nvariáveis: relacionadas ao tempo, ao lugar e às pessoas. Sobre esses três conjuntos, é correto\nafirmar:","options":{"A":"Os dados sistemáticos relativos ao espaço são obtidos por procedimentos de inquérito.","B":"Período é a denominação de ordem geral que se dá as partes do tempo delimitadas e\nespecificadas.","C":"As variáveis relativas às pessoas guardam estrita dependência do tempo e do espaço.","D":"Se não há fator interveniente, espera-se que em qualquer país o número de homens e mulheres\nseja igual.","E":"Os fatores geográficos compõem um sistema ecológico simples em que os condicionantes estão\ndesvinculados da estrutura social."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-101011","number":"101011","sourceNumber":"101011","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"TEMA: além dos fatores de risco bem conhecidos, o Vírus Epstein-Barr (EBV) pode\ndesempenhar um papel significativo no\nCarcinoma Epidermoide de Boca (CEB). Para explorar o\npapel do EBV em CEB, a prevalência da infecção pelo EBV em células esfoliadas orais de casos\nde CEB e controles no nordeste da Tailândia foi investigada, e a associação de EBV com células\nda lesão tumoral foi confirmada. MÉTODOS: células esfoliadas orais foram coletadas de casos de\nCEB e controles sem neoplasia. Células de lesões tumorais foram retiradas de pacientes com\ntumores para uma confirmação mais robusta da associação de EBV com CEB. DNA de EBV foi\ndetectado por meio de Reação em Cadeia da Polimerase (PCR), utilizando iniciadores específicos\npara a DNA polimerase de EBV. As amostras positivas de DNA de EBV foram confirmadas ainda\npor nested PCR. RESULTADOS: o vírus de Epstein-Barr foi detectado nas células esfoliadas orais\nde 45,05% de pacientes com tumores e 18,08% dos controles (p < 0,001). Da mesma forma, o EBV\nfoi detectado em 32,5% das lesões tumorais. Mascar betel foi estatisticamente associado à\nprevalência de EBV (OR = 2,08), enquanto que nenhuma associação foi encontrada com o\ntabagismo e o consumo de álcool. O consumo de álcool e mascar betel foram significativamente\nassociados com CEB (OR = 3,05 e OR = 5,05, respectivamente), mas o consumo de tabaco não foi\nassociado. Curiosamente, EBV foi significativamente associado com CEB (OR = 3,76).\n\nCONCLUSÕES: a prevalência do Vírus Epstein-Barr está associada a CEB e parece ser reforçada\npor mascar betel, o que sugere que o EBV pode,\njuntamente com mascar betel, atuar como um\nimportante fator de risco etiológico da CEB (J Oral Pathol Med, 2014. Epub ahead of print).\n\nAssinale, entre as alternativas abaixo, aquela que corretamente indica o tipo do estudo:","options":{"A":"Estudo observacional descritivo do tipo coorte transversal.","B":"Estudo observacional analítico do tipo coorte transversal.","C":"Estudo observacional descritivo do tipo coorte.","D":"Estudo observacional descritivo do tipo caso-controle.","E":"Estudo observacional analítico do tipo caso-controle."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-100944","number":"100944","sourceNumber":"100944","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"TEMA: Além dos fatores de risco bem conhecidos, o vírus Epstein-Barr (EBV), pode\ndesempenhar um papel significativo no\nCarcinoma Epidermoide de Boca (CEB). Para explorar o\npapel do EBV em CEB, a prevalência da infecção pelo EBV em células esfoliadas orais de casos\nde CEB e controles no nordeste da Tailândia foi investigada, e a associação de EBV com células\nda lesão tumoral foi confirmada. MÉTODOS: Células esfoliadas orais foram coletadas de casos de\nCEB e controles sem neoplasia. Células de lesões tumorais foram retiradas de pacientes com\ntumores para uma confirmação mais robusta da associação de EBV com CEB. DNA de EBV foi\ndetectado por meio de reação em cadeia da polimerase (PCR), utilizando iniciadores específicos\npara a DNA polimerase de EBV. As amostras positivas de DNA de EBV foram confirmadas ainda\npor nested PCR. RESULTADOS: O vírus de Epstein-Barr foi detectado nas células esfoliadas orais\nde 45,05% de pacientes com tumores e 18,08% dos controles (p<0,001). Da mesma forma, o EBV\nfoi detectado em 32,5% das lesões tumorais. Mascar Betel foi estatisticamente associado à\nprevalência de EBV (OR = 2,08), enquanto que nenhuma associação foi encontrada com o\ntabagismo e o consumo de álcool. O consumo de álcool e mascar betel foram significativamente\nassociados com CEB (OR = 3,05 e OR = 5,05, respectivamente), mas o consumo de tabaco não foi\nassociado. Curiosamente, EBV foi significativamente associado com CEB (OR = 3,76).\n\nCONCLUSÕES: A prevalência do vírus Epstein-Barr está associada a CEB e parece ser reforçada\npor mascar betel, o que sugere que o EBV pode,\njuntamente com mascar betel, atuar como um\nimportante fator de risco etiológico da CEB (J Oral Pathol Med, 2014. Epub ahead of print). Sobre a\npresença de vieses, assinale a alternativa correta:","options":{"A":"O viés de seleção é de ocorrência improvável porque o desfecho ainda não ocorreu.","B":"Este tipo de estudo é particulamente vulnerável a vieses por perda amostral.","C":"O viés de informação é provável porque o dado principal obtido no estudo é o resultado de\nentrevista.","D":"Há presença de viés diferencial que incide no grupo de casos, um provável resíduo de estudos\nanteriores.","E":"A situação de saúde bucal odontológica e gengival pode representar fator de confusão."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-100947","number":"100947","sourceNumber":"100947","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"TEMA: Além dos fatores de risco bem conhecidos, o vírus Epstein-Barr (EBV), pode\ndesempenhar um papel significativo no\ncarcinoma epidermoide de boca (CEB). Para explorar o\npapel do EBV em CEB, a prevalência da infecção pelo EBV em células esfoliadas orais de casos\nde CEB e controles no nordeste da Tailândia foi investigada, e a associação de EBV com células\nda lesão tumoral foi confirmada. MÉTODOS: Células esfoliadas orais foram coletadas de casos de\nCEB e controles sem neoplasia. Células de lesões tumorais foram retiradas de pacientes com\ntumores para uma confirmação mais robusta da associação de EBV com CEB. DNA de EBV foi\ndetectado por meio de reação em cadeia da polimerase (PCR), utilizando iniciadores específicos\npara a DNA polimerase de EBV. As amostras positivas de DNA de EBV foram confirmadas ainda\npor nested PCR. RESULTADOS: O vírus de Epstein-Barr foi detectado nas células esfoliadas orais\nde 45,05% de pacientes com tumores e 18,08% dos controles (p<0,001). Da mesma forma, o EBV\nfoi detectado em 32,5% das lesões tumorais. Mascar Betel foi estatisticamente associado à\nprevalência de EBV (OR = 2,08), enquanto que nenhuma associação foi encontrada com o\ntabagismo e o consumo de álcool. O consumo de álcool e mascar betel foram significativamente\nassociados com CEB (OR = 3,05 e OR = 5,05, respectivamente), mas o consumo de tabaco não foi\nassociado. Curiosamente, EBV foi significativamente associado com CEB (OR = 3,76).\n\nCONCLUSÕES: A prevalência do vírus Epstein-Barr está associada a CEB e parece ser reforçada\npor mascar betel, o que sugere que o EBV pode,\njuntamente com mascar betel, atuar como um\nimportante fator de risco etiológico da CEB (J Oral Pathol Med, 2014. Epub ahead of print). Sobre\nas medidas de efeito no estudo em questão, assinale a alternativa correta:","options":{"A":"O efeito observado não é apresentado.","B":"O efeito observado é grande.","C":"O efeito observado é moderado a grande.","D":"O efeito observado é moderado a pequeno.","E":"O efeito observado é pequeno."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-100966","number":"100966","sourceNumber":"100966","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Ao estudarmos os fatores de risco em alcoolistas para Pacreatite Crônica e Cirrose\nHepática, encontramos o trabalho de Nakamura e\ncolaboradores de 2004 (J Gastroenterol 2004;\n39:879-887), que apresentava uma tabela com os seguintes dados: (adaptado). Tabela 1: Fatores\nde risco para Pancreatite Crônica Alcoólica (PCC) e Cirrose Hepática Alcoólica (CH) em 141\nalcoolistas masculinos japoneses. (OR- Odds Ratio, IC- Intervalo de Confiança). (VER IMAGEM).\nAo avaliarmos esta tabela, é correto afirmar que os autores encontraram os seguintes resultados\nem suas observações com os alcoolistas:","options":{"A":"A idade foi fator de risco para PCC e para CH, com significância estatística.","B":"A duração de uso de álcool (maior número de anos) foi fator de risco para PCC e para CH, com\nsignificância estatística.","C":"O tabaco não foi fator de risco para PCC, mas foi fator protetor para lesão hepática mais\navançada, com significância estatística.","D":"O tabaco não foi fator de risco para PCC, mas foi fator de risco para lesão hepática mais\navançada, com significância estatística.","E":"O tabaco foi fator de risco para PCC e para lesão hepática mais avançada, com significância\nestatística."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-87402","number":"87402","sourceNumber":"87402","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Diferentemente do raciocínio causal, o raciocínio probabilístico tenta estimar:","options":{"A":"A validação de um teste diagnóstico.","B":"A possibilidade de justificar os achados de um paciente a partir de conhecimentos clínicos e\nfisiopatológicos sobre uma determinada doença.","C":"A probabilidade de doença nos vários momentos do processo diagnóstico de forma quantitativa.","D":"Cada doença ou situação clínica apresentada nos testes padrão-ouro.","E":"A eficácia do teste padrão-ouro de forma qualitativa."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-87371","number":"87371","sourceNumber":"87371","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale a alternativa INCORRETA:","options":{"A":"A eficácia de um tratamento é a evidência de que ele realmente funciona.","B":"A efetividade é a evidência de que a intervenção funciona.","C":"Embora eficácia/efetividade sejam sinônimos, os termos têm sido usados de modo diferentes.","D":"Evidências de eficácia são geralmente demonstradas por vários tipos de delineamento de\npesquisas, entre os quais o ideal seria o ensaio clínico caso-controle.","E":"A terapia prescrita para uma doença tem como meta a melhora de seu curso clínico, o que pode\nsignificar a melhora de sintomas já manifestados ou a prevenção de outros ainda latentes."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-87380","number":"87380","sourceNumber":"87380","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os principais tipos de análises econômicas para avaliação de uma intervenção clínica\nsão análises de:","options":{"A":"benefícios e custo-efetividade.","B":"população doente e sadia e custo relativo.","C":"risco e probabilidade do teste controle.","D":"custo-efetividade, custo-utilidade e custo-minimização.","E":"eficácia e eficiência do trabalho."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-87386","number":"87386","sourceNumber":"87386","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale a alternativa INCORRETA:","options":{"A":"As clássicas medidas de mortalidade e morbidade permitem quantificar as condições de saúde\nde uma população ou grupo populacional por\nmeio da utilização de parâmetros opostos.","B":"O conceito de saúde estabelecido pela OMS como o estado de \"completo bem-estar físico,\nmental e social, e não somente ausência de afecções e enfermidades\" tem uma formulação\nestrategicamente positivista em relação à saúde, já que esta pode ser garantida pelo médico\nassistente.","C":"As informações sobre mortalidade no Brasil são obtidas pelo Sistema de Informações de\nMortalidade (SIM), que é alimentado pelas\ndeclarações de óbito, de preenchimento compulsório em\ntodo o País.","D":"No Brasil, os censos demográficos nacionais são realizados desde 1980, sendo esse realizado a\ncada cinco anos.","E":"Mudanças demográficas e de aporte nutricional levam a alterações importantes no perfil de\nmorbimortalidade da população brasileira, processo esse denominado de transição demográfica."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-88918","number":"88918","sourceNumber":"88918","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Odds ratio é uma medida de associação tipo proporcionalidade, utilizada na análise de\nestudos epidemiológicos. Ela é específica para estudos de:","options":{"A":"Caso-controle.","B":"Ecológicos.","C":"Seccionais.","D":"Coorte.","E":"Intervenção."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-339843","number":"339843","sourceNumber":"339843","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um pesquisador selecionou 600 mulheres menopausadas em 4 hospitais de\nPernambuco e São Paulo, no período de 2000\na 2010, tendo sido comparadas com 1.000 mulheres\ninternadas nos mesmos hospitais, no mesmo período, apresentando outros cânceres ou outras\ncondições clínicas. O fator em estudo era o uso prévio de estrogênios. Sobre essa pesquisa,\nassinale a alternativa que indica o tipo de estudo epidemiológico utilizado.","options":{"A":"Coorte.","B":"Intervenção.","C":"Caso-controle.","D":"Ensaio clínico.","E":"Inquérito."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-218241","number":"218241","sourceNumber":"218241","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo realizado no Hospital Primavera da Cidade do Norte mostrou um estudo de\ncoorte em relação a hipertensão arterial como fator de risco para infarto agudo do miocárdio, com\nrisco relativo de 3,0 com significância de p = 0,04. Com esses dados, é CORRETO afirmar que\nnesse estudo:","options":{"A":"Considera-se acaso uma possibilidade de 4% de associação observada entre as doenças\n(hipertensão arterial e infarto agudo do miocárdio).","B":"12% dos pacientes com infarto agudo do miocárdio terão hipertensão arterial.","C":"30% dos pacientes com hipertensão arterial terão infarto agudo do miocárdio.","D":"30% dos pacientes com infarto agudo do miocárdio não têm hipertensão arterial."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-354838","number":"354838","sourceNumber":"354838","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"De acordo com o livro Medicina Ambulatorial: Condutas de Atenção Primária Baseadas\nem Evidências, Duncan, B. B., et al., (2022), o\nnúmero necessário para tratar (NNT) das\nterapêuticas direcionadas para redução dos riscos de fraturas são mostrados na tabela a seguir.\n\nUtilizando os dados da tabela e se valendo do conhecimento acerca da aplicabilidade da Medicina\nBaseada em Evidências (MBE) no tópico do tratamento, dos aspectos do Método Clínico Centrado\nna Pessoa (MCCP), bem como, do tratamento da Osteoporose um médico pode,","options":{"A":"sugerir ao paciente que opte pela vitamina D + cálcio pelo seu alto NNT na prevenção da fratura\nde quadril (importante causa de\nmorbimortalidade nos idosos), na impossibilidade financeira do\npaciente adquirir bisfosfonato e vitamina D + cálcio.","B":"prescrever ao paciente o ácido zoledrônico alertando sobre o fato da medicação ser intravenosa\ne de que é menos eficaz para redução de\nfratura vertebral que o risedronato, quando a comodidade\nde aplicar a medicação ao paciente menos frequentemente for desejada.","C":"prescrever ao paciente o ácido zoledrônico alertando sobre o fato de que é mais eficaz para\nredução de fratura vertebral que o\nrisedronato, quando o paciente desejar evitar o uso intravenoso.","D":"prescrever ao paciente, que deseja tratamento oral, o alendronato que tem melhor NNT para\nredução de fratura vertebral que o risedronato, na impossibilidade financeira do paciente adquirir\nbisfosfonato e vitamina D + cálcio."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-363971","number":"363971","sourceNumber":"363971","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um teste para diagnosticar a presença de transtorno bipolar foi aplicado\nindividualmente em estudantes universitários\ncom idades entre 18 e 23 anos. A sensibilidade e a\nespecificidade do teste utilizado foram de 88% e 77%, respectivamente. De acordo com essas\ncaracterísticas do teste, era esperado que, a cada 100 participantes sem a doença,","options":{"A":"77 seriam diagnosticados corretamente (verdadeiros positivos).","B":"12 ficariam sem serem diagnosticados (falso negativos).","C":"88 seriam diagnosticados como isentos de transtorno bipolar (verdadeiros negativos).","D":"23 seriam incorretamente diagnosticados como tendo transtorno bipolar (falsos positivos)."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-363968","number":"363968","sourceNumber":"363968","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma investigação foi realizada pela comparação de estatísticas de diversos países,\nsendo encontrada correlação positiva,\nestatisticamente significativa, entre o montante de cigarros,\nper capita, vendido à população e o coeficiente de mortalidade por doenças cardiovasculares. Qual\né o tipo do estudo?","options":{"A":"Prevalência.","B":"Coorte.","C":"Ecológico.","D":"Caso-controle."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-363938","number":"363938","sourceNumber":"363938","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os vieses são processos que tendem a produzir resultados que se desviam\nsistematicamente dos valores verdadeiros. Um viés de seleção ocorre quando","options":{"A":"as variáveis clínicas são medidas de um modo sistematicamente diferente entre os grupos de\npacientes.","B":"uma terceira variável está associada com a exposição e, independentemente da exposição, é\num fator de risco para a doença.","C":"os casos tendem a lembrar com mais detalhes de sua história de doença e exposições\npregressas do que os controles.","D":"a associação entre a exposição e o desfecho observada na população de estudo é diferente\ndaquela que seria verificada caso fossem estudados todos os indivíduos da base populacional."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-363936","number":"363936","sourceNumber":"363936","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um ensaio clínico, para se calcular a redução relativa de risco, usa-se a seguinte\nfórmula:","options":{"A":"Incidência do desfecho no experimento- incidência do desfecho no controle.","B":"Incidência do desfecho no experimento / incidência do desfecho no controle.","C":"(1 - Risco Relativo) x 100.","D":"1 / Redução Absoluta do Risco."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-363908","number":"363908","sourceNumber":"363908","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em Goiânia (GO), no período de 1989-1990, um estudo avaliou a associação entre\nvacina BCG intradérmica e hanseníase. Todos\nos 62 casos novos de hanseníase, em escolares,\ndiagnosticados em um centro de saúde, foram comparados com 186 controles entre pessoas do\nmesmo sexo e idade. A presença de cicatriz, deixada pelo BCG, foi identificada em 24 escolares no\ngrupo de casos, e em 143 escolares no grupo de controles. Qual foi a efetividade estimada da\nvacina?","options":{"A":"51%.","B":"61%.","C":"71%.","D":"81%."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-346408","number":"346408","sourceNumber":"346408","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Para uma determinada patologia, o risco relativo para mulheres, comparadas aos\nhomens, foi 0,85 (IC de 95%, 0,67: 0,98).\nAssinale a alternativa que contém uma afirmação correta\nem relação ao estudo referido:","options":{"A":"O risco foi igual entre homens e mulheres;","B":"O risco em mulheres foi 85% menor que o risco em homens.;","C":"O risco em mulheres foi menor que o risco em homens;","D":"O risco em homens foi menor que o risco em mulheres."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-346413","number":"346413","sourceNumber":"346413","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O estabelecimento de um programa de rastreamento na população deve obedecer a\nalguns critérios. Idealmente, o exame escolhido para servir de primeira etapa de rastreamento para\nalguma doença ou condição na população geral deve ter:","options":{"A":"Alta especificidade, porque significa que teremos poucos falsos negativos;","B":"Alta especificidade, porque significa que teremos poucos falsos positivos;","C":"Alta sensibilidade, porque significa que teremos poucos falsos positivos;","D":"Alta sensibilidade, porque significa que teremos poucos falsos negativos."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-330075","number":"330075","sourceNumber":"330075","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"No que se refere aos princípios gerais de atuação do clínico, é CORRETO afirmar:","options":{"A":"No princípio da não maleficência, o médico, em todas as suas atitudes, deve sempre evitar\nqualquer atitude que possa prejudicar, causar\ndano, ou piorar as condições de saúde do paciente.","B":"No princípio da justiça, o médico, em todas as suas atitudes, deve sempre procurar fazer apenas\naquilo que visa beneficiar o paciente.","C":"No princípio da beneficência, o médico deve fazer o possível para que todos sejam tratados com\nequidade e possam ter acesso a cuidados de saúde de qualidade equivalente.","D":"No princípio da isonomia, o médico deve respeitar os desejos do paciente, informá-lo e\nconsultá-lo sobre tudo o que diz respeito à sua saúde, diagnósticos e prognósticos."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-334793","number":"334793","sourceNumber":"334793","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A colonoscopia constitui uma ferramenta diagnóstica e terapêutica importante nas\ndoenças do aparelho digestivo. O ensaio\nclinico randomizado \"Effect of colonoscopy screening on\nrisk of colorectal cancer and related death\" (tradução livre: Efeito da colonoscopia de rastreio no\nrisco do câncer colorretal e mortalidade relacionada\") publicado na revista New England Journal of\nMedicine este ano 2022, testou a hipótese se a colonoscopia reduz a incidência do câncer\ncolorretal, comparando pacientes que fizeram a colonoscopia versus os pacientes que não fizeram\no exame (grupo controle). Os resultados do ensaio clínico são apresentados no gráfico a seguir. Os\nresultados apresentados mostram que","options":{"A":"a incidência de câncer colorretal ao fim do estudo foi maior nos pacientes que fizeram a\ncolonoscopia.","B":"o risco relativo de câncer colorretal foi de 1,22 para os pacientes que fizeram a colonoscopia.","C":"A redução relativa do risco do câncer colorretal nos pacientes foi de 18%.","D":"A colonoscopia não reduz a incidência do câncer colorretal."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-321567","number":"321567","sourceNumber":"321567","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Avaliar se existe associação entre duas características quantitativas é objetivo de\nmuitos estudos nas ciências da saúde. Um médico deseja avaliar se a pressão arterial está\ncorrelacionada à idade das pessoas. Para isso, ele deve utilizar:","options":{"A":"A correlação linear simples.","B":"O teste Qui-Quadrado.","C":"A correlação curva de Chiari.","D":"O teste exato de Fisher."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-321569","number":"321569","sourceNumber":"321569","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Analise os resultados de um ensaio clínico no quadro. De acordo com os cálculos das\nmedidas de associação/efeitos de intervenção:","options":{"A":"A vacina é um fator de risco para a doença.","B":"O grupo de vacinados teve uma redução de 80% da doença quando comparado ao grupo de\nnão vacinados.","C":"A vacina diminuiu o número absoluto de casos de doença de 20% para 2% (eliminação de 18%\ndo evento).","D":"É necessário vacinar aproximadamente 8 pacientes (8,3) para se evitar um caso da doença."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-321573","number":"321573","sourceNumber":"321573","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Alguns autores investigaram a associação entre o consumo materno de cocaína e a\nprematuridade. Eles iniciaram a pesquisa revisando todos os registros de nascimentos ocorridos\ndurante o ano de 1988 para a obtenção das informações sobre o uso de cocaína pela mãe. A\nmulher era considerada exposta se o uso de cocaína tivesse sido indicado em algum momento nos\nregistros do pré-natal. Posteriormente, consultaram as informações sobre a idade gestacional ao\nnascimento. Qual foi o delineamento desse estudo?","options":{"A":"Seccional.","B":"Ecológico.","C":"Caso-controle.","D":"Coorte."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-321577","number":"321577","sourceNumber":"321577","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Analise o quadro referente a um teste diagnóstico. Qual o cálculo para se encontrar o\nvalor da Razão de Verossimilhança Negativa?","options":{"A":"A/A+C dividido por B/B+D.","B":"C/A+C dividido por D/B+D.","C":"A/A+B dividido por D/C+D.","D":"C/C+D dividido por A/A+B."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-331999","number":"331999","sourceNumber":"331999","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo foi realizado com 13.987 pessoas com idade superior a 50 anos, sem\ndoença cardiovascular, demência ou deficiência\nfísica na admissão. Foram divididos em: Grupo A -\n6.994 participantes designados aleatoriamente para receber o fármaco em teste; Grupo B - 6.993\nparticipantes, para receber placebo. A adesão ao tratamento foi de 71,1% no Grupo A e de 73,1%\nno grupo B. O ensaio clínico foi encerrado com uma mediana de 2,7 anos de acompanhamento.\n\nInforme que tipo de estudo foi realizado:","options":{"A":"Ensaio clínico duplo-cego randomizado.","B":"Coorte prospectiva.","C":"Estudo de corte transversal.","D":"Estudo ecológico.","E":"Estudo de caso-controle."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-332000","number":"332000","sourceNumber":"332000","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Avalie as afirmativas abaixo e assinale a alternativa CORRETA: I. A metanálise é a\ncombinação de resultados de estudos desde que sejam suficientemente semelhantes. II. Os\nmelhores estudos para definir se uma intervenção é eficaz são os estudos de coorte prospectiva.\n\nIII. Estudos ecológicos são úteis para levantar hipóteses, mas podem apresentar um viés\ndenominado de falência ecológica.","options":{"A":"Apenas a alternativa I está correta.","B":"As alternativas II e III estão corretas.","C":"As alternativas I e III estão corretas.","D":"As alternativas I e II estão corretas.","E":"Todas as alternativas estão corretas."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-332008","number":"332008","sourceNumber":"332008","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Você está comparando a média de peso entre homens e mulheres antes e depois de\numa série de tratamentos para a obesidade.\nTomando por base que os dados das amostras são\nparamétricos, o teste de hipóteses que poderia ser aplicado nessa pesquisa seria o:","options":{"A":"Teste de média ponderada.","B":"Teste de x²","C":"Teste de kolmogorov.","D":"Teste de correlação.","E":"Teste t de student."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-339835","number":"339835","sourceNumber":"339835","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O(A) Médico(a) Residente deve saber interpretar e analisar criticamente a literatura\ncientífica. O conhecimento sobre os tipos de\nestudo é crucial. Assinale a alternativa que caracteriza\nos estudos cirúrgicos tipo caso-controle.","options":{"A":"Usado para descrever a prevalência de uma doença","B":"Examina a associação de fatores de risco a desfechos incomuns","C":"Não tem viés de seleção","D":"Tem grande potencial de estabelecer uma relação de causa e efeito","E":"Combina resultados de estudos clínicos (caso) e experimentais (controle)"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-339836","number":"339836","sourceNumber":"339836","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo foi conduzido sobre os sinais e sintomas físicos em 247 pacientes avaliados\npara Tuberculose Pulmonar (TB). O diagnóstico\nfinal foi feito de acordo com os achados da cultura\n(padrão-ouro). Noventa e cinco pacientes tinham TB, e 49 deles também tinham hemoptise. Cento\ne cinquenta e dois não tinham TB, e 79 desses pacientes tinham hemoptise. Analisando esse\nestudo, qual a especificidade da hemoptise para TB?","options":{"A":"38%","B":"48%","C":"52%","D":"61%","E":"76%"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-339837","number":"339837","sourceNumber":"339837","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considerando o estudo da questão anterior, se o médico pensou que o paciente tinha\nTB por causa da hemoptise, em qual porcentagem dos pacientes ele estava certo?","options":{"A":"38%","B":"48%","C":"52%","D":"61%","E":"76%"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-339839","number":"339839","sourceNumber":"339839","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sobre os estudos epidemiológicos, qual dos seguintes estudos NÃO pode ser usado\npara identificar fatores prognósticos?","options":{"A":"Coorte","B":"Caso-controle","C":"Prevalência","D":"Análise de tempo até o evento","E":"Nenhuma das alternativas"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-339845","number":"339845","sourceNumber":"339845","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na tabela abaixo, temos um diagrama de um teste diagnóstico da epidemiologia,\nutilizado para a aferição de um teste\ndiagnóstico comparado ao Padrão-ouro. Considerando a\ntabela da questão anterior, um estudo de Coorte, o resultado da divisão do valor descrito na casela\n\"a\" pelo valor da casela \"a+b\" (a/a+b) é denominado de","options":{"A":"Risco Relativo.","B":"Incidência em expostos.","C":"Incidência em não expostos.","D":"Odds Ratio.","E":"Acurácia."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-342685","number":"342685","sourceNumber":"342685","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A randomização é uma técnica de alocação que visa:","options":{"A":"impedir que indivíduos sem critérios de elegibilidade sejam incluídos no estudo","B":"evitar perdas seletivas de acompanhamento que levem a resultados enviesados","C":"garantir a distribuição homogênea de características prognósticas entre os grupos comparados","D":"garantir que os alocados em diferentes grupos de tratamento recebam a mesma qualidade de\nassistência"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-342686","number":"342686","sourceNumber":"342686","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Com relação ao viés em pesquisas clínicas, analise as assertivas a seguir, conforme\ndescrito por Fletcher (2006): I - O viés de\nseleção ocorre quando são feitas comparações entre\ngrupos de pacientes que diferem em outros determinantes do desfecho, além do que está sendo\nestudado. II - O viés de aferição ocorre quando os métodos de aferição são iguais entre os grupos\nde pacientes. III - O viés de confusão ocorre quando 2 fatores estão associados e seus efeitos não\nse confundem. Está(ão) correta(s):","options":{"A":"apenas I","B":"apenas III","C":"II, III","D":"I,II,III"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-334856","number":"334856","sourceNumber":"334856","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Mortalidade por covid-19 entre indígenas é 16% maior... [...] A pandemia de COVID-19\nprovocou até o momento a morte de 889\nindígenas e a contaminação de 41.250 integrantes de 161\ndos 305 povos originários que vivem no Brasil. A taxa de mortalidade entre a população indígena é\nde 991 por milhão, 16% superior à mortalidade geral no Brasil pela doença, hoje em 852 por\nmilhão....\n\nFonte:https://www.poder360.com.br/brasil/mortalidade-por-covid-19-entre-indigenas-e-16-maior-dw/\nAs medidas de associação fornecem dados sobre a força da associação entre o fator em estudo e\no desfecho, permitindo que se faça um julgamento sobre uma relação de causalidade. Neste\ncontexto, quais são as medidas de associação\nutilizadas para análise de estudos epidemiológicos?","options":{"A":"Razão de médias e correlação.","B":"Razão de prevalência e diferença de prevalência.","C":"Risco relativo e risco atribuível.","D":"Médias, frequências, prevalência e incidência."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-339847","number":"339847","sourceNumber":"339847","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O código de ética médica, em seu artigo 31, versa que é vedado ao médico:\n\"Desrespeitar o direito do paciente ou de seu\nrepresentante legal de decidir livremente sobre a\nexecução de práticas diagnósticas ou terapêuticas, salvo em caso de iminente risco de morte.\" O\nreferido artigo abrange o seguinte princípio bioético:","options":{"A":"Beneficência","B":"Não maleficência","C":"Autonomia","D":"Justiça","E":"Paternalismo."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-342687","number":"342687","sourceNumber":"342687","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo analítico, no qual há comparação entre os grupos estudo e controle, qual\ndos parâmetros a seguir não é levado em conta para o calculo amostral?","options":{"A":"o nível de significância estatística","B":"o valor do poder da amostra","C":"o tamanho da população de estudo","D":"a estimativa da taxa do desfecho em um dos grupos"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-342688","number":"342688","sourceNumber":"342688","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma pesquisa foi realizada a fim de investigar a prevalência do suicídio na\nadolescência, mediante a aplicação de um\nquestionário com perguntas fechadas, avaliando\nvariáveis demográficas, socioeconômicas e comportamentais associadas ao desfecho. A seleção\nda população foi realizada mediante uma seleção probabilística. Como esse estudo poderia ser\nclassificado?","options":{"A":"Ecológico.","B":"Caso-controle.","C":"Coorte.","D":"Transversal."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-342689","number":"342689","sourceNumber":"342689","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sobre os estudos epidemiológicos, assinale a alternativa correta:","options":{"A":"o estudo de coorte prospectiva é menos sujeito a vieses de memória quanto à exposição ao fator\nde risco do que um estudo caso-controle","B":"o estudo caso-controle possibilita calcular o risco relativo de uma doença diretamente,\ncomparando expostos e não expostos a determinado fator de risco","C":"estudos ecológicos permitem avaliar se a exposição de indivíduos a determinado fator aumenta\no risco de determinado desfecho","D":"em um estudo caso-controle, pessoas expostas e não expostas a determinado fator são\nseguidas no tempo para avaliar a incidência de um determinado desfecho"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-342690","number":"342690","sourceNumber":"342690","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um ensaio clínico randomizado foi realizado entre os indivíduos com diabetes. Entre os\n100 indivíduos alocados para tratamento, houve\n1 caso de pé diabético e, entre 100 alocados para\n18 placebo, houve 2 casos. Qual é o Número Necessário para Tratar (NNT) para previnir um único\ncaso de pé diabético entre indivíduos com as características desse estudo?","options":{"A":"50","B":"25","C":"10","D":"100"},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-334863","number":"334863","sourceNumber":"334863","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Ronaldson e colaboradores (2021) realizam uma análise do banco de dados do English\nLongitudinal Study of Ageing (ELSA) avaliando em 11.391 pessoas a relação entre clusters de\nmultimorbidade física e mudanças em comportamentos sociais ao longo de 15 anos. Quatro grupos\nde multimorbidade física foram identificados. Todos os clusters de multimorbidade física foram\nassociados a uma redução no envolvimento cultural (por exemplo, visitas a teatro, cinema, museus)\nao longo do tempo, com a associação mais forte observada no cluster complexo/multissistêmico (?\n\n= -0,26, IC 95% = -0,38 a - 0,15). Resultados semelhantes ocorreram para atividades de lazer.\nApós ajuste de modelo, a presença de sintomas depressivos atenuou totalmente algumas\nassociações. De acordo com as informações do texto, qual é a natureza deste estudo?","options":{"A":"Ecológico de séries temporais, no qual o ano de nascimento da população observada é\nespecificado e as taxas de mudanças de\ncomportamentos sociais em cada cluster são comparadas.","B":"Transversal sobre a relação entre agrupamentos de morbidades e comportamentos sociais, em\nque a maior taxa de prevalência de cluster\nfoi de 26%.","C":"Coorte longitudinal prospectivo controlado por variáveis de confusão na análise multivariada, em\nque a variável desfecho é a mudança no\ncomportamento social.","D":"Ensaio clínico, no qual se comparam mudanças em comportamentos sociais conforme presença\nde clusters de morbidades."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-339854","number":"339854","sourceNumber":"339854","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Alguns autores investigaram a associação entre o consumo materno de cocaína e a\nprematuridade. Eles iniciaram a pesquisa revisando todos os registros de nascimentos ocorridos\ndurante o ano de 1988 para a obtenção das informações sobre o uso de cocaína pela mãe. A\nmulher era considerada exposta se o uso de cocaína tivesse sido indicado em algum momento nos\nregistros do pré-natal. Posteriormente, consultaram as informações sobre a idade gestacional ao\nnascimento. Qual foi o delineamento desse estudo?","options":{"A":"Seccional.","B":"Ecológico.","C":"Caso-controle.","D":"Coorte."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-317922","number":"317922","sourceNumber":"317922","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na pesquisa científica em cirurgia, muitos desenhos de estudo são possíveis. Os\ndesenhos de estudo","options":{"A":"observacionais incluem Cohort e Caso-controle.","B":"experimentais são geralmente retrospectivos.","C":"observacionais são os que apresentam melhor nível de evidência.","D":"experimentais têm robustez quando a exposição e o desfecho acontecem ao mesmo tempo."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-314112","number":"314112","sourceNumber":"314112","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O estudo de coorte","options":{"A":"é individuado, observacional e longitudinal.","B":"apresenta alocação aleatória dos participantes.","C":"tem custo menos elevado do que o estudo de casos.","D":"necessita de mascaramento duplo cego para ser efetivo."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-314115","number":"314115","sourceNumber":"314115","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considerando as medidas de tendência central estudadas na bioestatística, um médico\ngestor deseja descobrir qual é o salário mais comum, isto é, qual é o salário recebido pelo maior\nnúmero de médicos do hospital. Neste caso, ele deverá usar a:","options":{"A":"variância.","B":"média.","C":"mediana.","D":"moda."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-314116","number":"314116","sourceNumber":"314116","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na avaliação de um teste diagnóstico, foram encontrados os seguintes resultados: Os\nvalores dos cálculos da sensibilidade e do valor preditivo negativo foram, respectivamente,","options":{"A":"0,9 e 0,888.","B":"0,5 e 0,850.","C":"0,8 e 0,818.","D":"0,2 e 0,181."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-311924","number":"311924","sourceNumber":"311924","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sabemos que o tempo médio de permanência hospitalar é igual ao número de\npacientes-dia em um determinado período/ saídas no período, sendo este valor multiplicado por\n\n100. Uma unidade hospitalar possui uma média de permanência em sua unidade de internação de\n10 dias. No mês de setembro de 2021, esta\nunidade de internação conseguiu 300 saídas\nhospitalares. O único fornecedor desta unidade de internação é o pronto atendimento deste serviço\nde saúde. Sabendo que o pronto atendimento durante o mês de setembro de 2021 fez 120\natendimentos por dia, qual a taxa de conversão/internação?","options":{"A":"50%","B":"20%","C":"30%","D":"25%"},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-317958","number":"317958","sourceNumber":"317958","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um grupo de pesquisadores divulgou os seguintes resultados na avaliação de um novo\nteste diagnóstico; Considerando esses resultados, conclui-se que a","options":{"A":"acurácia do teste foi 0,68.","B":"razão de verossimilhança negativa foi 0,35.","C":"especificidade do teste foi 0,47.","D":"razão de verossimilhança positiva foi 1,56."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-294285","number":"294285","sourceNumber":"294285","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Ao se realizar um ensaio clínico, os pesquisadores devem se atentar ao fenômeno no\nqual indivíduos mudam seu comportamento quando sabem que estão sendo observados e\nmonitorados. Pois, pode ocorrer o","options":{"A":"efeito placebo.","B":"viés de memória.","C":"efeito hawthorne.","D":"viés de perda de memória."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-295373","number":"295373","sourceNumber":"295373","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo ecológico, é possível que um coeficiente de correlação seja\napresentado. A esse respeito, analise o\ngráfico a seguir que foi exibido em um estudo desse tipo:\nDe acordo com os dados, é possível concluir que:","options":{"A":"Não há correlação.","B":"A correlação é próxima de -1.","C":"A correlação é próxima de 1.","D":"A correlação é próxima de 0."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-294287","number":"294287","sourceNumber":"294287","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na avaliação de um teste diagnóstico, foram encontrados os seguintes resultados: Os\nvalores dos cálculos da probabilidade pré-teste e da acurácia foram, respectivamente:","options":{"A":"5% e 25%.","B":"10% e 50%.","C":"20% e 75%.","D":"50% e 85%."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-294289","number":"294289","sourceNumber":"294289","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Estudo observacional ecológico, tendo como base dados obtidos através do Sistema de\nInformações sobre Mortalidade e aqueles obtidos por meio da Pesquisa Nacional de Saúde de\n2013, publicada pelo Instituto Brasileiro de Geografia e Estatística. Um dos cálculos que podem ser\nencontrados nesse delineamento de estudo é o do","options":{"A":"coeficiente de correlação.","B":"risco relativo.","C":"odds ratio.","D":"risco atribuível."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-317963","number":"317963","sourceNumber":"317963","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"No campo da bioestatística, há uma dificuldade técnica na aplicação do teste\n\nqui-quadrado quando o valor esperado em alguma caseia em uma tabela 2 x 2 é menor que 5. Uma\nalternativa nessa situação seria usar o teste","options":{"A":"exato de Fisher.","B":"de Glebson.","C":"de Berson.","D":"de Godfrey."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-295378","number":"295378","sourceNumber":"295378","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um teste chamado Gonosticon Dri-Drot apresentou sensibilidade de 0,80 e\nespecificidade 0,95 em uma população com\nprevalência da doença de 0,5. Os valores da predição\npositiva e negativa serão, respectivamente:","options":{"A":"0,94 e 0,83.","B":"0,87 e 0,91.","C":"0,05 e 0,17.","D":"0,64 e 0,98."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-308253","number":"308253","sourceNumber":"308253","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Médica da equipe 458, está atendendo pacientes em sala do Covid, quando adentra o\nrecinto paciente com quadro típico de síndrome gripal. A enfermeira que faz a triagem faz o exame\ndo mesmo e detecta uma frequência respiratória aumentada, sinais de esforço respiratório e\nSatO2=88% em ar ambiente. Prontamente a doutora solicita que seja iniciado O2 em máscara a 5l\npor minuto. Tendo em vista o caso e seus conhecimentos de Medicina Baseada em Evidências,\nassinale o princípio em que a referida médica se baseou para a tomada de decisão acima.","options":{"A":"Principio da plausibilidade extrema.","B":"Princípio da prova de conceito.","C":"Princípio do nível de evidencia.","D":"Princípio da hipótese nula."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-295379","number":"295379","sourceNumber":"295379","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na bioestatística, se um mesmo número é somado a todos os elementos de um\nconjunto de dados,","options":{"A":"haverá redução do valor da média correspondente ao número adicionado.","B":"o valor do desvio-padrão não sofrerá alteração.","C":"haverá aumento do valor do desvio-padrão correspondente ao número adicionado.","D":"o valor da média não sofrerá alteração."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-294292","number":"294292","sourceNumber":"294292","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um inquérito sorológico, foi apresentada uma análise bivariada de algumas\ncaracterísticas dos participantes e infecção\npelo vírus da dengue, usando um teste estatístico com\np-valor com nível de significância <0,05, conforme demonstrado na tabela a seguir. De acordo com\nos resultados, houve associação significativa entre o desfecho e a variável","options":{"A":"sexo.","B":"escolaridade do chefe da família.","C":"tipo de moradia.","D":"história prévia de dengue."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-294294","number":"294294","sourceNumber":"294294","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na bioestatística, com relação à Distribuição Normal,","options":{"A":"sua origem está associada à atuação de John Snow, considerado o pai da epidemiologia\nmoderna.","B":"a área total sob a curva e acima do eixo horizontal é igual a zero.","C":"a média é igual à mediana que é igual à moda.","D":"Distribuições normais com o mesmo desvio-padrão e diferentes médias possuem a mesma\nlocalização, mas diferem quanto à forma."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-317968","number":"317968","sourceNumber":"317968","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Leia as informações da seguinte pesquisa. Todas as 300 crianças em uma comunidade\nem que é feito o diagnóstico de debilidade\nmental, em um determinado período, são incluídas na\ninvestigação, à medida que o diagnóstico é confirmado. Elas são submetidas a teste sorológico\npara toxoplasmose, no intuito de inferir se tiveram ou não infecção prévia pelo Toxoplasma gondii.\nO mesmo exame de toxoplasmose é realizado em igual número de crianças sem debilidade mental,\nconforme os resultados a seguir. O delineamento da pesquisa e o valor da medida de associação\nforam, respectivamente:","options":{"A":"coorte - 1,58.","B":"ecológico - 2,10.","C":"caso-controle - 3,35.","D":"ensaio clínico - 1,58."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-317971","number":"317971","sourceNumber":"317971","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Analise a tabela a seguir de um ensaio clínico. Um pesquisador, realizando o cálculo\n1/(Rc-Rt), chega no resultado","options":{"A":"do Risco Relativo.","B":"da Redução Absoluta do Risco.","C":"do Número Necessário para Tratar.","D":"da Redução Relativa do Risco."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-317972","number":"317972","sourceNumber":"317972","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os testes diagnósticos em paralelo","options":{"A":"aumentam a especificidade.","B":"aumentam a sensibilidade.","C":"têm valor preditivo positivo alto.","D":"não são mais indicados na atualidade."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-317198","number":"317198","sourceNumber":"317198","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Identifique os tipos de estudo epidemiológico a seguir: partir da doença para conhecer a\nexposição que é o estudo ; partir da exposição para conhecer a doença que é o\nestudo ; partir da doença e da exposição, concomitantemente, que é o estudo\n\n. Assinale a alternativa que, correta e respectivamente, preenche as lacunas.","options":{"A":"de coorte, de caso e controle, transversal.","B":"de coorte, transversal, de caso e controle.","C":"de caso e controle, de coorte, transversal.","D":"Transversal, de coorte, de caso e controle."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-311950","number":"311950","sourceNumber":"311950","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O rastreamento de agentes infecciosos em doadores de sangue impede a\ncontaminação dos receptores. É de extrema\nimportância, então, que os testes utilizados nesse\nrastreamento tenham:","options":{"A":"Alta sensibilidade, já que o ônus de se deixar de fazer o diagnóstico é alto.","B":"Alta especificidade, já que o ônus de um diagnóstico errôneo é alto.","C":"Alto valor preditivo positivo para detecção de todos os casos positivos.","D":"Alto valor preditivo negativo para eliminar doadores não adequados."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-311956","number":"311956","sourceNumber":"311956","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um médico de família analisa os dados relativos à mortalidade na sua área de\nabrangência da Unidade Básica de Saúde em que\ntrabalha e constata que uma dada doença é\nresponsável por uma grande parcela das mortes na população. Ele resolve criar um programa para\nidentificar, mais precocemente possível, os portadores desta doença. O programa basear-se-á na\naplicação de um teste diagnóstico. Para tal, em se tratando de medicina baseada em evidências,\nassinale a alternativa correta quanto a principal característica que o teste em questão deve ter.","options":{"A":"Alta sensibilidade.","B":"Alto valor preditivo negativo.","C":"Alto valor preditivo positivo.","D":"Alta especificidade."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-300875","number":"300875","sourceNumber":"300875","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O médico, em sua relação médico-paciente, deve ter consigo os princípios\nfundamentais da Bioética moderna, a fim de\nevitar qualquer atitude que possa vir a prejudicar o\nindivíduo adoecido ou até piorar o seu estado crítico, bem como possibilitar cuidados e tratamentos\nde excelente qualidade e respeitar os seus anseios, informando-o sobre tudo que circunda a sua\nsaúde. Nesse sentido, NÃO diz respeito à área da Bioética o princípio da:","options":{"A":"Beneficência e justiça.","B":"Não maleficência e autonomia.","C":"Ética e justiça.","D":"Autonomia e beneficência."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-300877","number":"300877","sourceNumber":"300877","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considerando a classificação dos estudos epidemiológicos, quanto à divisão dos\nestudos observacionais, é INCORRETO afirmar:","options":{"A":"Estudos clínicos.","B":"Estudos ecológicos.","C":"Estudos de coorte.","D":"Estudos de caso."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-313264","number":"313264","sourceNumber":"313264","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo multicêntrico avaliou a correlação entre as taxas de incidência de câncer de\npele em diferentes faixas etárias e as horas médias de insolação diárias em diferentes regiões do\nplaneta. Trata-se de um estudo:","options":{"A":"De coorte, em que os indivíduos foram seguidos quanto a exposição ao sol em diferentes\nregiões do planeta.","B":"Ecológico, pois foram analisados, agregados espaciais com dados ambientais médios.","C":"Transversal, pois foram analisadas as incidências médias de câncer de pele em diferentes faixas\netárias.","D":"de caso-controle, pois foram analisados os casos de câncer de pele e comparados quanto à\nexposição ao sol."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-313268","number":"313268","sourceNumber":"313268","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O conhecimento da distribuição de uma doença na população é fundamental para a sua\ncondução. Para conhecer realmente qualquer agravo à saúde, torna-se imprescindível o\nconhecimento de seus aspectos epidemiológicos, tanto quanto os patológicos, imunológicos,\nclínicos, dentre outros. Qual é o método de escolha para estudos de prognóstico?","options":{"A":"estudo ecológico","B":"estudo de coorte","C":"estudo transversal","D":"estudo de caso-controle"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-313269","number":"313269","sourceNumber":"313269","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Com relação aos estudos experimentais, podemos afirmar que:","options":{"A":"as variáveis confusionais podem ser equilibradas pela randomização","B":"a variável dependente é representada pela intervenção","C":"o desfecho é também chamado de variável independente","D":"os grupos teste e controle são selecionados de populações diferentes"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-313271","number":"313271","sourceNumber":"313271","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale a alternativa que apresenta o estudo com pouca possibilidade de viés de\nseleção, pouca possibilidade de viés de informação e baixo tempo requerido para realização:","options":{"A":"transversal","B":"ecológico","C":"ensaio clínico","D":"caso-controle"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-313272","number":"313272","sourceNumber":"313272","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O odds ratio é uma medida de:","options":{"A":"efeito, pois quantifica adequadamente um fenômeno na população","B":"efeito, já que apresenta a probabilidade de o evento ocorrer","C":"ocorrência, pois é uma razão (ratio) entre 2 variáveis","D":"ocorrência, pois mostra o número de eventos e a população exposta"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-313274","number":"313274","sourceNumber":"313274","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale a alternativa que contém um estudo que pressupõe intervenção em seres\nhumanos:","options":{"A":"ensaio clínico","B":"ecológico","C":"coorte","D":"caso-controle"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-300893","number":"300893","sourceNumber":"300893","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma investigação com o intuito de avaliar a eficácia de um novo antibiótico na cura de\ninfecção urinária em adultos de 18 a 60 anos incluiu 100 indivíduos, sendo 60 mulheres e 40\nhomens. Decorridos 5 dias, 83 indivíduos estavam assintomáticos. Sendo assim, os investigadores\nconcluíram que o novo medicamento era eficaz na cura da infecção em adultos entre 18 e 60 anos.\nConsiderando essa conclusão, analise as proposições abaixo e, em seguida, assinale a alternativa\nCORRETA: I. Estamos diante de uma série de 100 casos sem avaliação de um grupo sem\ntratamento controle, portanto, não é possível definir o real benefício desse novo antibiótico. II. A\nconclusão é incorreta, porque o benefício de um antibiótico é dependente da condição\nsocioeconômica de quem o está usando e a pesquisa não considerou tal condição. III. Para\nconsiderar um antibiótico eficaz, é necessário saber, em população semelhante, quanto de cura\nseria obtida sem tratamento placebo ou comparar com o tratamento já conhecido semelhante ao\ntratamento melhor ou pior.","options":{"A":"Apenas I está correta.","B":"Apenas II e III estão corretas.","C":"Apenas I e III estão corretas.","D":"I, II e III estão corretas."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-273128","number":"273128","sourceNumber":"273128","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A Lei Estadual no 10.241, de 17 de março de 1999, do estado de São Paulo, conhecida\ncomo ?Lei Mário Covas?, dispõe sobre os\ndireitos dos usuários dos serviços e das ações de saúde\nno estado e dá outras providências, estabelecendo, por exemplo, em seu Artigo 2º, inciso VI, que\nsão direitos dos usuários dos serviços de saúde no estado de São Paulo ?receber informações\nclaras, objetivas e compreensíveis sobre hipóteses diagnósticas; diagnósticos realizados; exames\nsolicitados; ações terapêuticas; riscos, benefícios e inconvenientes das medidas diagnósticas e\nterapêuticas propostas; duração prevista do tratamento proposto ...?. O trecho descrito traduz, na\nmelhor das hipóteses, o princípio bioético da:","options":{"A":"Justiça.","B":"Equidade.","C":"Não maleficência.","D":"Autonomia."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-281819","number":"281819","sourceNumber":"281819","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo foi realizado com o objetivo de avaliar a possível associação entre o tipo de\npersonalidade e o risco de desenvolvimento de doença coronariana. Participaram do estudo 3.154\ntrabalhadores do sexo masculino. Por meio de entrevista no início do estudo, eles foram\nclassificados em dois tipos de personalidade (A e B) e, após a classificação, foram acompanhados\npor um período médio de nove anos. O delineamento do estudo e a medida calculada para se\navaliar a associação foram, respectivamente:","options":{"A":"caso-controle - risco relativo.","B":"coorte - risco relativo.","C":"caso-controle - odds ratio.","D":"prevalência - razão de prevalência."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-281820","number":"281820","sourceNumber":"281820","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em uma análise descritiva, as variáveis categóricas são mais apropriadamente\nrepresentadas pela seguinte representação\ngráfica:","options":{"A":"diagrama de barras.","B":"histograma.","C":"polígono de frequências.","D":"ogiva."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-281821","number":"281821","sourceNumber":"281821","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Ao se considerar o problema de comparação entre dois tratamentos, é usual fixar como\nhipótese de interesse a inexistência de diferença entre os dois tratamentos comparados. Como\nfrequentemente a comparação é feita entre um tratamento padrão e um tratamento novo, esta\nopção implica colocar o ônus da prova de efetividade no tratamento novo. Por essas razões, a\nhipótese a ser testada é usualmente chamada hipótese nula (H0), que deve ser comparada com\numa hipótese alternativa, denominada H1. Em termos técnicos, a decisão de rejeitar H0, quando de\nfato H0 é verdadeira, é chamada de erro do tipo","options":{"A":"I.","B":"II.","C":"III.","D":"IV."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-281826","number":"281826","sourceNumber":"281826","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A figura a seguir mostra a taxa de incidência (por 100.000 mulheres) de câncer no\ncólon e o consumo médio de carne na\npopulação de vários países (ARMSTRONG, B. & DOLL, R.,\n1975. International Journal of Cancer, 15:617-631). Uma associação foi sugerida: maior consumo\nde carne, maior incidência de câncer no cólon. O delineamento desse estudo foi:","options":{"A":"coorte.","B":"prevalência.","C":"caso-controle.","D":"ecológico."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-281827","number":"281827","sourceNumber":"281827","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere os dados a seguir. O cálculo da probabilidade pré-teste é:","options":{"A":"A + B / C + D","B":"A + B / N","C":"A / N","D":"A + C / N"},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-257739","number":"257739","sourceNumber":"257739","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um pesquisador oftalmologista de Sydney observou, no primeiro semestre de 1941,\nvários recém-nascidos com catarata congênita. As\ncaracterísticas pouco usuais dos casos o\nlevaram a procurar uma explicação que envolvesse as mães. Na pesquisa, verificou que todas\nforam acometidas de rubéola em uma grande epidemia que havia atingido a Austrália no ano\nanterior, exatamente durante o primeiro trimestre de gestação que resultaram no nascimento das\ncrianças com catarata congênita (Gregg, 1941). O estudo apresentado é delineado como:","options":{"A":"caso-controle.","B":"estudo de casos.","C":"coorte retrospectiva.","D":"ecológico."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-257740","number":"257740","sourceNumber":"257740","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Pesquisadores que tratam de doenças pulmonares em uma clínica especializada\nsugeriram um novo teste para detectar câncer\nno pulmão. Os resultados do estudo são descritos a\nseguir. Considerando os dados, a probabilidade de um paciente, atendido nessa clínica e que não\ntenha câncer no pulmão, ter um resultado positivo no teste e o valor da predição negativa são,\nrespectivamente,","options":{"A":"0,841 e 0,981.","B":"0,018 e 0,981.","C":"0,841 e 0,092.","D":"0,018 e 0,992."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-257741","number":"257741","sourceNumber":"257741","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A resposta de um indivíduo a uma terapêutica varia de acordo com suas características\npessoais. Assim, para que as diferenças\nporventura detectadas em um estudo sejam realmente\ndevidas à diferença na eficácia das terapias, é fundamental que os grupos de tratamento e controle\nsejam comparáveis. Uma maneira adequada de se atingir a comparabilidade é:","options":{"A":"o mascaramento duplo cego realizado pelos pesquisadores, em que os participantes e os\nexaminadores não sabem qual grupo está recebendo a terapêutica em estudo.","B":"o tamanho da amostra dos participantes, que deve ser grande o suficiente para garantir uma\nestimativa próxima ao valor real dos resultados.","C":"a alocação aleatória dos pacientes participantes no experimento aos grupos de controle e de\ntratamento.","D":"o cálculo da redução do risco relativo que informa a eficácia da intervenção quando comparada\nao controle."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-257742","number":"257742","sourceNumber":"257742","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em uma análise descritiva, o estado civil de participantes de um estudo é um tipo de\nvariável.","options":{"A":"quantitativa discreta.","B":"quantitativa contínua.","C":"categórica ordinal.","D":"categórica nominal."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-257743","number":"257743","sourceNumber":"257743","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um tipo de gráfico útil para a descrição de dados, visualização de sua variabilidade e\ncomparação entre diferentes grupos é o gráfico em caixas (boxplot). Para se construir um boxplot,\nobtêm-se primeiro algumas estatísticas. Entre elas, a mediana, que corresponde","options":{"A":"ao primeiro quartil (Q1).","B":"ao segundo quartil (Q2).","C":"ao terceiro quartil (Q3).","D":"à distância interquartílica (DQ)."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-257747","number":"257747","sourceNumber":"257747","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um pesquisador desenvolveu um estudo comparando a sintomatologia psiquiátrica dos\npacientes com surto esquizofrênico de um serviço especializado no momento da internação com a\nsintomatologia seis dias após o uso de um novo medicamento que ele acreditava ser eficaz para\ncontrolar o surto. Como resultado, encontrou uma redução dos sintomas iniciais. Nesse caso, o\ndelineamento desse estudo foi:","options":{"A":"ensaio clínico controlado.","B":"coorte.","C":"caso-controle.","D":"estudo de intervenção não controlado."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-258197","number":"258197","sourceNumber":"258197","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em 1982, foi realizado um estudo em que 22.071 médicos americanos voluntários\nforam divididos aleatoriamente em dois grupos. O\nprimeiro grupo, com 11.037 médicos, tomou a\ncada dois dias aspirina, enquanto o segundo, com 11.034 médicos tomou placebo. Os dois grupos\nforam acompanhados durante cinco anos pelo comitê que monitorava os dados obtidos. Os\nresultados do estudo estão descritos a seguir: Considerando esses resultados apresentados, a\naspirina foi considerada um fator de","options":{"A":"proteção em relação ao desfecho e o acaso tendeu a explicar o efeito protetor.","B":"risco em relação ao desfecho e o acaso tendeu a explicar o efeito de risco.","C":"proteção em relação ao desfecho e o acaso não tendeu a explicar o efeito protetor.","D":"risco em relação ao desfecho e o acaso não tendeu a explicar o efeito de risco."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-258198","number":"258198","sourceNumber":"258198","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os dados obtidos dos participantes de estudos médicos podem ser analisados e\ninterpretados com o auxílio de métodos estatísticos. Nesse sentido, a organização e síntese de\ndados é importante. É um exemplo de variável categórica nominal:","options":{"A":"estadiamento de uma doença.","B":"sexo.","C":"número de indivíduos que compõe a família.","D":"valor da pressão arterial sistêmica."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-285106","number":"285106","sourceNumber":"285106","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um dos campos importantes da Medicina Preventiva e Social é a epidemiologia clínica.\nNo que se refere a alguns conceitos\nrelacionados a ela, assinale a alternativa correta:","options":{"A":"Testes sensíveis não são úteis quando positivos.","B":"Valor preditivo negativo é a probabilidade de o paciente estar sadio entre os que tiveram o teste\npositivo.","C":"Uma vez definida a realização de um teste diagnóstico, o valor preditivo (positivo ou negativo)\ndesse teste não tem mais importância clínica\nrelevante.","D":"O valor preditivo negativo determina a sensibilidade e a especificidade de um teste.","E":"Testes altamente específicos são necessários quando resulta dos falsos positivos podem levar o\npaciente a tratamento ou conduta desnecessários e, às vezes, de risco."},"answer":"E","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-258201","number":"258201","sourceNumber":"258201","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo sobre a leitura de radiografias de tórax em pessoas com micobacteriose,\nforam encontrados os resultados a seguir. Os valores\ndas proporções de falso positivo e falso\nnegativo são, respectivamente:","options":{"A":"0,6986 e 0,0045.","B":"0,0045 e 0,6986.","C":"0,0284 e 0,2666.","D":"0,2666 e 0,0284."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-258204","number":"258204","sourceNumber":"258204","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"No Educandário Boa Esperança há 2400 estudantes que foram tratados contra\nparasitos intestinais. Após o tratamento,\ninvestigou-se a reinfestação por Giardia lamblia em relação\nao uso de água encanada. Os alunos foram acompanhados por sete meses, por meio de exame\ncoproparasitológico. No fim do estudo, identificou-se que 800 crianças não faziam uso de água\nencanada. Foram detectadas 150 crianças com cistos de Giardia lamblia, sendo que, dentre elas,\n60 não faziam uso de água encanada. O valor da medida de associação para o risco de se adquirir\ngiardíase quando se usa água não-encanada e o número de casos de giardíase que podem ser\natribuídos ao uso da água não-encanada são, respectivamente:","options":{"A":"1,33 e 0,019.","B":"3,00 e 0,075.","C":"0,75 e 1,900.","D":"3,00 e 1,900."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-274799","number":"274799","sourceNumber":"274799","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considerando que o exame de urocultura pode demorar até 5 dias para ter o resultado,\nfoi realizado um estudo com 1000 gestantes\nassintomáticas para verificar a utilidade do uso da\npesquisa de nitrito em amostra de urina no rastreamento de bacteriuria, utilizando a urocultura\ncomo padrão-ouro. O estudo mostrou que 50 gestantes tinham urocultura positiva. Dentre 115\ngestantes que apresentavam nitrito positivo, 95 eram falso positivos. Já entre as 885 que\napresentaram pesquisa de nitrito negativa, 30 eram falso negativos. Marque a afirmação correta.","options":{"A":"A acurácia do teste nessa população é de aproximadamente 40%.","B":"A especificidade do teste é de aproximadamente 40%.","C":"O valor preditivo positivo é de aproximadamente 17%.","D":"A sensibilidade do teste é de aproximadamente 83%."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-282022","number":"282022","sourceNumber":"282022","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A saúde atualmente tem se pautado nas evidências Científicas, não diferente a política\ntem embutido em suas ações as evidências\ncientíficas publicadas. As evidências vividas ou\nsituações observadas servem para apoiar, refutar ou modificar uma hipótese, teoria científica ou\ntomada de decisão, não sendo uma conclusão, e sim um dos pilares nos quais uma conclusão é\nsustentada. Pensando no tema saúde baseada em evidência para a formulação de políticas de\nsaúde, assinale a alternativa correta.","options":{"A":"A opinião de autores da síntese de evidências é a melhor orientação, contribuindo para resolver\nproblemas ou dúvidas particulares sobre políticas.","B":"Não contribui para que o processo de formulação de políticas seja sistemático e transparente,\nvisto que a justificativa para a escolha não é\nclaramente explicitada.","C":"Auxilia a colocar temas na agenda de gestão, entregando alternativas de abordagem de um\nproblema ou tema de políticas.","D":"Equidade, aplicabilidade e custo-efetivo são pontos mínimos que devem ser descritos para\nenfrentamento de um problema utilizando evidências científicas."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-274803","number":"274803","sourceNumber":"274803","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O RECOVERY Trial foi um estudo realizado para avaliar a eficácia de medicamentos\ncom potencial para tratamento de pacientes\nhospitalizados com COVID-19. Um dos braços do\nestudo avaliou o benefício do uso de dexametasona em pacientes com ventilação invasiva. Foram\nrandomizados 1007 pacientes. 324 para dexametasona e 683 para placebo. O estudo teve óbito\ncomo desfecho avaliado. Houve 95 mortes nos pacientes que usaram dexametasona e 283 no\ngrupo controle. Marque a afirmação correta.","options":{"A":"O risco relativo foi de aproximadamente 30%.","B":"O número necessário para tratar (NNT) foi de aproximadamente 33.","C":"Houve apenas redução do risco relativo sem redução no risco absoluto de morte.","D":"A redução do risco absoluto foi de aproximadamente 12%."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-282030","number":"282030","sourceNumber":"282030","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A Epidemiologia é uma importante ferramenta da Atenção Primária à Saúde, pois a\npartir dos dados coletados, sistematizados e\ncorrelacionados com a evidência em saúde e a história\nnatural se tomam decisões em ações para uma determinada população. Há várias variáveis que\ndevemos levar em consideração para a tomada de uma decisão em saúde. Utilizando os\nconhecimentos sobre teste diagnóstico e ocorrência de uma doença, complete o quadro:","options":{"A":"A: Verdadeiro-positivo, C: Falso-negativo: Sensibilidade.","B":"B: Falso-positivo; D: Verdadeiro-negativo: Sensibilidade.","C":"A: Verdadeiro-positivo, B: Falso-negativo: Sensibilidade.","D":"C: Falso-positivo, D: Verdadeiro-negativo: Sensibilidade."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-282033","number":"282033","sourceNumber":"282033","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Há diversos preceitos a serem seguidos por médicos e o Código de Ética Médica é a lei\nque regimenta as condutas dos profissionais da área. Sendo assim, ao se infringir qualquer artigo\nnele contido, há penalidades previstas. A Bioética é a interdisciplinaridade entre os princípios\néticos\nque regem a vida quando essa é colocada em risco pela medicina ou pelas ciências. Não faz parte\ndos princípios bioéticos:","options":{"A":"Justiça.","B":"Maleficência.","C":"Beneficência.","D":"Autonomia."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-277473","number":"277473","sourceNumber":"277473","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um teste de triagem em estudo tem o resultado disposto no quadro abaixo. Considere\nVPP= valor preditivo positivo e VPN= valor\npreditivo negativo. Qual a alternativa correta quantos\naos seus índices para avalição da viabilidade do teste:","options":{"A":"sensibilidade=73,4% e especificidade=71,28%","B":"VPP=74,43% e VPN=73,9%","C":"VPP=71,28% e especificidade=70,65%","D":"sensibilidade=70,65% e especificidade=74,44%"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-277474","number":"277474","sourceNumber":"277474","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma fato observável e mensurável de uma população de indivíduos comparáveis é que\nmuitas vezes apresentam características em uma frequência modelada por uma distribuição\nnormal. É o exemplo da altura humana em uma determinada idade (separados entre homens e\nmulheres), ou o tamanho do bico de uma população de aves como os pássaros estudados por\nCharles Darwin. Em uma curva de distribuição normal (Gaussiana), qual é aproximadamente a\nporcentagem de dados que está a 2 desvios-padrão (dp) da média (intervalo representado pela\nletra X na figura)?","options":{"A":"66,00%","B":"68,30%","C":"95,40%","D":"99,80%"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-273204","number":"273204","sourceNumber":"273204","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os estudos epidemiológicos podem ser classificados em dois grupos: os estudos\nobservacionais e os estudos experimentais.\nQuanto às características dos estudos observacionais,\né CORRETO afirmar:","options":{"A":"É o estudo onde o investigador interfere em quem é ou não é exposto à condição ou\ncaracterística de interesse.","B":"Nesse estudo, a exposição ao experimental ocorre de forma independente à realização do\nestudo.","C":"É o estudo onde há um grupo de comparação, aumentando, assim, a qualidade da evidência\ngerada.","D":"Nesse estudo, quem determina quem recebe ou não a exposição é o investigador, pois os\nparticipantes não seriam expostos à intervenção de interesse."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-277479","number":"277479","sourceNumber":"277479","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"É considerada uma vantagem do estudo Caso-Controle:","options":{"A":"Não é susceptível ao viés de memória","B":"Permite randomizar os indivíduos para os grupos dos casos e controles","C":"Produz estimativa de incidência da doença","D":"É útil para estudar doenças raras"},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-277484","number":"277484","sourceNumber":"277484","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere um estudo epidemiológico que tenha medido as variáveis: faixa etária, sexo,\npeso ao nascer (alto ou baixo), cor da\npele. Essas variáveis podem ser classificadas,\nrespectivamente, como:","options":{"A":"Nominal, nominal, contínua e descontínua","B":"Ordinal, nominal, nominal, nominal","C":"Nominal, ordinal, ordinal, contínua","D":"Ordinal, dicotômica, contínua e nominal"},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-273213","number":"273213","sourceNumber":"273213","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um ensaio clínico, controlado e ao ocaso, com recém-nascidos prematuros de uma\nmaternidade, foi realizado com o intuito de avaliar os efeitos da musicoterapia nos índices de\naleitamento materno, obtendo-se os seguintes resultados: o aleitamento materno foi\nsignificativamente maior no grupo da musicoterapia na 1ª consulta do segmento (RR=1,26;\nIC=95%=1,01-1,57; P=0,06), bem como por ocasião da alta do bebê (RR=1,22; IC 95%=0,99-1,51;\np=0,06). (fonte: J. Pediatria 2011). Diante o exposto conclui-se:","options":{"A":"A variável independente desse ensaio clínico, apresentou um incremento de 26% no risco do\naleitamento materno no grupo que sofreu a intervenção.","B":"O estudo buscou estabelecer o quanto a introdução da variável (aleitamento) afetou a variável\nresposta (musicoterapia).","C":"Por ocasião da alta do bebê, a variável independente influenciou de forma estatisticamente\nsignificativa na variável resposta.","D":"O ensaio foi realizado com grupos distribuídos de acordo com critérios clínicos, uma vez que foi\nrealizado de forma controlada."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-277487","number":"277487","sourceNumber":"277487","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"As condições de saneamento básico persistem como desafio no que se refere à\ncobertura populacional no Brasil, com implicações\ndiretas em diversos índices de saúde. Em 2014\nUm grupo de pesquisadores avaliou nos estados brasileiros a associação entre condições de\nsaneamento (cobertura populacional por redes de abastecimento de água, por sistemas de\nesgotamento sanitário e por serviços de coleta de lixo) e indicadores epidemiológicos (taxa de\nmortalidade infantil, mortalidade proporcional por doença diarreica aguda em menores de um ano e\nmortalidade proporcional por doenças infecciosas e parasitárias no mesmo grupo). Para isso os\npesquisadores utilizaram os dados secundários do banco de dados Indicadores e Dados Básicos\npara a Saúde 2014 ? IDB 2014 ? do Ministério da Saúde. A partir do enunciado assinale o tipo de\nestudo que se refere:","options":{"A":"Coorte","B":"Ecológico","C":"Caso controle","D":"Transversal"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-277488","number":"277488","sourceNumber":"277488","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considerando uma distribuição não normal de dados qual seria a medida mais indicada\na ser utilizada para representar a tendência\ncentral?","options":{"A":"Média","B":"Desvio padrão","C":"Mediana","D":"Coeficiente de regressão"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-277489","number":"277489","sourceNumber":"277489","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A pesquisa epidemiológica está sujeita a uma grande quantidade de erros, que podem\ncomprometer a validade e confiabilidade de seus resultados. Tais erros podem ser denominados\naleatórios ou sistemáticos (vieses). Quando diferentes grupos de indivíduos estudados são\nsubmetidos a critérios diagnósticos diferentes entre si e que, portanto, apresentam qualidade\ndiagnóstica variável, estamos potencialmente diante de um viés de:","options":{"A":"Confusão","B":"Aferição","C":"Seleção","D":"Montagem"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-273218","number":"273218","sourceNumber":"273218","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A epidemiologia e as informações geradas pelos estudos epidemiológicos têm diversas\naplicações. Quanto à contribuição dos estudos epidemiológicos, é INCORRETO afirmar:","options":{"A":"Estudam a história da saúde de populações em curtos períodos e projeta as tendências futuras.","B":"Diagnosticam os níveis de saúde de uma comunidade, permitindo definir quais áreas necessitam\nde intervenção e as prioridades nas ações de\nsaúde.","C":"Investigam o funcionamento dos serviços de saúde, como estes são utilizados pela clientela e\nqual sua eficácia com relação aos objetivos originais.","D":"Estimam, em média, os riscos individuais de doenças, acidentes ou defeitos congênitos."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-273219","number":"273219","sourceNumber":"273219","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considerando as explicações alternativas nas interpretação de associações em estudos\nepidemiológicos, a mistura e os efeitos em que a aparente associação entre uma exposição de\ninteresse e uma doença é, na verdade, devida a uma terceira variável, associada à exposição\ninvestigada e, por si mesma, um fator de risco independente para aquela doença, é denominada:","options":{"A":"Chance.","B":"Viés.","C":"Bias.","D":"Confusão."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-235838","number":"235838","sourceNumber":"235838","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O estudo científico caracterizado por distribuir pacientes em diferentes grupos com o\nobjetivo de se estudar os resultados de diferentes intervenções terapêuticas representa:","options":{"A":"uma meta-análise.","B":"um caso-controle.","C":"um coorte.","D":"uma série de casos."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-249859","number":"249859","sourceNumber":"249859","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os valores seguintes se referem ao peso de recém-nascidos em quilogramas: 2,9; 4,0;\n2,1; 2,8; 3,2; 3,0; 3,1; 3,2; 3,5; 3,2. O resultado do cálculo da mediana desses valores é:","options":{"A":"3,0.","B":"3,10.","C":"3,15.","D":"3,20."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-249860","number":"249860","sourceNumber":"249860","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em 1991, três pesquisadores realizaram um estudo com o objetivo de investigar a\nassociação entre o uso materno de cocaína e a ocorrência de prematuridade. Utilizaram como fonte\nde dados um banco de registros perinatais de uma universidade. Todos os registros de\nnascimentos ocorridos durante o ano de 1988 foram inicialmente revisados para a obtenção das\ninformações sobre o uso de cocaína pela mãe. Foi verificada posteriormente a associação com o\nrisco de prematuridade ao final da gestação. O delineamento do estudo foi:","options":{"A":"caso-controle.","B":"prevalência.","C":"ecológico.","D":"coorte não concorrente."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-249861","number":"249861","sourceNumber":"249861","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo transversal, foram encontrados os seguintes dados: O resultado da\nrazão de prevalência nesse estudo foi de","options":{"A":"0,5.","B":"1,0.","C":"1,5.","D":"2,0."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-249862","number":"249862","sourceNumber":"249862","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma das avaliações do impacto das ações de saúde refere-se aos efeitos alcançados\nem relação ao esforço despendido, em termos de\nrecursos e tempo utilizado. É o resultado que se\nobtém, tendo em conta os insumos empregados. Trata-se, assim, da","options":{"A":"efetividade.","B":"eficiência.","C":"eficácia.","D":"acurácia."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-232244","number":"232244","sourceNumber":"232244","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"São ensaios iniciais de investigação clinica do efeito do tratamento, constituindo\ninvestigações em pequena escala da eficácia e\nsegurança da droga, com monitoramento cuidadoso\nde cada paciente; são estudos-piloto de eficácia. No caso das vacinas, o foco é sobre a\nimunogenicidade. Raramente vai além de 100-200 pacientes por droga. Tais características se\nreferem à","options":{"A":"fase I dos Ensaios Clínicos.","B":"fase II dos Ensaios Clínicos.","C":"fase III Ensaios Clínicos.","D":"fase IV dos Ensaios Clínicos."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-232247","number":"232247","sourceNumber":"232247","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo caso-controle hipotético mostrou que o uso de anticoncepcional oral (ACO)\naumentava o risco de trombose venosa profunda (TVP). A medida de associação foi igual a 3,4.\n\nTodavia, muitos pesquisadores aventaram a possibilidade de que os resultados desse estudo não\neram válidos devido à existência de viés, com\no seguinte argumento: \"mulheres que usam ACO e\napresentam sintomas de TVP procuram assistência médica com mais frequência do que mulheres\ncom TVP que não usam ACO\". Qual seria a medida de associação desse estudo? E assumindo-se\nque a argumentação dos pesquisadores é verdadeira, se o viés de seleção presente no estudo\nfosse corrigido, o valor dessa medida de associação tenderia a","options":{"A":"odds ratip ? diminuir.","B":"risco relativo ? não se modificar.","C":"odds ratio ? aumentar.","D":"risco relativo ? aumentar"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-232248","number":"232248","sourceNumber":"232248","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na bioestatística, valores de x que dividem uma série ordenada de dados em quatro\ngrupos, cada um reunindo 25% das observações, são:","options":{"A":"as modas.","B":"as medianas.","C":"os quartis.","D":"as somas dos postos."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-231978","number":"231978","sourceNumber":"231978","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Na década de 1960, ainda não estava perfeitamente comprovada a associação entre\ncâncer de pulmão e tabagismo. Os tipos de estudos que finalmente estabeleceram isso foram:","options":{"A":"estudos seccionais e ensaios clínicos","B":"estudos de coortes e relatos de caso","C":"relato de caso e estudos seccionais","D":"caso-controles e estudos de coorte","E":"ensaios clínicos e caso-controles"},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-232252","number":"232252","sourceNumber":"232252","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um médico de família ministrou uma droga anti-hipertensiva para estudar o efeito do\ntratamento sobre o nível de hipertensão arterial sistêmica em um mesmo grupo de pacientes\nhipertensos, nos quais foi aferida a pressão arterial antes do início e em vários momentos após a\nintrodução do medicamento. É uma característica desse estudo:","options":{"A":"ser um estudo \"\"antes e após\"\".","B":"ser observacional.","C":"ser randomizado.","D":"ser mascarado."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-234352","number":"234352","sourceNumber":"234352","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um médico avalia uma pesquisa sobre um tratamento medicamentoso de uma doença\nfrequente no seu território de atuação. Os resultados encontrados foram: pacientes tratados com o\nmedicamento e tiveram cura da doença: 75%; pacientes tratados com um placebo e tiveram cura\nda doença: 30%. Então, a redução relativa do risco foi de:","options":{"A":"0,35 ou 35%.","B":"0,45 ou 45%.","C":"0,55 ou 55%.","D":"0,65 ou 65%."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-229861","number":"229861","sourceNumber":"229861","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A epidemiologia clínica introduz métodos para estabelecer diagnósticos, estimar\nprognósticos, reconhecer fatores de risco e\ndecidir sobre a eficácia, a efetividade e a eficiência de\nintervenções terapêuticas. Sobre a epidemiologia clínica, assinale a alternativa INCORRETA.","options":{"A":"A decisão do médico de solicitar um exame diagnóstico pressupõe que o resultado pode\nmodificar de forma relevante a probabilidade de a doença estar presente ou ausente.","B":"Um teste diagnóstico com uma alta especificidade pode ser muito útil para o rastreamento em\numa população assintomática, porque possui baixo\nrisco de resultados falso-negativos.","C":"O número necessário para tratar (NNT) informa quantas pessoas necessitam receber o\ntratamento para possibilitar um bom desfecho (ou evitar desfecho ruim).","D":"A probabilidade de que uma doença exista antes de um teste diagnóstico ser realizado é\nchamada de probabilidade pré-teste."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-234355","number":"234355","sourceNumber":"234355","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um investigador interessado em estudar o álcool como fator de risco para cirrose\nhepática realizou um estudo epidemiológico.\nForam selecionados para o estudo 14 casos e 28\ncontroles. Dentre os casos, seis tinham história prévia de uso de bebida alcoólica e, dentre os\ncontroles, cinco tinham história prévia de uso de bebida alcoólica. O Odds Ratio (OR) foi igual a\n3,45 com intervalo de confiança de 95%, variando de 0,67 a 18,59. Teste x² = 3,02 (p=0,082). A\ninterpretação desses resultados indica que:","options":{"A":"Os expostos ao álcool apresentaram 3,45 vezes menor chance de desenvolver cirrose hepática\ndo que os não expostos ao álcool.","B":"A associação foi estatisticamente significativa ao nível de alfa = 0,05 (p = 0,082).","C":"O intervalo de confiança ampliado se relaciona a um pequeno tamanho da amostra (a estimativa\né pouco precisa).","D":"O estudo é uma coorte não concorrente."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-229862","number":"229862","sourceNumber":"229862","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A Medicina Baseada em Evidências é uma abordagem médica que integra a melhor\nevidência atual, a experiência clínica e os valores das pessoas para otimizar os desfechos clínicos\ne a qualidade de vida. Sobre a Medicina Baseada em Evidências pode-se afirmar que","options":{"A":"as revisões sistemáticas, fontes secundárias de evidência, analisam os problemas\nmetodológicos dos estudos primários e possibilitam\nachados mais confiáveis para a tomada de\ndecisão do profissional.","B":"o médico na sua tomada de decisão deve priorizar os estudos que avaliam desfechos baseados\nem alterações dos exames complementares, pois\nsão estudos com menor risco de vieses.","C":"a evidência proporcionada pela experiência de um médico deve ser considerada do mesmo nível\nda evidência proporcionada por um estudo realizado de forma sistemática.","D":"os sumários (guias de prática clínica), como o UpToDate, o Dynamed e o BMJ Best Practice,\nnão são recomendados como informação rápida na\ndecisão clínica do médico."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-234356","number":"234356","sourceNumber":"234356","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Quanto maior a sensibilidade de um teste diagnóstico, maior será","options":{"A":"Seu valor preditivo negativo.","B":"Sua probabilidade pré-teste.","C":"Sua especificidade.","D":"Seu valor preditivo positivo."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-247451","number":"247451","sourceNumber":"247451","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um ensaio clínico randomizado controlado por placebo analisou os efeitos do uso da\ndroga A125 para prevenção de AVC. Os indivíduos do estudo foram divididos entre grupo\ntratamento (100 pacientes) e grupo placebo (150 pacientes). Após 5 anos de seguimento foram\nobservados 5 casos de AVC no grupo tratamento e 15 casos no grupo placebo. Com base nesse\nestudo, é correto afirmar:","options":{"A":"O NNT (Número Necessário para Tratar) encontrado pelo estudo foi 10 e redução do risco\nrelativo foi de 5%.","B":"Não é possível calcular o NNT, já que existe menos pessoas no grupo tratamento do que no\ngrupo placebo.","C":"o NNT encontrado pelo estudo foi 20 e redução absoluta do risco foi 5%.","D":"A redução do risco relativo foi 5% e a redução absoluta do risco foi 50%."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-247452","number":"247452","sourceNumber":"247452","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Devido à baixa disponibilidade de doppler vasculares em UBS e à grande utilidade da\nmedição do Índice Tornozelo Braquial (ITB) para diagnóstico de doença arterial periférica, foi\nrealizado um estudo para comparar a acurácia do ITB medido apenas com esfigmomanômetro e\nestetoscópio. A tabela abaixo mostra os resultados do estudo que teve o ITB medido por doppler\ncomo padrão ouro. É considerado correto:","options":{"A":"a acurácia do teste foi de 87,6%.","B":"a sensibilidade foi de 91% e portanto o teste pode ser usado como rastreamento.","C":"a especificidade foi de 62,5% e portanto 37,5% dos doentes teriam um diagnóstico falso positivo.","D":"o valor preditivo negativo foi de 75% e, portanto, houve 25% de falsos negativos."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-247456","number":"247456","sourceNumber":"247456","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"O rastreamento de agentes infecciosos em doadores de sangue é imprescindível, pela\npossibilidade de contaminação dos receptores do sangue doado. A evolução dos testes\ndiagnósticos possibilita uma maior acurácia nesses exames. Considerando-se que o ônus de se\ndeixar de fazer o diagnóstico nesses casos é alto, utiliza-se um método de:","options":{"A":"alta especificidade.","B":"alto valor preditivo negativo.","C":"alta sensibilidade.","D":"alto valor preditivo positivo."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-248980","number":"248980","sourceNumber":"248980","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale a alternativa que apresenta, corretamente, os tipos de estudos observacionais\nadequados para investigar o risco de desenvolver uma doença ou evento adverso à saúde:","options":{"A":"ensaios clínicos aleatórios controlados e estudos eco-lógicos","B":"ensaios clínicos aleatórios controlados e estudos de coorte","C":"estudos de corte transversal e estudos do tipo caso-controle","D":"estudos de coorte e estudos do tipo caso-controle"},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-248982","number":"248982","sourceNumber":"248982","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em uma distribuição de dados semelhantes à curva normal, quantas observações se\nestimam encontrar, aproximadamente, entre ±2 desvios-padrão?","options":{"A":"16%.","B":"34%.","C":"68%.","D":"95%."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-248983","number":"248983","sourceNumber":"248983","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A capacidade de um teste diagnóstico de detectar os verdadeiros positivos é conhecida\ncomo:","options":{"A":"sensibilidade","B":"especificidade","C":"valor preditivo positivo","D":"variância"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-252809","number":"252809","sourceNumber":"252809","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"\"Paulo, 35 anos anos de idade, procura atendimento com seu médico de família na\nUBS Santos Silva, que fica próxima à sua casa.\nConseguiu atendimento para o dia seguinte.\n\nChegou à UBS e passou pela triagem com a Técnica Maria, que reforçou a necessidade de\nacompanhar a pressão arterial. Enquanto\naguardava na recepção o atendimento do seu médico.\nDr. Guilherme, foi abordado pela enfermeira Juliana que reforçou a presença dele na próxima\nconsulta de sua esposa, que está grávida. Paulo relata que tem trabalhado muito, mas irá se\nprogramar, visto que o bebê chega em 3 meses. Dr. Guilherme chama Paulo, na recepção, e após\ncumprimento afável Dr. Guilherme pergunta em que poderá ajudar. Paulo refere que iniciou uma\ndor no estômago tipo \"queimação\" que melhora após comer. Diz ter sensação de empachamento\ndurante todo o dia, como se estivesse cheio. Nega emagrecimento, mas relata que aumentou de\npeso após ter parado de fumar, há aproximadamente 06 meses. Ele relata que as fezes estão com\naspecto normal, não tem outras queixas. Relembra que seu avô paterno faleceu em decorrência de\num câncer gástrico e que o pai sofre de gastrite crônica, por isso resolveu procurar o médico. Ao\nexame físico, não apresenta nenhuma alteração significativa\". A saúde baseada em evidência\ncompõe estratégias diagnósticas, sendo assim, qual a alternativa correta?","options":{"A":"Para usar um teste diagnóstico na prática clínica, é fundamental conhecer o quanto esses testes\ndiferenciam pessoas que têm a doença ou condição suspeita das que não têm.","B":"Idealmente, a habilidade de um teste em identificar corretamente pacientes com e sem uma\ndoença específica deveria variar.","C":"Se você é um clínico, ainda que intuitivamente, compreende que um teste precisa ter um melhor\ndesempenho quando é utilizado para avaliar pacientes com uma doença menos avançada do que\npacientes com uma doença grave.","D":"Testes diagnósticos são necessários quando a doença é clinicamente evidente, assim como\nnaquelas situações em que a doença é muito pouco provável."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-241772","number":"241772","sourceNumber":"241772","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Quanto mais específico um teste, maior será o/a:","options":{"A":"Valor preditivo positivo.","B":"Valor preditivo negativo.","C":"Sensibilidade.","D":"Intervalo de confiança.","E":"Risco relativo."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-248987","number":"248987","sourceNumber":"248987","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considere as afirmativas a seguir, quanto à validade de um teste diagnóstico: I -\nSensibilidade é a capacidade de o teste acertar em indivíduos com aquela doença. II -\nEspecificidade é a capacidade de o teste acertar em indivíduos sem aquela doença. IIl - Testes\nsensíveis têm poucos falsos negativos. IV - Testes específicos têm poucos falsos positivos, Estão\ncorretas:","options":{"A":"l,ll","B":"l,lll","C":"ll, IV","D":"l, ll, lll, lV"},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-248988","number":"248988","sourceNumber":"248988","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Para a investigação de associações etiológicas em doenças de baixa incidência, qual\ndos estudos a seguir é o mais indicado?","options":{"A":"Coorte.","B":"Ecológico.","C":"Caso-controle.","D":"Seccional"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-248993","number":"248993","sourceNumber":"248993","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um ensaio clínico randomizado foi realizado entre os indivíduos com diabetes. Entre os\n100 indivíduos alocados para tratamento, houve\n1 caso de pé diabético e, entre 100 alocados para\nplacebo, houve 2 casos. Qual é o Número Necessário para Tratar (NNT) para previnir um único\ncaso de pé diabético entre indivíduos com as características desse estudo?","options":{"A":"50","B":"25","C":"10","D":"100"},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-218211","number":"218211","sourceNumber":"218211","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sobre análise exploratória de dados, assinale a alternativa correta:","options":{"A":"Na anaásibilidade de descrever o perfil de um conjunto de dados.","B":"A diferença entre escala intervalar e escala de razão é que o valor nulo na escala de razão não\ncorresponde à ausência da característica medida.","C":"A escala nominal é formada por categorias que descrevem atributos ou qualidades dos dados.","D":"As variáveis quantitativas discretas apresentam valores numéricos fracionários e a variável pode\napresentar qualquer valor pertencente ao conjunto dos números reais."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-201730","number":"201730","sourceNumber":"201730","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Considerando os testes diagnósticos, o valor preditivo positivo:","options":{"A":"Aumenta com a elevação da prevalência da doença da especificidade do teste.","B":"Diminui com a elevação da prevalência da doença e da especificidade do teste.","C":"Aumenta com a elevação da incidência da doença e da sensibilidade do teste.","D":"É inviável em relação à prevalência ou incidência da doença, e em relação à sensibilidade ou\nespecificidade do teste."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-201733","number":"201733","sourceNumber":"201733","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em se tratando das medidas de tendência central, o valor que ocupa a posição central\nde um conjunto de dados ordenados define a:","options":{"A":"Média.","B":"Mediana.","C":"Moda.","D":"Variância."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-201656","number":"201656","sourceNumber":"201656","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Quando a associação entre a exposição e o desfecho observada na população de\nestudo for diferente daquela que seria verificada caso fossem estudados todos os individuos da\nbase populacional, constata-se no estudo um viés de:","options":{"A":"Informação.","B":"Memória.","C":"Seleção.","D":"Confundimento."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-201661","number":"201661","sourceNumber":"201661","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um ensaio clínico, a diferença entre a incidência do desfecho no grupo controle e a\nincidência do desfecho no grupo tratado equivale:","options":{"A":"Ao rísco relativo.","B":"Ao número necessário para tratar.","C":"À redução absoluta do risco.","D":"À redução relativa do risco."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-202670","number":"202670","sourceNumber":"202670","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Para a amostra de dados de hematócrito: 45,43, 45, 46, 52, 50, 47, 44, 51, a mediana\né:","options":{"A":"44.","B":"45.","C":"46.","D":"47."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-201950","number":"201950","sourceNumber":"201950","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Com intuito de estudar características de risco para determinada doença e para a\nprodução de medidas de incidência, foram selecionados jovens para participar de estudo\nepidemiológico que se prontificaram a serem acompanhados. O tipo de estudo em questão é:","options":{"A":"corte transversal","B":"caso-controle","C":"coorte prospectiva","D":"seccional","E":"duplo cego"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-202687","number":"202687","sourceNumber":"202687","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma pesquisa foi realizada para investigar a relação entre exposição à emissão de\npartículas aéreas produzidas pelas indústrias químicas e de petróleo e a incidência anual de\ndoença pulmonar obstrutiva crônica (DPOC) entre moradores de uma localidade em Minas Gerais.\nÁreas dessa localidade foram classificadas de acordo com os níveis de poluentes. A incidência de\nDPOC foi calculada para cada área de exposição. O delineamento desse estudo foi:","options":{"A":"coorte.","B":"ecológico.","C":"caso-controle.","D":"transversal."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-202702","number":"202702","sourceNumber":"202702","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os funcionários de uma empresa são convidados a preencher um questionário que\ninclui o detalhamento das atividades\nfísicas no trabalho e nos momentos de lazer. Dois grupos são,\nentão, formados, um de sedentários e outro de funcionários que se exercitam regularmente. Após\n15 anos, observou-se que a incidência de doença coronariana foi maior no grupo de sedentários do\nque no grupo de não sedentários. O delineamento desse estudo foi:","options":{"A":"caso-controle.","B":"transversal.","C":"coorte.","D":"ecológico."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-202710","number":"202710","sourceNumber":"202710","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo transversal de distribuição da infecção pelo vírus da hepatite B e fator de\nrisco para essa infecção, 1.000 pessoas foram entrevistadas, tendo sido coletadas as amostras de\nsangue delas. Dessas pessoas, 160 eram usuárias de drogas injetáveis e tinham anticorpos\npositivos para o vírus, 400 eram usuárias de drogas injetáveis, 400 pessoas não eram usuárias de\ndrogas injetáveis e não tinham anticorpos positivos para o vírus. A razão de prevalência nesse\nestudo é de:","options":{"A":"2,21.","B":"1,88.","C":"2,88.","D":"1,21."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-202715","number":"202715","sourceNumber":"202715","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A acurácia de um teste é a proporção de","options":{"A":"verdadeiros positivos entre todos os doentes.","B":"verdadeiros positivos entre todos os indivíduos com teste positivo.","C":"todos os casos da doença antes da realização do teste.","D":"acertos de um teste diagnóstico."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-202623","number":"202623","sourceNumber":"202623","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os testes em paralelo","options":{"A":"são solicitados geralmente quando o clínico necessita de um diagnóstico rápido como, por\nexemplo, em situações de emergência.","B":"aumentam a capacidade de se afastar a doença quando ela está ausente.","C":"são utilizados geralmente nos processos diagnósticos que não requerem urgência, como no\ncaso dos pacientes ambulatoriais para\ninvestigação diagnóstica, que são acompanhados durante\num determinado período.","D":"diminuem a capacidade de se detectar a doença quando ela está de fato presente."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-216529","number":"216529","sourceNumber":"216529","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A epidemiologia clínica, termo derivado de suas disciplinas mães -- medicina clínica e\nepidemiologia-- fornece métodos para, por exemplo, estabelecer diagnósticos, estimar\nprognósticos, reconhecer fatores de risco e decidir sobre a eficácia, efetividade e eficiência de\nintervenções terapêuticas e preventivas.","options":{"A":"2-4-1-3.","B":"4-2-3-1.","C":"1-3-2-4.","D":"3-1-4-2."},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-216517","number":"216517","sourceNumber":"216517","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Assinale o termo que NÃO é um princípio bioético:","options":{"A":"Justiça.","B":"Autonomia.","C":"Não maleficência.","D":"Benevolência."},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-216625","number":"216625","sourceNumber":"216625","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A epidemiologia clínica utiliza métodos epidemiológicos já consagrados no estudo de\npopulações para melhorar o diagnóstico e o manejo de pacientes considerados individualmente.\nAssim a probabilidade pós-teste de um agravo à saúde de baixa prevalência em ambulatório de\natenção primária à saúde é:","options":{"A":"Alta.","B":"Indeterminada.","C":"Baixa.","D":"Dependente do valor preditivo."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-214914","number":"214914","sourceNumber":"214914","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Um estudo caso-controle foi conduzido para avaliar a associação entre o uso de álcool\npara fins de limpeza doméstica e a ocorrência de queimaduras graves em idosos. Essa informação\nfoi relatada por 56 dos 94 casos e por 63 dos 148 idosos do grupo-controle. Qual é a medida de\nassociação estimada no estudo?","options":{"A":"risco relativo: 2,93","B":"razão de chances (odds ratio): 1,99","C":"razão de chances (odds ratio): 2,93","D":"razão de prevalência: 2,93"},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-214931","number":"214931","sourceNumber":"214931","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Com relação às medidas de frequência em estudos epidemiológicos, é correto afirmar\nque:","options":{"A":"a prevalência de uma doença varia conforme a sua incidência, sua duração e os movimentos\nmigratórios","B":"a prevalência de uma doença é função direta da sazonalidade, isto é, a magnitude de uma\ndoença varia exclusivamente com o aparecimento\ndos casos novos do agravo","C":"a prevalência e a incidência são conceitos antagônicos","D":"a incidência de uma doença é caracteristicamente calculada em estudos transversais"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-214950","number":"214950","sourceNumber":"214950","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"A randomização é uma técnica de alocação que visa:","options":{"A":"impedir que indivíduos sem critérios de elegibilidade sejam incluídos no estudo","B":"evitar perdas seletivas de acompanhamento que levem a resultados enviesados","C":"garantir a distribuição homogênea de características prognósticas entre os grupos comparados","D":"garantir que os alocados em diferentes grupos de tratamento recebam a mesma qualidade de\nassistência"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-214955","number":"214955","sourceNumber":"214955","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Com relação ao viés em pesquisas clínicas, analise as assertivas a seguir, conforme\ndescrito por Fletcher (2006): I - O viés de\nseleção ocorre quando são feitas comparações entre\ngrupos de pacientes que diferem em outros determinantes do desfecho, além do que está sendo\nestudado. II - O viés de aferição ocorre quando os métodos de aferição são iguais entre os grupos\nde pacientes. III - O viés de confusão ocorre quando 2 fatores estão associados e seus efeitos não\nse\n\nconfundem. Está(ão) correta(s):","options":{"A":"apenas I","B":"apenas III","C":"II, III","D":"I,II,III"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-214957","number":"214957","sourceNumber":"214957","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo analítico, no qual há comparação entre os grupos estudo e controle, qual\ndos parâmetros a seguir não é levado em conta para o calculo amostral?","options":{"A":"o nível de significância estatística","B":"o valor do poder da amostra","C":"o tamanho da população de estudo","D":"a estimativa da taxa do desfecho em um dos grupos"},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-214962","number":"214962","sourceNumber":"214962","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Uma pesquisa foi realizada a fim de investigar a prevalência do suicídio na\nadolescência, mediante a aplicação de um\nquestionário com perguntas fechadas, avaliando\nvariáveis demográficas, socioeconômicas e comportamentais associadas ao desfecho. A seleção\nda população foi realizada mediante uma seleção probabilística. Como esse estudo poderia ser\nclassificado?","options":{"A":"ecológico","B":"caso-controle","C":"coorte","D":"transversal"},"answer":"D","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-214966","number":"214966","sourceNumber":"214966","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Sobre os estudos epidemiológicos, assinale a alternativa correta:","options":{"A":"o estudo de coorte prospectiva é menos sujeito a vieses de memória quanto à exposição ao fator\nde risco do que um estudo caso-controle","B":"o estudo caso-controle possibilita calcular o risco relativo de uma doença diretamente,\ncomparando expostos e não expostos a determinado fator de risco","C":"estudos ecológicos permitem avaliar se a exposição de indivíduos a determinado fator aumenta\no risco de determinado desfecho","D":"em um estudo caso-controle, pessoas expostas e não expostas a determinado fator são\nseguidas no tempo para avaliar a incidência de um determinado desfecho"},"answer":"A","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-215430","number":"215430","sourceNumber":"215430","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Os resultados das análises de meta regressão sugerem que a terapia com aspirina\npode estar associada a uma diminuição do AVC\nentre as mulheres diabéticas e uma diminuição do\nIAM entre os homens diabéticos, e que as reduções de risco obtidas com baixas doses (75 mg/dia)\nforam tão grandes quanto às obtidas com doses mais elevadas (650 mg/dia). Assim, podemos\nconcordar com o item:","options":{"A":"O estudo concluiu que a baixa dose de aspirina não era benéfica para a prevenção primária da\nDCV e que a decisão sobre um tratamento com\naspirina deveria ser feita individualmente. Os\nefeitos da terapia com aspirina variaram por sexo e diabetes.","B":"O estudo concluiu que a baixa dose de aspirina era benéfica para a prevenção primária da DCV\ne que a decisão sobre um tratamento com\naspirina deveria ser feita individualmente. Os efeitos da\nterapia com aspirina variaram por sexo e diabetes.","C":"O estudo concluiu que a baixa dose de aspirina era benéfica para a prevenção primária da DCV\ne que a decisão sobre um tratamento com\naspirina não deveria ser feita individualmente. Os efeitos\nda terapia com aspirina variaram por sexo e diabetes.","D":"O estudo concluiu que a baixa dose de aspirina era benéfica para a prevenção primária da DCV\ne que a decisão sobre um tratamento com\naspirina deveria ser feita individualmente. Os efeitos da\nterapia com aspirina não variaram por sexo e diabetes."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-173561","number":"173561","sourceNumber":"173561","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo epidemiológico cujo objetivo é responder se a chance de desenvolver a\ndoença no grupo dos expostos é maior do que\nno grupo de não expostos, a medida de associação\na ser estimada é","options":{"A":"a redução do risco relativo.","B":"o odds ratio.","C":"a razão de prevalência.","D":"o risco atribuível."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-173564","number":"173564","sourceNumber":"173564","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em um estudo epidemiológico que visa avaliar a associação entre o nível de atividade\nfísica e a mortalidade, é possível que a\nidade interfira na relação entre a exposição e o efeito por\nser uma variável de","options":{"A":"seleção.","B":"sobrevivência.","C":"confundimento.","D":"memória."},"answer":"C","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-preventiva-pre-2-174162","number":"174162","sourceNumber":"174162","collectionBlock":"medcurso:medcurso-preventiva-pre-2","collectionLabel":"Medcurso · PRE 2","documentBlock":"","area":"Medicina Preventiva","specialty":"Medicina Preventiva","topic":"PRE 2","subtopic":"","stem":"Em uma análise de nível individual, o valor de cada variável é assinalado para cada\nsujeito no estudo. Em qual análise, todas\nas variáveis são medidas agrupadas, não discriminando,\npor exemplo, os indivíduos expostos que adoeceram?","options":{"A":"De prevalência.","B":"Ecológica.","C":"De incidência.","D":"Experimental."},"answer":"B","source":"Preventiva/PRE 2/PRE 2.txt","sourceLabel":"Medcurso · PRE 2","images":[],"optionImages":{},"commentImages":[],"tags":["Medicina Preventiva","PRE 2","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
